//  正本: マイドライブ/テリオンアニメ/台本_ギリシャ編_22話版/第NN話.md。直す時は台本を直してから抜き出し直す(python story/gr22_update.py)。
const GR_EP={};
const GR_BT={};
GR_SC.g01_01=[{w:null,t:"まっ暗な石の通路。"},{w:null,t:"奥から、大きな生き物の寝息のような低い音。"},{w:null,t:"寝息に合わせて、天井から砂がひとすじ、さらさらと落ちる。"},{w:null,t:"世界のどこかの地面の下では、大昔の生き物が、まだ眠っている。",v:"01_0028"}];
GR_SC.g01_02=[{w:null,t:"青い海ぞいの坂道。"},{w:null,t:"白いロボタクシーが一台、坂を下っていく。"},{w:null,t:"車の中。男の子が一人、手首の画面にかじりついている。"},{w:null,t:"画面の中は、テリオンどうしの勝負の配信。"},{w:null,t:"黒いコートの少年と、岩の鱗の大きな蛇。"},{w:null,t:"画面のすみで、小さな話し相手のマークが、まばたきしている。"},{w:null,t:"ヤマトの体が、画面の勝負に合わせて、右へ、左へかたむく。"},{w:"hero",t:"そこだ……右！　右だって！",v:"01_0040"},{w:null,t:"ヤマトの足が、前の座席を、どかっとける。"},{w:"hero",t:"いけーっ！",v:"01_0042"},{w:"x",n:"車の声",t:"お客さま。座席を、けらないでください。",v:"01_0043"},{w:"hero",f:"sad",t:"あ、ごめん。",v:"01_0044"},{w:null,t:"画面の上に、通知がぽんと出る。"},{w:null,t:"研究所で生まれた生き物「テリオン」は、世界じゅうの町で、人と暮らしている。",v:"01_0053"},{w:"hero",f:"serious",t:"……止めて。",v:"01_0056"},{w:"hero",t:"止めて止めて、止めて！",v:"01_0057"},{w:"x",n:"車の声",t:"停車します。完全に止まるまで、お待ちくだ——",v:"01_0058"},{w:"x",n:"車の声",t:"——さい。",v:"01_0061"}];
GR_SC.g01_03=[{w:null,t:"ギリシャ。オリーブの村、オリーヴァ。",v:"01_0065"},{w:null,t:"白い家の坂道に、屋台が並ぶ。"},{w:null,t:"値段は、品物の上に浮かぶ光る字。"},{w:null,t:"ヤマト、スーツケースを引いて、坂をかけ上がってくる。"},{w:null,t:"オリーブの屋台のおばさん。"},{w:"x",n:"屋台のおばさん",t:"あんた、ひとりかい？　そんな大荷物で、どこから来たの。",v:"01_0070"},{w:"hero",t:"日本から！",v:"01_0071"},{w:"hero",t:"ねえおばちゃん、この村、テリオンいっぱいいる？",v:"01_0072"},{w:null,t:"おばさん、坂の上を指さす。"},{w:null,t:"さっきの牛の子が、のっそり屋台の前を通る。"},{w:"hero",f:"smile",t:"すっげー……本物だ。",v:"01_0075"},{w:null,t:"ヤマト、牛の子のおなかへ、そうっと手をのばす。"},{w:null,t:"牛の子のしっぽが、ぺしっ。"},{w:null,t:"牛の子は、ふり向きもせずに、坂をのぼっていく。"},{w:"x",n:"屋台のおばさん",t:"ほら、オリーブお食べ。腰をぬかすのは、まだ早いよ。",v:"01_0079"},{w:null,t:"ヤマト、オリーブを一つつまむ。"},{w:null,t:"紺色の毛に、オレンジのえりまき。二本のしっぽの先で、火がゆれる。"},{w:null,t:"口いっぱいに、オリーブ。"},{w:"x",n:"屋台のおばさん",t:"あっ、また、あの泥棒！　こらー！　今日はいくつ持ってった！",v:"01_0083"},{w:"hero",f:"surprised",t:"なにあれ！？　しっぽ、燃えてんじゃん！",v:"01_0084"},{w:null,t:"坂の下で、急ブレーキの音。"},{w:null,t:"ドアに、オレンジの角の丸い四角の輪。"},{w:null,t:"うしろの荷物の部屋に、鉄のおり。"},{w:null,t:"降りてくる二人組。"},{w:null,t:"二人とも手ぶら。"},{w:null,t:"市場の人たちが、さっと道をあける。"},{w:"x",n:"八百屋のおじさん",t:"ヴィクター一味だ……。",v:"01_0092"},{w:"x",n:"屋台のおばさん",t:"あんた、こっちに下がってな。",v:"01_0093"},{w:"x",n:"屋台のおばさん",t:"先週は、パン屋の猫の子が連れていかれた。",v:"01_0094"},{w:null,t:"マルコ、店番の鳥の子を、ひょいとつまみ上げる。"},{w:"marco",t:"これも、もらっとくぜ。",v:"01_0096"},{w:"x",n:"八百屋のおじさん",t:"おい、それはうちの——！",v:"01_0097"},{w:null,t:"ニーナ、鳥の子の首すじを、指でつまんで見せる。"},{w:"nina",t:"首、光ってないじゃない。",v:"01_0099"},{w:null,t:"おじさん、黙る。"},{w:"hero",t:"（小声で）なんで、だれも止めねーの？",v:"01_0101"},{w:"x",n:"屋台のおばさん",t:"（小声で）首が光ってない子は、取られても文句言えないのさ。",v:"01_0102"},{w:"nina",t:"あたしたちの用は、あの狐よ。",v:"01_0103"},{w:"marco",t:"今日こそ、つかまえてやるぜ。",v:"01_0104"},{w:null,t:"ニーナ、手首の画面を動かす。"},{w:null,t:"ドローンの胴にも、同じオレンジの輪。"},{w:"nina",t:"右！　右から回りなさいよ！",v:"01_0107"},{w:"hero",f:"hurt",t:"うわっ、熱っ……！",v:"01_0115"},{w:"hero",t:"あいつ、追っかける！　おばちゃん、荷物見てて！",v:"01_0118"},{w:"x",n:"屋台のおばさん",t:"ちょっと、あんた！　ヴィクターの前に出ちゃだめだって！",v:"01_0119"},{w:null,t:"第1話　狐と焦げたオリーブ",v:"01_0122"}];
GR_SC.g01_04=[{w:null,t:"狐。そのうしろにドローン三機。"},{w:null,t:"そのうしろにヤマト。"},{w:"marco",t:"ニーナ、なんか子どもがついてくるぜ。",v:"01_0130"},{w:"nina",t:"子どもなんか、ほっときなさいよ。狐が先でしょ！",v:"01_0131"},{w:"hero",t:"おーい、待てよー！　ちょっとさわるだけだって！",v:"01_0132"},{w:"x",n:"子ども1",t:"あの子、ヴィクター一味より速いよ！",v:"01_0133"},{w:null,t:"ドローンが網を落とす。"},{w:null,t:"網は日よけの上に、ばさっ。狐、下からしっぽの小さな火。"},{w:"marco",t:"あー！　また網、燃やされた！",v:"01_0136"},{w:"nina",t:"うるさい！　次は、屋根のない所よ！",v:"01_0137"},{w:null,t:"狐のしっぽが、今度はヤマトに向く。"},{w:"hero",f:"hurt",t:"あちっ！　……今の見た！？　火、とばした！",v:"01_0139"},{w:"x",n:"子ども2",t:"あぶないって！",v:"01_0140"},{w:"hero",t:"いいって！　火だぞ、火！",v:"01_0141"},{w:null,t:"狐の口から、半分焦げたオリーブが一つ落ちる。"},{w:null,t:"ヤマト、走りながら拾って、ポケットに入れる。"},{w:null,t:"狐、石垣の下の細いすき間を、するっとくぐる。"},{w:null,t:"ヤマトも、腹ばいになって、すき間をくぐる。"},{w:null,t:"マルコも頭からつっこむ。……肩で、つかえる。"},{w:"nina",t:"なにやってんのよ！",v:"01_0147"},{w:"marco",t:"ぬ、抜けねえ……！",v:"01_0148"},{w:null,t:"すき間の上で、ドローン三機が、ぐるぐる回っている。"}];
GR_SC.g01_05=[{w:null,t:"村の上の、古い神殿のあと。",v:"01_0152"},{w:null,t:"倒れた柱と、神殿の石の床。"},{w:null,t:"向こうのはしに、オリーブの林。"},{w:null,t:"野原のまん中に、一本だけ、幹の太い大きなオリーブの木。"},{w:null,t:"いちばん下の枝が、地面の近くまで、横に長く張り出している。"},{w:null,t:"根もとには、落ちて乾いたオリーブの葉と実が、ふかふかに積もっている。"},{w:null,t:"狐、その木の根もとに逃げこむ。くわえたオリーブを、しっぽの火の上へ。"},{w:"hero",t:"おまえ、ここが好きなのか？",v:"01_0165"},{w:"hero",t:"大丈夫、おれ、あいつらの仲間じゃないから。",v:"01_0166"},{w:"hero",t:"ほら、なんにもしないって。",v:"01_0167"},{w:"hero",t:"よーし、いい子だ。そのまま、そのまま……。",v:"01_0169"},{w:"hero",f:"hurt",t:"いってえ！",v:"01_0171"}];
GR_SC.g01_06=[{w:null,t:"石段の下から、ごろごろと音。"},{w:null,t:"白い上着に、水色のブラウスと、ひざ下のプリーツスカート。"},{w:null,t:"金の長いウェーブの髪に、白いリボン一つ。"},{w:null,t:"肩かけカバンに、丸いぬいぐるみの飾り。"},{w:"elly",t:"あ、いたいた！　ねえ、これ、きみのでしょ？",v:"01_0183"},{w:"elly",t:"オリーブのおばさんから、預かってきたよ。",v:"01_0184"},{w:"hero",t:"あ、おれの！",v:"01_0185"},{w:"elly",t:"……って、ちょっと、その右手！　赤くなってる！",v:"01_0186"},{w:"hero",t:"ああ、これ？　なでようとしたら、ガブッとやられた。",v:"01_0187"},{w:"elly",t:"やられたのに、なんでうれしそうなの。",v:"01_0188"},{w:"hero",t:"だって、本物だぞ！　本物にかまれたんだぞ！",v:"01_0189"},{w:"elly",t:"ほら、すわって！",v:"01_0190"},{w:null,t:"ヤマト、木の根もとに座らされる。"},{w:null,t:"エリー、カバンを開ける。"},{w:"elly",t:"しみるよ。がまんしてね。",v:"01_0193"},{w:"hero",t:"いっ……！　しみる、しみる！",v:"01_0194"},{w:null,t:"エリー、指のつけ根に、ばんそうこうを一枚。"},{w:"hero",t:"（エリーの顔を見て）ありがとな。荷物も。",v:"01_0196"},{w:null,t:"エリー、ばんそうこうの箱を、ぱちんと閉じる。"},{w:"elly",t:"あの子、フォルン。だれにもさわらせないの。",v:"01_0198"},{w:"elly",t:"わたしなんか、三年、毎日クッキー持ってきてるんだよ。",v:"01_0199"},{w:null,t:"根もとの石のくぼみに、クッキーが一枚。"},{w:"hero",t:"フォルンか。かっこいい名前だな！",v:"01_0201"},{w:null,t:"木の上で、フォルンの耳が、ぴくっとこっちを向く。"},{w:null,t:"【プロフィール】フォルン／炎／●○○／しっぽの火で気持ちが分かる"},{w:"elly",t:"本気で怒ると、フレイガっていう火、吹くんだって。",v:"01_0204"},{w:"elly",t:"見たことないけど。",v:"01_0205"},{w:null,t:"木の上のフォルン、ふんと鼻を鳴らす。しっぽの火が、ぼっ。"},{w:null,t:"ヤマトの口が、「フレイガ」の形に動く。"},{w:"elly",t:"フォルン、何回もねらわれてるんだよ。",v:"01_0208"},{w:"hero",f:"serious",t:"……あいつも、首、光ってねーのか。",v:"01_0209"},{w:"elly",t:"野良の子のために、ヴィクターとけんかする人はいないよ。",v:"01_0210"},{w:null,t:"どの首にも、小さな光の点。"},{w:null,t:"八百屋のおじさんの屋台だけ、見張りの止まり木が、空っぽ。"},{w:null,t:"ヤマト、木の上のフォルンを見上げる。だまって、見ている。"},{w:"elly",t:"で、きみは？　観光？",v:"01_0215"},{w:"hero",t:"観光っていうか、テリオン見に来たんだよ。日本にはいねーし。",v:"01_0216"},{w:null,t:"エリーの手が止まる。"},{w:"elly",t:"ちょっと待って。日本から来た男の子って……。",v:"01_0218"},{w:"elly",t:"きみ、もしかして、ヤマト？",v:"01_0219"},{w:"hero",t:"え、なんでおれの名前知ってんの。",v:"01_0220"},{w:"elly",t:"わたし、エリー！　うち、ホテルやってるの！",v:"01_0221"},{w:"elly",t:"きみのおじいちゃんに頼まれて、空港でずっと待ってたんだよ！",v:"01_0222"},{w:"hero",f:"serious",t:"……迎え？　聞いてねえ。",v:"01_0223"},{w:"elly",t:"聞いてねえ、じゃないの！　どこから出たの！",v:"01_0224"},{w:"hero",t:"ふつうに出たよ。",v:"01_0225"},{w:"elly",t:"おじいちゃんから、連絡来てたでしょ？",v:"01_0226"},{w:null,t:"ヤマト、手首の画面をつける。"},{w:null,t:"「わりい、急用。"},{w:"hero",f:"serious",t:"……来てた。",v:"01_0229"},{w:null,t:"言いながら、ヤマトの目は、もう木の上のフォルンにもどっている。"},{w:null,t:"エリー、ヤマトの目の先を追って、ため息。"},{w:null,t:"エリー、となりの倒れた柱の古い字を、指でなぞりはじめる。"},{w:null,t:"手首の画面に、なぞった字が一つずつ写る。"},{w:"hero",t:"なにそれ。",v:"01_0234"},{w:"elly",t:"昔の字。いつか、ぜんぶ読むの。",v:"01_0235"},{w:null,t:"なぞる指は、迷わない。ヤマト、その横顔を見る。"},{w:"hero",t:"ふーん。ぜんぶって、何年かかんだよ。",v:"01_0237"},{w:"elly",t:"わかんない。だから、毎日。",v:"01_0238"}];
GR_SC.g01_07=[{w:null,t:"ブーンと、羽の音。"},{w:null,t:"続いて、ニーナとマルコが、息を切らして石段をのぼってくる。"},{w:null,t:"マルコの肩に、石垣のこけが、べったりついている。"},{w:"marco",t:"はあ、はあ……坂、長すぎだろ……。",v:"01_0247"},{w:"nina",t:"いた。……なんで子どもと一緒にいんのよ。",v:"01_0248"},{w:null,t:"フォルン、木から下りて、身がまえる。耳がうしろに倒れる。"},{w:null,t:"ヤマト、立ち上がる。こぶしをにぎる。"},{w:"nina",t:"ちょっと、そこのチビ。その狐、よこしなさい！",v:"01_0251"},{w:"hero",t:"やなこった！",v:"01_0252"},{w:"nina",t:"へえ。痛い目、見たいわけ？",v:"01_0253"},{w:"marco",t:"ニーナ、網じゃ、また燃やされるぜ。",v:"01_0254"},{w:"nina",t:"分かってるわよ。だから、先に弱らせるの。",v:"01_0255"},{w:null,t:"ドローン三機は、網を下げたまま、丘の上で止まる。"},{w:null,t:"オリーブの林の中から、がさがさと音。"},{w:null,t:"茶色いクマの子が、林のはしに、のそっと出てくる。"},{w:null,t:"頭のてっぺんに、緑の双葉が二枚。"},{w:"nina",t:"出番よ、クマッパ！",v:"01_0260"},{w:null,t:"【プロフィール】クマッパ／森／●○○／力じまんの小さなクマ"},{w:null,t:"フォルン、ヤマトの足もとから、すっと前に出る。"},{w:"hero",f:"serious",t:"……やってくれんのか！　よっしゃ！",v:"01_0264"},{w:"hero",t:"いっけー、フォルン！",v:"01_0265"},{w:"elly",t:"ヤマト、こっち！　下がって！",v:"01_0266"}];
GR_SC.g01_09=[{w:null,t:"柱のかげから、市場の子どもたちが走ってくる。"},{w:"x",n:"子ども1",t:"ヴィクター一味に、勝っちゃった！",v:"01_0359"},{w:"x",n:"子ども2",t:"林から出たら、つる、届いてなかった！",v:"01_0360"},{w:"x",n:"子ども3",t:"泥棒狐、すげー！",v:"01_0361"},{w:null,t:"ニーナ、ひっくり返ったクマッパを抱き上げる。目を回したまま。"},{w:null,t:"ニーナ、焦げた双葉を、指でそっとなでる。"},{w:"nina",t:"よくやったわ。休んでなさい。",v:"01_0364"},{w:null,t:"ニーナ、クマッパを両腕でかかえ直す。"},{w:"nina",t:"覚えてなさいよ、チビ。",v:"01_0366"},{w:"hero",t:"おう、覚えとく。ニンジンだろ？",v:"01_0367"},{w:"nina",t:"誰がニンジンよ！　ニーナよ！",v:"01_0368"},{w:null,t:"マルコ、横を向いて、ぷっとふきだす。"},{w:null,t:"ニーナ、だまってマルコを見る。"},{w:"hero",t:"何回来たって、同じだ！　なあ、フォルン！",v:"01_0371"},{w:null,t:"ヤマト、フォルンの方へ、得意げに親指を立てて見せる。"},{w:null,t:"フォルン、その顔を見上げる。"},{w:null,t:"火が、ヤマトの目の前で、ぽふっ。"},{w:null,t:"ヤマト、胸を張ったまま、まぶたが開かない。"},{w:"hero",t:"おい！　フォルン！　目が開かないよ〜",v:"01_0377"},{w:null,t:"ヤマト、目をつぶったまま、両手で前をさぐる。"},{w:"elly",t:"（笑いをこらえて）……そっち、木だよ。",v:"01_0379"},{w:null,t:"フォルン、ヤマトの前を素通りして、マルコの前へ。しっぽを、ぴんと立てる。"},{w:"marco",t:"あ。",v:"01_0381"},{w:null,t:"ぽっ。マルコのお尻に、小さな火。"},{w:"marco",t:"あちちちちっ！　ニーナーっ！",v:"01_0383"},{w:"nina",t:"マルコ、置いてくわよ！",v:"01_0384"}];
GR_SC.g01_10=[{w:null,t:"夕方。子どもたちは坂を下りていった。"},{w:null,t:"ヤマト、まつ毛のダマを、指でほぐす。やっと、両目が開く。"},{w:null,t:"両手をこすり合わせて、フォルンに手をのばす。"},{w:"hero",f:"smile",t:"やったな、フォルン！　ほら、ちょっとだけ——",v:"01_0392"},{w:null,t:"フォルン、喉の奥で、ぐるる。"},{w:null,t:"ヤマト、手を引っこめる。"},{w:null,t:"引っこめた右手を見る。"},{w:"elly",t:"（小声で）ほら、やっぱり食べない。",v:"01_0404"},{w:"hero",t:"（小声で）しっ。",v:"01_0405"},{w:"hero",f:"serious",t:"……食った。おれの手の上で、食った。",v:"01_0411"},{w:"elly",f:"surprised",t:"うそでしょ……。焦がしたのが好きだったの？",v:"01_0412"},{w:"elly",t:"さ、ホテル行こ。お姉ちゃん、ずっと待ってるから。",v:"01_0416"}];
GR_SC.g01_11=[{w:null,t:"坂の下の黒塗りのロボタクシー。"},{w:null,t:"うしろのおりの中で、さらわれたテリオンたちが鳴いている。"},{w:"marco",t:"ボスに、なんて言うんだよ？",v:"01_0425"},{w:"marco",t:"狐はとれませんでした、って言うのか？",v:"01_0426"},{w:null,t:"ニーナ、手首の画面に、ドローンが撮った写真を出す。"},{w:null,t:"少年の前に立って、しっぽを立てる狐。"},{w:"nina",t:"だれにもなつかない野良が、あのチビの前に出たのよ。",v:"01_0429"},{w:"marco",t:"それって、まずいのか？",v:"01_0430"},{w:"nina",t:"まずいどころじゃないわよ。ボスが一番ほしがる話じゃないの。",v:"01_0431"},{w:"nina",t:"これなら、手ぶらでも怒られないわ。",v:"01_0432"},{w:null,t:"ニーナ、送り先を選ぶ。"}];
GR_SC.g01_12=[{w:null,t:"その夜。坂の上の、小さなホテル。",v:"01_0436"},{w:null,t:"ホテルの一階のはしの、小さな部屋。"},{w:null,t:"机の上に、うすい板のテリオン図鑑。"},{w:"elly",t:"その図鑑、お姉ちゃんが置いといてくれたの。",v:"01_0439"},{w:"elly",t:"「日本の子なら、きっと読むから」って。",v:"01_0440"},{w:"hero",t:"お姉ちゃんって、さっき受付にいた人？",v:"01_0441"},{w:"elly",t:"そう、アナ。このホテル、お姉ちゃんが一人でやってるの。",v:"01_0442"},{w:null,t:"ヤマト、図鑑をひらく。"},{w:null,t:"テリオンのいる国に、色がぬってある。"},{w:null,t:"ヤマト、色のぬってある国を、指で一つずつ、なぞっていく。"},{w:null,t:"ギリシャで、指が一度止まる。"},{w:null,t:"地図のはしの、白い日本で止まる。"},{w:null,t:"ヤマト、色のぬってある国ぜんぶを、手のひらでばんっとたたく。"},{w:"hero",t:"おれ、世界一のテリオンマスターになるんだ。",v:"01_0449"},{w:"elly",f:"serious",t:"……本物見たの、今日が初めてなのに？",v:"01_0450"},{w:"hero",t:"だから、なるんだよ。",v:"01_0451"},{w:null,t:"ヤマト、図鑑を一枚めくる。"},{w:null,t:"見た子の絵が、ぱらぱらと色づいていく。"},{w:null,t:"図鑑のすみに、小さな字。"},{w:null,t:"手首の画面のすみに、昼の配信の切り抜きが一つ、ぽんと出る。"},{w:null,t:"黒いコートの少年と、岩の鱗の大きな蛇。"},{w:null,t:"ヤマト、図鑑を閉じかけた手を止める。"},{w:null,t:"窓の外。ぶどう畑の柵の上に、フォルンが丸くなっている。"},{w:"elly",t:"見て。あの子、ここまでついてきてる。",v:"01_0460"},{w:"hero",t:"友達だからな。",v:"01_0461"},{w:null,t:"柵の上のフォルン、大きく口をあけて、あくび。"},{w:"elly",f:"serious",t:"……友達、あくびしてるよ。",v:"01_0463"},{w:"hero",f:"angry",t:"うっせ。",v:"01_0464"},{w:"hero",t:"エリー、ちょっと見て。",v:"01_0473"},{w:"hero",t:"おれの画面に、知らないアプリが入ってる。",v:"01_0474"},{w:"elly",t:"え、どれ？　どこから来たの？",v:"01_0475"},{w:"hero",t:"……じいちゃんだ。空港で、おれの画面いじってた。",v:"01_0477"}];
GR_SC.g01_13=[{w:null,t:"窓のない暗い部屋。"},{w:null,t:"画面の上に、オレンジの角の丸い四角の輪。"},{w:null,t:"どの子も同じ向き。"},{w:null,t:"並びのいちばん上に、白い字で「しつけ　おわり」。"},{w:null,t:"並びの中に、パンの棚の前で丸くなった、猫の子の写真。"},{w:null,t:"耳のうしろに、チップ。"},{w:null,t:"そのとなりが、一つだけ、空いている。"},{w:null,t:"空いたすき間に、写真が一枚、すっと入る。"},{w:null,t:"少年の前に立って、しっぽを立てる狐。"},{w:null,t:"写真から細い線がのびて、画面のすみの名前の並びの「アレク」で止まる。"},{w:null,t:"「アレク」が、白く光る。"}];
GR_BT[1]={mid:[[{w:"nina",t:"クマッパ、つる！",v:"01_0273"},{w:"hero",t:"もっと近くだ、フォルン！　行け！",v:"01_0280"},{w:"elly",t:"フォルンの足、紫になってる！",v:"01_0284"},{w:"nina",t:"ふふん。",v:"01_0285"},{w:"hero",t:"負けんな、フォルン！　行け！　行けって！",v:"01_0286"}],[{w:"x",n:"子ども2",t:"当たった！",v:"01_0290"},{w:"hero",f:"surprised",t:"逃げたぞ！　追え、フォルン！　追えって！",v:"01_0292"},{w:"elly",t:"ヤマト、だめ！　林の中、つるだらけだよ！",v:"01_0293"},{w:null,t:"ヤマト、林へふり上げていた腕が、だらりと下がる。"},{w:"nina",t:"今よ！　網！",v:"01_0300"},{w:null,t:"ヤマトの目が、倒れたフォルンの先の、低い枝へ行く。"},{w:"hero",t:"（石の床から）フォルン！　木の下！",v:"01_0303"},{w:"nina",t:"あきらめなさい、チビ！",v:"01_0306"}],[{w:"hero",t:"やだね！　こいつは、ぜってー渡さねー！",v:"01_0307"},{w:"nina",t:"ちっ……。",v:"01_0319"},{w:null,t:"エリー、ヤマトのとなりにしゃがむ。"},{w:null,t:"ヤマト、根もとを見る。一回りふくらんだしっぽの火。"},{w:null,t:"ヤマト、自分のひざを、こぶしで一回たたく。"},{w:null,t:"ヤマト、こぶしをひざにのせたまま、動かない。"},{w:null,t:"ヤマト、身を乗り出しかける。……やめる。"},{w:"hero",t:"まだだ、フォルン。そこにいろ。",v:"01_0330"},{w:null,t:"ニーナの目が、それを見る。"},{w:"nina",t:"クマッパ、行きなさい！",v:"01_0334"},{w:"hero",t:"フォルン、フレイガ！",v:"01_0341"},{w:"nina",t:"なにしてんのよ、立ちなさい、クマッパ！",v:"01_0350"}]],post:[{w:null,t:"クマッパ、あおむけにひっくり返る。目がぐるぐる。"},{w:null,t:"枯れ草に火が走りかける。フォルンがしっぽをひと振り。"},{w:"elly",f:"serious",t:"……見ちゃった。",v:"01_0354"},{w:"hero",f:"smile",t:"勝った！！　フォルン、勝ったぞ！",v:"01_0355"}]};
GR_EP[1]={"t": "狐と焦げたオリーブ", "sc": [["g01_01", "地面の下（5秒）", 0], ["g01_02", "海ぞいの坂道・ロボタクシーの中（昼）", 0], ["g01_03", "オリーヴァ村・市場の坂（昼）", 0], ["g01_04", "坂道の追いかけっこ", 0], ["g01_05", "神殿のあとの丘", 0], ["g01_06", "同じ場所・女の子", 0], ["g01_07", "丘・ヴィクター一味", 0], ["g01_08", "勝負", 1], ["g01_09", "勝負のあと", 0], ["g01_10", "手のひらのオリーブ（夕方）", 0], ["g01_11", "黒塗りのロボタクシーの中（夕方）", 0], ["g01_12", "坂の上のホテル・一階のはしの部屋（夜）", 0], ["g01_13", "窓のない部屋（夜）", 0]]};
GR_SC.g02_01=[{w:null,t:"口から水の柱。"},{w:null,t:"その向こうで、二本のしっぽの火が、じゅっと細くなる。"}];
GR_SC.g02_02=[{w:null,t:"その前の日。オリーヴァ村。坂の上のホテルの朝。",v:"02_0054"},{w:null,t:"裏のぶどう畑。"},{w:null,t:"エリーが、パンとオリーブの皿を持ってのぞきこむ。"},{w:"elly",t:"ヤマト？　まさか、ひと晩じゅうここにいたの？",v:"02_0057"},{w:"hero",t:"見張ってたんだよ。",v:"02_0058"},{w:"hero",t:"ヴィクター一味が、また来るかもしれないだろ。",v:"02_0059"},{w:null,t:"フォルン、起き上がる。"},{w:"hero",t:"かっけえ……。",v:"02_0061"},{w:"elly",f:"serious",t:"……ほんとに、焦がしたのが好きなんだね。",v:"02_0062"},{w:null,t:"二階の窓が、ばんと開く。"},{w:"ana",t:"エリー！　お客さんの朝ごはん！　日本の子の分も！",v:"02_0064"},{w:"elly",t:"はーい、お姉ちゃん！",v:"02_0065"},{w:null,t:"第2話　競技場の地下",v:"02_0067"}];
GR_SC.g02_03=[{w:null,t:"ロビー。古いソファと、壁の大きな画面。"},{w:null,t:"ソファでパンをかじるヤマト。"},{w:null,t:"エリーの長い髪のかげから、うす茶色の、まんまるの毛玉が、そっと顔を出す。"},{w:"hero",f:"surprised",t:"うわっ！　なんだそれ、いつからいたんだよ！？",v:"02_0076"},{w:"elly",t:"ずっといたよ。ピリポン。こわがりなの。",v:"02_0077"},{w:null,t:"【プロフィール】ピリポン／雷／●○○／こわがり"},{w:"elly",t:"寝てる時は、さわっちゃだめ。びりってするから。",v:"02_0079"},{w:null,t:"エリー、ピリポンをヤマトのとなりに下ろす。"},{w:null,t:"ピリポン、丸くなる。"},{w:null,t:"ヤマト、エリーを見る。"},{w:null,t:"指先が、毛にふれる。ピリポンの目が、ぱちっと開く。"},{w:null,t:"ヤマトの髪の毛が、まるごと、ぼわっとふくらむ。"},{w:null,t:"もこもこの、まんまるの頭。"},{w:null,t:"ヤマト、指をのばした形のまま。"},{w:"elly",t:"（カウンターから、ふり向いて）……さわったでしょ。",v:"02_0087"},{w:"hero",f:"serious",t:"……ちょっとだけ。",v:"02_0088"},{w:null,t:"画面に赤い枠のお知らせ。"},{w:"hero",t:"（画面の黒い車を見て）この車、あいつらだ！",v:"02_0091"},{w:"ana",t:"パン屋の猫の子も、あいつらよ。",v:"02_0092"},{w:"hero",t:"じゃあ、おれがフォルンの相棒になる！　そしたら守れる！",v:"02_0093"},{w:"ana",t:"相棒は、テリオンの方が選ぶのよ。",v:"02_0094"},{w:"hero",f:"serious",t:"……15さい？　おれ、11だぞ。",v:"02_0098"},{w:"hero",t:"それ出る！　おれ、それ出る！",v:"02_0105"},{w:"elly",t:"その前に、おばあちゃんち！　呼ばれてるの。",v:"02_0106"}];
GR_SC.g02_04=[{w:null,t:"段々のオリーブ畑。"},{w:null,t:"畑のまん中に、石でかこんだ小さなため池。"},{w:null,t:"フォルン、池のふちへ。水に顔を近づける。"},{w:null,t:"池の向こう、丘の頂上に、白い大きな建物のあと。"},{w:"elly",t:"昔の研究所。おばあちゃん、前にあそこで働いてたの。",v:"02_0113"},{w:null,t:"フォルンの耳が、建物の方へ、ぴくっと動く。"}];
GR_SC.g02_05=[{w:null,t:"丘の向こうの、小さな石の家。"},{w:"elly",t:"おばあちゃーん！　つれてきたよ！",v:"02_0118"},{w:null,t:"おばあさん、ヤマトの頭をじっと見る。"},{w:"oba",t:"あらまあ。まんまるだねえ。",v:"02_0120"},{w:null,t:"おばあさんの目が、ヤマトの右手のばんそうこうへ下りる。"},{w:"elly",t:"狐にかまれたの。",v:"02_0122"},{w:"oba",t:"手は狐で、頭はピリポンかい。",v:"02_0123"},{w:"hero",f:"serious",t:"……どっちも、ちょっとさわっただけだって。",v:"02_0124"},{w:null,t:"エリー、口を両手で押さえて、肩をふるわせる。"},{w:null,t:"家の中。研究の記録の板が、どこにでも積んである。"},{w:null,t:"棚の写真。白い建物の前に、白衣の三人。"},{w:null,t:"ヤマト、くしゃくしゃのちらしをテーブルに置く。"},{w:"hero",f:"serious",t:"……白い都、行きたいんだ。",v:"02_0129"},{w:null,t:"おばあさん、ちらしの「だれでも出られます」を見る。それから、ヤマトの手を見る。"},{w:null,t:"ヤマトの手のとなりで、だまって、ちらしのしわを一緒にのばす。"},{w:"oba",t:"……エリー。一緒に行っておいで。",v:"02_0132"},{w:"elly",t:"うん！　行ってくる！",v:"02_0133"},{w:null,t:"ヤマト、のばしたちらしを両手で持って、おばあさんの目を見る。"},{w:"hero",t:"ありがと！",v:"02_0135"},{w:null,t:"おばあさん、返事のかわりに、まんまるの頭をぽんとなでる。"},{w:null,t:"毛が、ふわっとはね返る。"},{w:"hero",t:"（窓にはりついて）……また来てる。",v:"02_0139"},{w:"oba",t:"あしたの夜、森の道から出な。",v:"02_0140"},{w:"oba",t:"……古い形の時計だね。消さずに、大事にしな。",v:"02_0144"}];
GR_SC.g02_06=[{w:null,t:"同じころ、遠くの丘。",v:"02_0148"},{w:null,t:"丘の上。若い男が一人、古い小さな望遠鏡で星を見ている。顔は半分しか見えない。"},{w:null,t:"男の手首の画面が鳴る。マークも顔も名前も出ない。"},{w:"x",n:"画面の声",t:"アレク、急ぎの仕事だ。",v:"02_0151"},{w:"x",n:"画面の声",t:"オリーヴァ村の丘に、狐が一匹いる。",v:"02_0153"},{w:"x",n:"画面の声",t:"昔、逃げた子だ。運べ。",v:"02_0155"},{w:null,t:"画面のすみに、少年の前に立って、しっぽを立てる狐の写真。"},{w:"alek",t:"運ぶのは、狐だけっすか。",v:"02_0157"},{w:"x",n:"画面の声",t:"狐だけだ。払いは、いつもの研究の金に足しておく。",v:"02_0158"},{w:"alek",t:"急ぎなら、二割増しっす。",v:"02_0159"},{w:"x",n:"画面の声",t:"……一割だ。",v:"02_0160"},{w:"alek",t:"……うす。",v:"02_0161"},{w:null,t:"アレク、望遠鏡をのぞいたまま、写真を開かずに、画面を指で消す。"},{w:null,t:"丘のすその古い水路。"},{w:null,t:"水の柱が、はるか向こうの石垣まで届いて、ぴしゃっ。"}];
GR_SC.g02_07=[{w:null,t:"次の日。村の外れの、三千年前の競技場。",v:"02_0170"},{w:null,t:"石の入口のアーチ。"},{w:null,t:"土手の日かげで、案内のロボットと観光客の一団が休んでいる。"},{w:null,t:"エリーは、案内のロボットのとなりで、観光客に水を配る手伝い。"},{w:"hero",t:"エリー、かけっこしようぜ。向こうの端まで。",v:"02_0174"},{w:"elly",f:"serious",t:"……いいよ。よーい……ドン！",v:"02_0175"},{w:null,t:"ヤマト、エリーの前に出る。前だけ見て、にっと笑う。"},{w:null,t:"その横を、フォルンが追いぬく。しっぽの火が、ヤマトの鼻先をかすめる。"},{w:null,t:"ヤマト、のけぞって、足がもつれる。"},{w:null,t:"土手の一団から拍手。"}];
GR_SC.g02_08=[{w:null,t:"正午。",v:"02_0182"},{w:null,t:"エリーの手首の画面が、ぴこんと鳴る。"},{w:null,t:"「お姉ちゃん　黒いドローンが、うちの上を回ってる。"},{w:null,t:"ヤマト、土手の下のフォルンをふり返る。"},{w:"hero",f:"serious",t:"……フォルンはここだ。だいじょぶ。",v:"02_0186"},{w:"elly",f:"serious",t:"……うん。お姉ちゃん、強いから。",v:"02_0187"},{w:null,t:"ヤマト、手首の画面を見る。"},{w:"elly",t:"今度は、開くんじゃない？",v:"02_0189"},{w:null,t:"ヤマト、アイコンを、指でとんと押す。"},{w:null,t:"手首の画面から光が広がって、宙に地図になる。"},{w:"hero",t:"この真下……何かあんの？",v:"02_0195"},{w:"hero",f:"serious",t:"……ちょっと、中を見てくるだけ。",v:"02_0198"}];
GR_SC.g02_09=[{w:null,t:"競技場の、真下。",v:"02_0203"},{w:null,t:"ひんやりした石の通路。フォルンのしっぽの火が明かりになる。"},{w:null,t:"つきあたりに、大きな石の扉。"},{w:null,t:"扉のふちに、細かい文字がびっしり。"},{w:null,t:"ヤマト、首をうんと反らして、角のてっぺんを見上げる。"},{w:"elly",f:"serious",t:"……これ、古いギリシャの字だ。",v:"02_0208"},{w:null,t:"エリー、文字を指でなぞって、声に出して読む。"},{w:"elly",f:"surprised",t:"えっとね……ここで寝てる子、起こさないでね、だって。",v:"02_0210"},{w:null,t:"エリーの声が、通路にひびいて、消える。"},{w:null,t:"……足の下の、ずっと深い所から、低い音が一つだけ返ってくる。"},{w:null,t:"ヤマトは角を見上げ、エリーは羽の色をさわっている。"},{w:null,t:"フォルンの耳だけが、ぴくっと床の方を向く。"},{w:null,t:"ヤマト、扉に手をのばしかける。"},{w:null,t:"通路のずっとうしろ。曲がり角の暗がりに、卵のからをかぶったワニの子の目が二つ、光る。"},{w:null,t:"フォルンが、ヤマトと扉のあいだに、すっと入る。耳をうしろに倒して、喉の奥で低くうなる。"},{w:"elly",t:"フォルンが怒ってる。……今日は帰ろ。",v:"02_0218"},{w:"hero",f:"serious",t:"……分かったよ。でも、また来るからな。",v:"02_0219"}];
GR_BT[2]={mid:[[{w:"alek",t:"立ち入り禁止って、入口の看板に書いてあったやろ。",v:"02_0225"},{w:"hero",f:"serious",t:"……読んでない。",v:"02_0226"},{w:"alek",t:"×の絵ぐらい見いや。",v:"02_0227"},{w:"elly",t:"わたし、ぜんぶ読めたよ。奥の扉のも。",v:"02_0228"},{w:null,t:"アレク、石の台についていた手を、はなす。"},{w:null,t:"エリーの顔を、はじめて、まっすぐ見る。"},{w:null,t:"アレクの目が、ヤマトの足もとのフォルンに止まる。"},{w:"alek",t:"その狐、置いていき。仕事なんや。",v:"02_0232"},{w:"hero",t:"こいつが行くって言ったらな。",v:"02_0233"},{w:null,t:"ヤマト、一歩も引かない。"}],[{w:"alek",t:"ほな、力ずくで運ぶで。",v:"02_0235"},{w:null,t:"アレク、手首の画面を指で一回たたく。"},{w:"elly",t:"そのドローン、ヴィクター一味のだよ！",v:"02_0237"},{w:null,t:"アレク、ドローンの胴の輪を見上げる。ほんの一瞬、目が止まる。"},{w:null,t:"アレク、目をもどす。"},{w:"hero",t:"お前、あの赤い髪の女の仲間か！",v:"02_0240"},{w:"alek",t:"ちゃう。おれは運ぶだけや。",v:"02_0241"},{w:"hero",t:"エリー、下がってろ。",v:"02_0242"},{w:null,t:"ヤマトとエリー、通路の出口の石の壁ぎわまで下がる。"},{w:"elly",t:"ピリポン！　もどって！",v:"02_0245"},{w:null,t:"エリー、一歩出かけて、止まる。ピリポンから目をはなせない。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"}],[{w:"alek",t:"3か。……ちっこいな。",v:"02_0253"},{w:"hero",f:"surprised",t:"ちっこくねえ！",v:"02_0254"},{w:"hero",t:"フォルン、水路に近よるな！",v:"02_0256"},{w:"hero",t:"右のはしからだ！",v:"02_0257"},{w:null,t:"アレク、画面を指ではじく。"},{w:"hero",t:"なんで、あんな遠くまで……！",v:"02_0262"},{w:"hero",t:"近くだ！　近くで吹け！",v:"02_0265"},{w:null,t:"ヤマト、こぶしをにぎる。"},{w:null,t:"アレク、画面に指をのせる。"}],[{w:"elly",t:"ピリポン！",v:"02_0274"},{w:null,t:"エリーが飛び出しかける。"},{w:"hero",t:"出るな！　水が来る！",v:"02_0277"},{w:null,t:"アレク、画面から指をはなす。"},{w:"alek",t:"……撃つな。",v:"02_0279"},{w:null,t:"ヤマト、エリーの腕をつかんだまま、フォルンを見る。"},{w:"hero",t:"フォルン、たのむ！　ピリポンを！",v:"02_0281"},{w:null,t:"アレク、それを見ている。"},{w:"alek",t:"……終わらせるで。",v:"02_0290"},{w:null,t:"アレク、画面をはじく。"},{w:"hero",t:"フォルン！",v:"02_0294"}]],post:[{w:null,t:"ヤマト、エリーの腕をはなす。"},{w:null,t:"アレクの手首の画面が、ぶるっとふるえる。"},{w:"alek",t:"はい。狐は、網の中です。",v:"02_0298"},{w:"alek",t:"それと、女の子が、地下の古い字を読みました。",v:"02_0299"},{w:null,t:"返事が来ない。"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……狐は、まだ運ぶな。",v:"02_0302"},{w:"x",n:"画面の声（アレクの耳の中）",t:"今夜、その娘と一緒にだ。",v:"02_0303"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……放しておけ。",v:"02_0304"},{w:null,t:"アレクの、画面にのせていた指が止まる。"},{w:null,t:"通話が切れる。"},{w:null,t:"アレク、画面を一回たたく。"},{w:"elly",f:"serious",t:"……今の、わたしのこと？",v:"02_0308"},{w:"alek",t:"気のせいや。",v:"02_0309"},{w:"hero",f:"serious",t:"……なんで、やめんだよ。",v:"02_0310"},{w:"alek",t:"……用事、できたんや。",v:"02_0311"},{w:null,t:"ヤマト、フォルンのぬれた毛から、水路の水へ目を移す。"},{w:"hero",f:"serious",t:"……水ん中だと、あいつ、強えな。",v:"02_0313"},{w:null,t:"アレク、水路のふちを軽くたたく。"},{w:null,t:"エリー、ピリポンを抱いて走ってくる。"},{w:null,t:"フォルンの目が、ぐるぐるから、ゆっくりもどる。"},{w:null,t:"エリーの腕の中で、ピリポンが首をのばす。"},{w:"elly",f:"serious",t:"……ありがとう、フォルン。",v:"02_0318"},{w:null,t:"ヤマト、林の方へ遠ざかるワニの子のあごを、だまって見ている。"},{w:"hero",t:"次は勝つ。",v:"02_0320"},{w:"elly",t:"次って……。またあの人とやる気？",v:"02_0321"},{w:"hero",t:"あいつだけじゃねえ。もっと強えやつとも、全部だ。",v:"02_0322"},{w:"elly",f:"serious",t:"……おととい言ってた、世界一ってやつ？",v:"02_0323"},{w:null,t:"ヤマト、ひざの泥もはらわずに、胸を張る。"},{w:"hero",t:"ああ。白い都で、まず一番だ！",v:"02_0325"},{w:"elly",f:"serious",t:"……ひざ、泥だらけで言われても。",v:"02_0326"},{w:null,t:"ヤマト、ひざの泥を、ばんばんとはらう。"},{w:null,t:"はらった泥が、少しはなれたフォルンの鼻先まで飛ぶ。"},{w:null,t:"火の粉が一つ、ヤマトのひざに、ぽっ。"},{w:null,t:"ヤマト、背中のリュックの横ポケットから、くしゃくしゃのちらしを引きぬく。"}]};
GR_EP[2]={"t": "競技場の地下", "sc": [["g02_01", "先に一瞬（10秒）", 0], ["g02_02", "ホテルの裏・ぶどう畑のはし（朝）", 0], ["g02_03", "ロビー（朝）", 0], ["g02_04", "丘の上・ため池と研究所あと（昼）", 0], ["g02_05", "おばあさんの家（昼）", 0], ["g02_06", "どこかの丘（夜）", 0], ["g02_07", "古代の競技場（次の日・昼前）", 0], ["g02_08", "土手の上（正午）", 0], ["g02_09", "地下の扉", 0], ["g02_10", "通路の出口・土手のすその空き地", 1]]};
GR_SC.g03_01=[{w:null,t:"同じ日の夕方。村の裏の森。",v:"03_0039"},{w:null,t:"小川べりの平たい岩に、背の高い若い男が一人、ひざを立てて座っている。"},{w:null,t:"小川の中を、頭に卵のからをかぶった緑のワニの子が、ぐるぐる回って泳いでいる。"},{w:null,t:"ワニの子が、岸の白っぽい乾いた石の上へ上がる。"},{w:null,t:"男、かばんから、やわらかく煮た魚の包みを出す。"},{w:null,t:"手首の画面が、ぶるっとふるえる。"},{w:"x",n:"受付の女の声",t:"お待ちください。おつなぎします。",v:"03_0045"},{w:"x",n:"画面の声",t:"アレク。日が落ちたら、狐と娘を連れてこい。",v:"03_0047"},{w:"x",n:"画面の声",t:"狐がなついている男の子も、一緒にな。",v:"03_0048"},{w:"alek",t:"……男の子も、ですか。",v:"03_0049"},{w:"alek",t:"受けたのは、狐一匹の運びだけっす。",v:"03_0050"},{w:"alek",t:"子どもまで、なんでです？",v:"03_0051"},{w:"x",n:"画面の声",t:"理由は、お前の仕事じゃない。",v:"03_0052"},{w:"alek",t:"子ども運んだら、運びの仕事やなくなります。",v:"03_0053"},{w:"x",n:"画面の声",t:"……アレク。",v:"03_0054"},{w:"x",n:"画面の声",t:"そのワニ、こちらで、いつでも止められる。",v:"03_0055"},{w:"x",n:"画面の声",t:"……運べ。",v:"03_0057"},{w:null,t:"通話が切れる。"},{w:null,t:"ワニの子が、男のひざに、ぬれた頭をのせる。"},{w:null,t:"男、ワニの子の頭に手を置く。"},{w:null,t:"第3話　夜の森",v:"03_0063"}];
GR_SC.g03_02=[{w:null,t:"その夜。",v:"03_0069"},{w:null,t:"ホテルの裏口。"},{w:null,t:"塀の上に、フォルン。"},{w:"hero",t:"（戸のすきまへ、小声で）エリー、もう二十分だぞ。",v:"03_0072"},{w:null,t:"戸の向こうで、引き出しを開ける音。"},{w:null,t:"塀の上のフォルン、大きなあくび。"},{w:"hero",f:"serious",t:"……先、行ってるからな。",v:"03_0075"},{w:null,t:"ヤマト、フォルンのあとを歩きだす。"},{w:null,t:"裏口の戸が、ばんと開く。"},{w:"elly",t:"（小声で）待ってってば！　まだ髪、結んでないのに！",v:"03_0078"},{w:null,t:"エリー、黒のチェックのフリルのブラウスに、うすい色の細身のデニム。"},{w:null,t:"走りながら結んだ髪が、高いポニーテールになる。"},{w:null,t:"白い小さな肩かけカバン。"},{w:"hero",t:"……エリー、脇にはさんでる、でっかいの、なに？",v:"03_0082"},{w:"elly",t:"虫よけ。夜の森、すごいんだから。",v:"03_0083"},{w:"hero",t:"アナさんに言わなくていいのか？",v:"03_0087"},{w:"elly",t:"言ったら、ぜったい止められるもん。",v:"03_0088"},{w:"elly",t:"お姉ちゃんには、あした電話する。",v:"03_0089"}];
GR_SC.g03_03=[{w:null,t:"ぶどう畑を抜けた先の、暗い森。"},{w:null,t:"かえるの声。"},{w:"elly",t:"わあ……きれい。",v:"03_0096"},{w:null,t:"ヤマトは、光る板を見たまま。"},{w:null,t:"光る板のまわりに、羽虫がわっと集まる。"},{w:"hero",t:"うわ、来んな！",v:"03_0099"},{w:null,t:"エリー、スプレーをかまえて、明かりのまわりに、ぷしゅー。"},{w:null,t:"フォルンだけは、森の奥をじっと見ている。耳が前を向いている。"},{w:null,t:"小川べりの平たい岩。"},{w:null,t:"ヤマト、顔を上げて、止まる。"},{w:"hero",f:"serious",t:"……また、お前かよ。",v:"03_0104"},{w:"hero",t:"いつから、ここにいたんだよ。",v:"03_0105"},{w:"alek",t:"夕方から、ずっとここで待っててん。",v:"03_0106"},{w:"alek",t:"車の通らへん道、ここしかないやろ。",v:"03_0107"},{w:null,t:"男、望遠鏡から目をはなさない。"},{w:null,t:"低い空に、赤い星が一つ。"},{w:"hero",f:"serious",t:"……望遠鏡で、何見てんだよ。",v:"03_0110"},{w:"alek",t:"星や。今夜はよう晴れてるしな。",v:"03_0111"},{w:"hero",t:"星って、どの星だよ。いっぱいあるだろ。",v:"03_0112"},{w:"alek",t:"赤いやつや。……それ以上は、有料やで。",v:"03_0113"},{w:"hero",t:"なんだよ、それ。教えてくれたっていいだろ！",v:"03_0114"},{w:null,t:"男、望遠鏡の筒をていねいにちぢめて、かばんにもどす。"}];
GR_SC.g03_04=[{w:"alek",t:"その狐、こっちに渡しや。",v:"03_0118"},{w:"hero",t:"昼みたいには、いかねえぞ。",v:"03_0119"},{w:"hero",t:"で、昼の「用事」って、何だよ。",v:"03_0120"},{w:"alek",t:"まだ運ぶなって言われたんや。",v:"03_0121"},{w:null,t:"アレク、手首の画面を消しかける。"},{w:"elly",f:"serious",t:"……やっぱり、昼の電話、わたしのことだ。",v:"03_0124"},{w:"alek",t:"（画面を消して）……気のせいやなかったわ。",v:"03_0125"},{w:"hero",t:"エリーまで連れてって、どうすんだよ。",v:"03_0126"},{w:"alek",t:"知らん。仕事の相手に聞け。",v:"03_0127"},{w:"hero",t:"やっぱ一味じゃん。フォルン売る気だろ。",v:"03_0128"},{w:null,t:"ヤマト、アレクをにらむ。"},{w:"alek",t:"うっさいな。こっちにも、断れへんわけがあるんや。",v:"03_0130"},{w:"elly",t:"その子も、そのお仕事してるの？",v:"03_0131"},{w:"alek",t:"こいつは関係ないやろ。仕事の話に、こいつを入れんな。",v:"03_0132"},{w:"hero",t:"その子連れて仕事してんだろ。関係あるじゃん。",v:"03_0133"},{w:"alek",t:"……ほな、関係あるかどうかも、勝負で決めよか。",v:"03_0134"},{w:"alek",t:"おれが勝ったら、狐とお前らを連れていくで。",v:"03_0135"},{w:"hero",f:"smile",t:"おれもかよ。じゃあ、おれが勝ったら？",v:"03_0136"},{w:"alek",t:"おれは黙って帰るわ。",v:"03_0137"},{w:"alek",t:"仕事の相手には「森にはだれも来なかった」って言うとくわ。",v:"03_0138"},{w:null,t:"男の目が、ヤマトの顔に止まる。それから、はなれる。"},{w:"elly",t:"ねえ、その子、なんか変だよ。",v:"03_0140"},{w:"elly",t:"耳のうしろ、何か光ってる。",v:"03_0141"},{w:"hero",t:"光ってる？　……どこだよ。",v:"03_0142"},{w:null,t:"エリー、しゃがんで、ワニの子の耳のうしろをのぞく。"},{w:"elly",t:"（ワニの子に）ここ、痛くない？　お名前は？",v:"03_0144"},{w:null,t:"アレクの目が、一瞬だけ、ワニの子の耳のうしろへ行く。"},{w:"alek",t:"名前は、おれに勝てたら教えたるわ。",v:"03_0146"},{w:"hero",t:"じゃあ、勝って聞く。昼の分も、返す。",v:"03_0147"}];
GR_SC.g03_05=[{w:null,t:"ヤマト、光る板を手前の切り株の上に置く。"},{w:null,t:"右を、小川が奥から手前へまっすぐ流れている。"},{w:null,t:"男、ワニの子を小川に放す。"},{w:null,t:"エリーは、小川を見ている。"},{w:null,t:"火花が、石を伝って、小川の水の上で、ぱちっと光る。"},{w:null,t:"ピリポン、びっくりして、エリーの髪にもぐる。"},{w:"elly",t:"ピリポン。こわかったら、そこの石のかげにいて。",v:"03_0157"},{w:"elly",t:"それだけでいいから。",v:"03_0158"},{w:null,t:"ピリポン、エリーの腕をつたって、草の上に、ぽてっと下りる。"},{w:"alek",t:"二体で来いや。",v:"03_0162"},{w:"elly",t:"ピリポンは、かくれてるだけだよ。",v:"03_0163"},{w:"alek",t:"ほな、それでええ。",v:"03_0164"},{w:"hero",t:"フォルン、根もとだ！　おとといの、あれだ！",v:"03_0165"},{w:"alek",t:"……始めよか。",v:"03_0168"}];
GR_SC.g03_07=[{w:null,t:"ヤマト、両手のこぶしを空へ突き上げる。"},{w:null,t:"ピリポン、固まっている。"},{w:"elly",t:"ピリポン、すごいよ……！",v:"03_0252"},{w:null,t:"アレク、ひっくり返ったワニの子のそばにひざをつく。あごに、手をそえる。"},{w:null,t:"耳のうしろのうろこのすき間から、割れたチップの半分が、ころっと落ちる。"},{w:"elly",t:"その黒いの、なに？",v:"03_0255"},{w:"alek",t:"仕事の相手が入れさせたもんや。",v:"03_0256"},{w:null,t:"アレク、かけらを指でつまんで、月あかりにかざす。"},{w:"alek",t:"……割れてもうたな。",v:"03_0258"},{w:"hero",t:"さっきの雷か？",v:"03_0259"},{w:"alek",t:"やろな。川ごと、しびれよったし。",v:"03_0260"},{w:null,t:"乾いた草の上で、ワニの子の背中のうろこが、白っぽくかわいていく。"},{w:null,t:"アレク、うろこから目を上げて、ヤマトを見る。"},{w:"alek",t:"乾くと、こいつ弱なるねん。",v:"03_0263"},{w:null,t:"ヤマト、小川へ走る。"},{w:"alek",t:"お前、何してんねん。",v:"03_0265"},{w:"hero",t:"かわいてんじゃん、こいつ。",v:"03_0266"},{w:null,t:"アレク、それを見ている。割れたチップをにぎった手が、ひざの上で止まっている。"},{w:null,t:"エリーも、ピリポンを肩にのせて、両手で水をすくいに走る。"},{w:null,t:"三回目の水がかかった時、ワニの子が目を開ける。"},{w:null,t:"アレク、割れたチップをにぎった手を、しばらく開かない。"},{w:"hero",f:"smile",t:"……勝ったぞ。約束だからな。",v:"03_0271"},{w:"alek",t:"おう。今夜は、狐は運ばへん。",v:"03_0272"},{w:"hero",t:"今夜は、って何だよ。",v:"03_0273"},{w:"alek",t:"仕事をやめたわけやない。",v:"03_0274"},{w:"elly",t:"その子にチップを入れた人の仕事、まだやるの？",v:"03_0275"},{w:"alek",t:"金がいるんや。",v:"03_0276"},{w:"hero",t:"金って……。",v:"03_0277"},{w:"alek",t:"でかい買いもんや。",v:"03_0278"},{w:null,t:"アレク、割れたチップを、パーカーのポケットにしまう。"},{w:null,t:"アレク、ぐったりしたワニの子を抱き上げる。"},{w:"elly",t:"その子、休ませなきゃ。",v:"03_0281"},{w:"elly",f:"serious",t:"……うち、すぐそこだから。",v:"03_0282"},{w:"hero",t:"（ワニの子を見て）……もどるか。こいつ、へばってるし。",v:"03_0283"},{w:"alek",t:"水おけ、あるか。こいつ、ひと晩つけときたいんや。",v:"03_0284"},{w:"elly",t:"あるよ！　ぶどう畑のはしの小屋に。",v:"03_0285"},{w:null,t:"エリーが歩きだすと、アレクもそのあとについてくる。"}];
GR_SC.g03_08=[{w:null,t:"夜ふけ。坂の上のホテル。",v:"03_0289"},{w:null,t:"玄関の明かりだけが、ついている。"},{w:null,t:"門の内側に、アナが、腕を組んで立っている。"},{w:"ana",t:"……こんな夜中に、二人とも、どこに行ってたの？",v:"03_0292"},{w:"elly",f:"surprised",t:"……えっと、……森。",v:"03_0293"},{w:"ana",t:"ちょっと出かけただけで、そんなに泥だらけになるの？",v:"03_0294"},{w:"ana",t:"電話、十二回もしたんだけど。",v:"03_0295"},{w:"elly",f:"sad",t:"（小さくなって）……ごめんなさい。音、切ってた。",v:"03_0296"},{w:"ana",t:"……で、あの人は、だれなの？",v:"03_0297"},{w:null,t:"門の外の、石の塀のそば。"},{w:"elly",f:"surprised",t:"えっと……森で会った人！",v:"03_0299"},{w:"ana",t:"……あとで、ちゃんと聞くからね。",v:"03_0300"},{w:null,t:"アナ、エリーの泥の服を見て、ため息。"},{w:null,t:"アレクの目が、リュックの横ポケットからはみ出したちらしの角に行く。"},{w:"alek",t:"白い都まで行くつもりなんか？",v:"03_0303"},{w:"hero",t:"行くに決まってんだろ。",v:"03_0304"},{w:"alek",t:"道なら、おれが知ってる。ヴィクターの車が通らへん道もな。",v:"03_0305"},{w:"alek",t:"……案内も、有料やで。",v:"03_0307"},{w:"hero",t:"また有料かよ。狐運ぶの、お前の仕事じゃねえか。",v:"03_0308"},{w:"alek",t:"届け先も、白い都や。",v:"03_0309"},{w:"hero",t:"着いても、フォルンはやらねえぞ。",v:"03_0310"},{w:"hero",t:"こいつは、おれと大会に出るんだからな。",v:"03_0311"},{w:"alek",t:"できたらな。",v:"03_0312"},{w:null,t:"エリー、塀の下にしゃがむ。"},{w:"elly",f:"smile",t:"（ワニの子に）約束だよ。わたしたち、勝ったんだから、名前、教えて。",v:"03_0314"},{w:"alek",t:"こいつの名前は、クロッコや。",v:"03_0315"},{w:null,t:"【プロフィール】クロッコ／水／●○○／のんき"},{w:"elly",t:"じゃあ、クロッコちゃんだね。",v:"03_0318"},{w:"alek",t:"「ちゃん」は、つけんでええって。",v:"03_0319"},{w:null,t:"ヤマト、アレクの腕の中のクロッコを見る。"},{w:null,t:"白く乾いたうろこを、アレクの手がそっとなでている。"},{w:"hero",t:"……道、知らねえしな。案内、たのむ。おれ、ヤマト。",v:"03_0322"},{w:"alek",t:"おれは、アレクや。",v:"03_0323"},{w:null,t:"アナが、タオルを二枚持ってもどってくる。"},{w:null,t:"一枚を、ヤマトの泥だらけの頭に、ばさっとかぶせる。"},{w:"hero",t:"（タオルから顔を出して）サンキュ、アナさん。",v:"03_0326"},{w:null,t:"アナ、ヤマトと目が合って、ふっと笑う。"},{w:"elly",t:"（タオルの下から）お姉ちゃん、この人、今夜泊めてあげて！",v:"03_0328"},{w:null,t:"エリー、クロッコのかさかさの背中を指さす。"},{w:null,t:"アナ、からになった手を腰に当てて、アレクを上から下まで見る。"},{w:null,t:"アレク、クロッコを抱いたまま、すっと背すじをのばす。"},{w:"alek",t:"（一段低い声で）……実は僕、北の国の王子でして。",v:"03_0332"},{w:"alek",t:"（一段低い声で）……お姉さん、僕とお茶しません？",v:"03_0333"},{w:null,t:"エリーの肩で寝ていたピリポンが、ビリリ。"},{w:"ana",t:"……で、一泊いくら払えるの？",v:"03_0335"},{w:null,t:"アレク、自分の手首の画面を見る。親指が、払いの欄の上で止まる。"},{w:null,t:"アナの目が、その手のひらに行く。"},{w:"alek",t:"（一段低い声で）……外でいいっす。屋根の分、浮くんで。",v:"03_0338"},{w:null,t:"腕の中のクロッコが、うす目をあける。"},{w:null,t:"アレク、あごから水をたらしたまま、低い声の顔をくずさない。"},{w:null,t:"アナ、だまって裏の小屋を指さす。"},{w:null,t:"アナ、もうエリーの泥だらけの服を見ている。"}];
GR_SC.g03_09=[{w:null,t:"ヤマトの部屋。"},{w:null,t:"窓のふちに、フォルン。"},{w:null,t:"フォルン、音を立てずに床へ下りる。"},{w:null,t:"リュックの上に乗る。"},{w:null,t:"ヤマト、うす目をあける。"},{w:null,t:"ヤマト、ベッドから、そうっと手をのばす。"},{w:null,t:"ぺしっ。しっぽが、ヤマトの手の甲をはたく。"},{w:"hero",t:"（小声で）……ちぇっ。",v:"03_0353"},{w:null,t:"ヤマト、手を引っこめる。"},{w:null,t:"リュックの方を向いたまま、掛け物をかぶる。"}];
GR_SC.g03_10=[{w:null,t:"ぶどう畑のはしの道具小屋。"},{w:null,t:"アレクの手首の画面が、ぶるっとふるえる。"},{w:"x",n:"画面の声（アレクの耳の中）",t:"アレク。狐と子どもは、どうした。",v:"03_0361"},{w:null,t:"アレク、ホテルの一階の、はしの窓を見る。"},{w:"alek",t:"森には、だれも来ませんでした。",v:"03_0363"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……夕方から、ずっとか。",v:"03_0364"},{w:"alek",t:"はい。",v:"03_0365"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……ワニのチップの反応が、消えたぞ。",v:"03_0366"},{w:"alek",t:"川で暴れて、取れてもうたみたいです。",v:"03_0367"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……狐は、必ず運べ。",v:"03_0369"},{w:"alek",t:"はい。白い都まで、運びます。",v:"03_0370"},{w:null,t:"通話が切れる。"},{w:null,t:"アレク、ポケットから、割れたチップを出す。"},{w:null,t:"水おけの中で、クロッコが寝がえりをうつ。アレクの手が、その頭の上で止まる。"}];
GR_BT[3]={mid:[[{w:"alek",t:"行け。水や。",v:"03_0174"},{w:"hero",t:"フォルン、やり返せ！",v:"03_0179"},{w:"alek",t:"もぐれ。もう一回、水や。",v:"03_0181"},{w:"hero",t:"出んな！　そこにいろ！",v:"03_0183"},{w:null,t:"ヤマト、その耳を見る。"}],[{w:"alek",t:"手前に回れ。",v:"03_0186"},{w:"elly",t:"ピリポン！",v:"03_0189"},{w:null,t:"ヤマト、森を見わたす。"},{w:null,t:"ヤマトの目が、フォルンの小さな火から、しぶきでふくらんだ苔へ。"},{w:"hero",f:"serious",t:"……じゃんけんじゃん、これ。",v:"03_0201"},{w:null,t:"ヤマト、残った一本の指で、小川の水とピリポンを、交互に指さす。"},{w:"hero",f:"serious",t:"……エリー！",v:"03_0204"},{w:"elly",t:"ピリポン、あそこ！",v:"03_0205"},{w:null,t:"アレクの目が、はじめてヤマトからはなれる。"}],[{w:"alek",t:"下がれ！　そいつの電気から離れや。",v:"03_0212"},{w:null,t:"ヤマトの目が、小川から、左の、白っぽい石の地面へ行く。"},{w:null,t:"ヤマトの指が、川の中のワニの子と、石の地面の奥を、一本の線で結ぶ。"},{w:"hero",t:"フォルン！　もう、根もとにいなくていい！",v:"03_0217"},{w:"hero",t:"（石の地面の奥を指さして）あそこまで下がれ！",v:"03_0219"},{w:null,t:"エリー、石の地面のフォルンを見る。それから、石のかげで震えているピリポンを見る。"},{w:"elly",t:"ピリポン、もう少しだけ前に出られる？",v:"03_0223"},{w:"elly",t:"わたし、ここでずっと見てるから。",v:"03_0224"},{w:null,t:"アレク、石の地面の奥のフォルンを見る。しっぽの火が、まだ小さい。"},{w:null,t:"アレクの目が、白く乾いた石へ下りる。"}],[{w:"alek",t:"川から上がれ！　火ぃ小さいうちに、近くで撃て！",v:"03_0229"},{w:null,t:"アレクの顔が、わずかに動く。"},{w:"alek",t:"もどれ！　川までもどるんや！",v:"03_0236"},{w:"elly",f:"serious",t:"……ピリポン、いける？",v:"03_0238"},{w:"elly",t:"ピリポン、ぱちって！",v:"03_0242"},{w:"hero",t:"フォルン、今だ！　そこからぶっ放せ！",v:"03_0244"}]],post:[{w:null,t:"ワニの子が、炎に押されて吹き飛び、小道の草の上を転がって、ひっくり返る。目を回して、起き上がらない。"},{w:null,t:"ひっくり返ったワニの子の耳のうしろのうろこを、雷の残りが、ちりちりっと走る。"}]};
GR_EP[3]={"t": "夜の森", "sc": [["g03_01", "森の小川（夕方）", 0], ["g03_02", "ホテルの裏口（夜）", 0], ["g03_03", "森の道（夜）", 0], ["g03_04", "口げんか", 0], ["g03_05", "向かい合う", 0], ["g03_06", "勝負（2Dアニメ）", 1], ["g03_07", "勝負のあと", 0], ["g03_08", "ホテルの門（夜ふけ）", 0], ["g03_09", "ホテルの一階のはしの部屋（夜ふけ）", 0], ["g03_10", "ホテルの裏・道具小屋（夜ふけ）", 0]]};
GR_SC.g04_01=[{w:null,t:"坂のとちゅうに、黒塗りのロボタクシーが止まっている。"},{w:null,t:"うしろの席。"},{w:null,t:"画面の字。「アレク　報告：森にはだれも来なかった」「オリーヴァ村　狐　まだ」。"},{w:"nina",t:"マルコ、起きなさい。仕事よ。",v:"04_0042"},{w:"marco",t:"……それ、アレクの仕事だろ。",v:"04_0043"},{w:null,t:"ニーナ、画面の字を、マルコの顔の前へ向ける。"},{w:null,t:"マルコ、帽子を少しだけ上げる。"},{w:"marco",t:"……めんどくさいなあ。朝めし、まだなのに。",v:"04_0046"},{w:null,t:"マルコの足もとで、黒い体にオレンジの点の散った、小さなヤモリの子が、目をあける。"},{w:null,t:"耳のうしろで、ヴィクターのマークの小さなチップが、ちかっと光る。"},{w:null,t:"第4話　夜明けの火",v:"04_0050"}];
GR_SC.g04_02=[{w:null,t:"坂の上のホテル。四日目の朝。",v:"04_0056"},{w:null,t:"ぶどう畑のはしの道具小屋から、アレクが、うすい掛け物をたたみながら出てくる。"},{w:null,t:"二階の窓から、アナが顔を出す。"},{w:"ana",t:"おはよう。じゃあ、ひと晩分の宿代ね。20ジェムコイン。",v:"04_0059"},{w:null,t:"アレク、手首の画面を、そでの中へ引っこめる。"},{w:"alek",t:"……画面で払うのは、ちょっと。",v:"04_0061"},{w:"ana",t:"わけありね。……じゃあ、裏の用水路の泥かき。",v:"04_0062"},{w:"ana",t:"それでいいから。",v:"04_0063"},{w:"alek",t:"……ほな、それで頼んますわ。",v:"04_0064"},{w:null,t:"小屋の横の石の水おけ。クロッコが体をしずめて、目をつむっている。"},{w:null,t:"小屋の前の用水路を、フォルンがひょいとまたぐ。"},{w:null,t:"フォルン、しっぽをぶるっとふって、知らん顔。"}];
GR_SC.g04_03=[{w:null,t:"朝ごはんのテラス。"},{w:null,t:"床を、丸い掃除ロボットがすべって回る。"},{w:null,t:"テラスの手すりの向こう、裏の畑。"},{w:"hero",t:"でさ、相手、川からばしゃーって撃ってくんの。",v:"04_0075"},{w:"x",n:"客の子A",t:"えっ、負けちゃうの？",v:"04_0076"},{w:"hero",t:"ふつうはな。でも、そこでおれが気づいたわけ。",v:"04_0077"},{w:"x",n:"客の子B",t:"何に気づいたの？",v:"04_0078"},{w:"hero",t:"（パンをほおばって）……とにかく、気づいたんだよ。",v:"04_0079"},{w:"x",n:"客の子A",t:"ふーん。言えないんだ。",v:"04_0080"},{w:"elly",t:"（パンをちぎりながら）気づいたの、負けそうになってからだったよね。",v:"04_0081"},{w:"hero",t:"負けそうになってからでも、気づいたもんは気づいたんだ。",v:"04_0082"},{w:null,t:"テーブルのはしで、フォルンがしっぽの火の上でオリーブを転がしている。"},{w:null,t:"ヤマト、いちばん大きい焼きオリーブを、ひょいとつまむ。"},{w:"hero",t:"これは、作戦を考えたおれの分な。",v:"04_0085"},{w:null,t:"フォルンのしっぽの火が、ぼっとふくらむ。"},{w:null,t:"前髪が、根もとの近くまで燃える。"},{w:null,t:"残ったのは、短い前髪と、右上の焦げた一房。"},{w:null,t:"フォルン、固まった指からオリーブをくわえて取る。"},{w:null,t:"子どもたちが、どっと笑う。"},{w:null,t:"ヤマト、おでこを手のひらでさわる。"},{w:"hero",t:"……で、次にだれが来ても、おれとフォルンなら——",v:"04_0092"},{w:"ana",t:"ヤマト。門のところに、あんたにお客さんが来てる。",v:"04_0094"}];
GR_SC.g04_04=[{w:null,t:"門の外に、マルコ。"},{w:"marco",t:"よう。この前の礼をしに来てやったぜ。",v:"04_0098"},{w:"hero",t:"あっ、この前の……マカロニ！",v:"04_0099"},{w:"marco",t:"誰がマカロニだ！　マルコだ！",v:"04_0100"},{w:"marco",t:"……あの狐、ここにいるんだろ？",v:"04_0101"},{w:null,t:"ヤマトの足もとで、フォルンの耳が立つ。"},{w:null,t:"マルコの目が、フォルンから、そのうしろへ行く。"},{w:"marco",t:"……アレク？　なにしてんだよ、そんなとこで。",v:"04_0104"},{w:"alek",t:"泥かきや。宿代のかわり。",v:"04_0105"},{w:"marco",t:"その狐、お前の係だろ。なんで、つかまえねえんだよ。",v:"04_0106"},{w:"alek",t:"おれのやり方があんねん。",v:"04_0107"},{w:"marco",t:"ふーん。……まあ、いいや。",v:"04_0108"},{w:null,t:"坂の下で、ニーナの画面が、かしゃっと鳴る。"},{w:"marco",t:"一対一で、どうだい。そっちが勝ったら、おれは手を引く。",v:"04_0110"},{w:"marco",t:"おれが勝ったら、狐はもらっていくぜ。",v:"04_0111"},{w:null,t:"アレク、泥だらけのまま、畑から門へ走ってくる。"},{w:"alek",t:"待て待て待て。ヤマト、勝手に返事すんなや。",v:"04_0113"},{w:"hero",t:"まだ何も言ってないって。",v:"04_0114"},{w:"hero",t:"（マルコに）受けなかったら、どうなんだよ。",v:"04_0115"},{w:"marco",t:"ニーナがドローンを呼んで、網だな。",v:"04_0116"},{w:null,t:"ヤマト、テラスの方をふり返る。"},{w:null,t:"ヤマト、アレクの方は見ない。"},{w:null,t:"アレク、テラスの子どもたちを見る。それから、水おけのクロッコ。"},{w:"alek",t:"……クロッコ、まだ出されへんで。",v:"04_0120"},{w:"hero",t:"いらねえよ。休ませとけ。フォルン、行くぞ。",v:"04_0121"},{w:null,t:"マルコの肩のヤモリが、口をあける。"},{w:null,t:"エリーの肩のピリポンが、エリーの髪の中に、頭からもぐりこむ。"},{w:"marco",t:"こいつ、まだ上があるんだぜ。",v:"04_0124"},{w:"hero",t:"上？　関係ねえよ。燃やしたもん勝ちだろ。",v:"04_0125"},{w:null,t:"ヤマトは、もう門の外に出ている。"},{w:"marco",t:"場所は、どこでもいいけど。……裏の畑にしようか。",v:"04_0127"},{w:"marco",t:"林のそばなら、日かげがあるからな。",v:"04_0128"}];
GR_SC.g04_05=[{w:null,t:"ぶどう棚の前で、マルコが畑を見わたす。"},{w:null,t:"手前は、乾いた草の畑。"},{w:null,t:"マルコ、林のわきの石垣のかげに木箱を置いて、座る。"},{w:null,t:"【プロフィール】スミヤモ／炎／●○○／火の玉を落とすヤモリ"},{w:null,t:"ヤマト、フォルンを手前の畑のまん中に立たせる。"},{w:null,t:"アレクとエリーが、ぶどう棚の下に立つ。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"6や。……お前のより、上やで。",v:"04_0144"},{w:"hero",t:"上等じゃん。",v:"04_0145"},{w:"marco",t:"じゃ、始めようか。こっちは、いつでもいいぜ。",v:"04_0146"}];
GR_SC.g04_09=[{w:"hero",f:"smile",t:"……やった。やったぞ、フォルコン！",v:"04_0278"},{w:null,t:"フォルンの体から、光がすうっと引いていく。"},{w:null,t:"ヤマト、ひざをついたまま、目をぱちぱちさせる。"},{w:"hero",f:"serious",t:"……あ、戻った。",v:"04_0281"},{w:null,t:"ヤマト、ひざの高さのフォルンを、上から下まで二回見る。"},{w:null,t:"アレク、ゴーグルを上げて、肩をすくめる。"},{w:"elly",t:"フォルン、前足、見せて！",v:"04_0284"},{w:null,t:"エリー、かけよってしゃがむ。"},{w:null,t:"マルコ、オキヤモを両腕でかかえ上げて、重そうに肩にかつぎ直す。"},{w:"marco",t:"……約束は約束だ。今日は帰るぜ。",v:"04_0287"},{w:"nina",t:"送ったわよ、ボスに。今の写真。",v:"04_0288"},{w:"marco",t:"……おれは、もういいや。",v:"04_0289"},{w:null,t:"マルコ、帰りかけて、アレクの前で止まる。"},{w:"marco",t:"アレク。お前、ほんとに運ぶ気あんのか。",v:"04_0291"},{w:"alek",t:"仕事はするで。",v:"04_0292"},{w:"marco",t:"ならいいけどさ。うちのボス、しつこいからな。",v:"04_0293"},{w:null,t:"マルコ、坂を下りていく。肩の上で、オキヤモのしっぽがぶらぶらゆれる。"},{w:null,t:"アレク、用水路の湯気を見たまま、ヤマトの横に立つ。"},{w:"alek",t:"水ん中の火ぃは、ちぎれてまうんや。",v:"04_0296"},{w:null,t:"エリー、フォルンの前足をなでながら、ヤマトの方をふり返る。にっと笑う。"},{w:null,t:"ヤマト、鼻の頭をかいて、焦げた前髪を指でつまむ。"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。さっきまで見上げていた顔が、ひざの高さにある。"},{w:"hero",t:"おい、それ、おれの手袋だって。",v:"04_0301"},{w:"hero",f:"serious",t:"……おい。返せって。",v:"04_0303"}];
GR_SC.g04_10=[{w:null,t:"ロビーの画面に、広告。"},{w:null,t:"ヤマト、その前に立っている。"},{w:null,t:"アレクがうしろに来る。"},{w:"alek",t:"今のうちに、村出よか。",v:"04_0310"},{w:null,t:"パンの袋をつめていたエリーの手が、一瞬だけ止まる。"},{w:"elly",f:"serious",t:"……お姉ちゃんに、言ってから。",v:"04_0312"},{w:"alek",t:"ほな、はよ言うてき。二分な。",v:"04_0313"},{w:null,t:"エリー、パンの袋をカウンターに置いて、ロビーの奥へ走っていく。"},{w:"hero",t:"白い都まで、どれくらいかかんの？",v:"04_0315"},{w:"alek",t:"歩きなら、二週間くらいや。",v:"04_0316"},{w:"hero",f:"serious",t:"……歩き？　ロボタクシーは？",v:"04_0317"},{w:null,t:"門の前を、ロボタクシーがすうっと通る。ヤマト、手を上げかける。"},{w:"alek",t:"乗ったら、行き先が全部残るやろ。",v:"04_0319"},{w:"hero",t:"残ったら困んの、お前だろ。マカロニの仲間だし。",v:"04_0320"},{w:"alek",t:"仲間ちゃう。白い都までは、仕事や。",v:"04_0321"},{w:"alek",t:"あと、大会の賞金。勝ったら、案内の分で半分もらうで。",v:"04_0322"},{w:"hero",f:"serious",t:"……それは、勝ってから決めようぜ。",v:"04_0323"},{w:null,t:"アレク、水おけからクロッコを出して、背中にかつぐ。クロッコ、目はあけない。"},{w:null,t:"ロビーの奥から、エリーがアナの手を引いてもどってくる。"},{w:"ana",t:"おばあちゃんに聞いたら、行かせなさいって。",v:"04_0326"},{w:"ana",t:"……どうせ、止めても行くんでしょ。",v:"04_0327"},{w:null,t:"エリー、カバンのひもを指に巻く。"},{w:"ana",t:"そのかわり毎晩、自分の画面で電話してきなさい。",v:"04_0329"},{w:null,t:"アナ、エリーのうしろのアレクを、一度だけ見る。"},{w:"ana",t:"電話が一晩抜けたら、むかえに行くからね。",v:"04_0331"},{w:"elly",f:"serious",t:"……うん。毎晩、かける。",v:"04_0332"},{w:null,t:"アナ、上着のポケットから、手のひらほどのうすい板を出す。"},{w:null,t:"表に、お金の数字が光っている。"},{w:"ana",t:"それと、これ。旅のあいだの、ジェムコインのカード。",v:"04_0335"},{w:"elly",t:"いいの？",v:"04_0336"},{w:"ana",t:"おばあちゃんから。なくさないでね。",v:"04_0337"},{w:null,t:"エリー、カードを両手で受け取って、肩かけカバンの内ポケットにしまう。"},{w:null,t:"アナ、アレクの方を向く。"},{w:"ana",t:"（アレクに）宿代は、泥かきでちゃらにしてあげる。",v:"04_0340"},{w:"ana",t:"そのかわりカードの分は、帰ってきたら働いて返してね。",v:"04_0341"},{w:null,t:"アレク、エリーのカバンの内ポケットを見る。"},{w:null,t:"アレク、背すじをのばして、アナに頭を下げる。"},{w:"alek",t:"（一段低い声で）……ちゃんと返しに来ますわ。",v:"04_0344"},{w:"alek",t:"（もっと低い声で）……実は僕、島に別荘持ってまして。",v:"04_0345"},{w:"alek",t:"（もっと低い声で）……お姉さん、僕とお茶しません？",v:"04_0346"},{w:null,t:"エリーの髪の中のピリポンが、ビリリ。"},{w:null,t:"アナ、エリーのカバンのひもを直したまま、顔を上げない。"},{w:"ana",t:"お茶代も、カードの分につけとくね。",v:"04_0349"},{w:null,t:"アレク、頭を下げた形のまま、止まる。背中のクロッコは、知らん顔であくび。"},{w:null,t:"アレク、だまって背すじをもどす。"},{w:null,t:"アレクの目が、ヤマトのリュックの横ポケットに行く。"},{w:null,t:"アレク、指二本で、ちらしをすっと抜く。"},{w:"alek",t:"……五千か。",v:"04_0354"},{w:null,t:"ヤマト、ひったくって、ポケットの奥へ押しこむ。"},{w:null,t:"エリー、カウンターのパンの袋を抱え上げる。"},{w:null,t:"袋の口から、パンくずがぽろぽろこぼれる。"},{w:null,t:"エリー、うしろのフォルンを見て、袋を少し下げて歩く。"},{w:null,t:"フォルン、手袋を足もとに置いてパンくずを食べ、またくわえる。"},{w:null,t:"アレク、ヤマトとエリーの方を向く。"},{w:"alek",t:"森の道で行くで。",v:"04_0361"},{w:"hero",t:"アナさん、ありがとな！　パン、うまかった！",v:"04_0363"}];
GR_SC.g04_11=[{w:null,t:"窓のない暗い部屋。"},{w:null,t:"白い右手が、写真を指で大きくする。"},{w:null,t:"となりの欄に、1話の写真。少年の前でしっぽを立てる、小さな狐。"},{w:null,t:"人さし指が、宙の字の板を、ゆっくり押していく。"},{w:null,t:"もう一枚。ニーナが門で撮った、泥かきのアレク。指が、それを一度大きくして、もどす。"},{w:null,t:"指が、送り先の並びの上で止まる。"},{w:null,t:"指が、机を、とん、とん。それから「ニーナ」を押す。"},{w:null,t:"字が一行。「ドローンを出せ。"}];
GR_BT[4]={mid:[[{w:"hero",f:"surprised",t:"（用水路の手前の土を指さして）フォルン、そっちじゃねえ！　こっちだ！",v:"04_0150"},{w:"marco",t:"スミヤモ、焼いちまえ。",v:"04_0154"},{w:"hero",t:"撃て、フォルン！　もっと撃て！",v:"04_0161"},{w:"hero",t:"ちがう、近くだ！　林まで行け！",v:"04_0163"},{w:null,t:"マルコのうしろで、ニーナが手首の画面を指で押す。"},{w:null,t:"マルコ、木箱から半分立ち上がる。"},{w:"hero",t:"出ろ！　フォルン、林から出ろ！",v:"04_0183"},{w:"hero",t:"右だ！　いや、左！　下がれ、フォルン！",v:"04_0185"},{w:null,t:"アレクは何も言わない。組んだ腕の指が、ひじをつかんでいる。"}],[{w:null,t:"マルコ、木箱から腰を上げて、のびをする。"},{w:"marco",t:"これ以上焦がすと、あとでボスがうるさいんだ。",v:"04_0191"},{w:"marco",t:"オキヤモ、止まれ。",v:"04_0192"},{w:"marco",t:"……オキヤモ？　止まれって言ってるだろ。",v:"04_0195"},{w:null,t:"ニーナの手首の画面が鳴る。"},{w:"marco",t:"……ニーナ、止められないのか？",v:"04_0197"},{w:null,t:"ニーナ、だまって画面をマルコに向ける。"},{w:null,t:"マルコ、ニーナの画面をのぞきこんだまま、だまる。"}],[{w:"marco",t:"……止まってくれよ。",v:"04_0207"},{w:null,t:"ヤマト、ぶどう棚の柱をつかんで、畑へ身を乗り出す。"},{w:null,t:"ヤマト、ふり返る。エリーが、すそをつかんだまま、首を横にふる。"},{w:null,t:"ヤマト、その場でひざをつく。"},{w:"hero",t:"（小さく、呼ぶだけ）……フォルン。",v:"04_0214"},{w:null,t:"ヤマトの目が、大きくなる。"},{w:null,t:"ヤマト、左の手首の画面を、フォルンへかざす。"},{w:"hero",t:"フォルン、進化！",v:"04_0223"},{w:"hero",f:"smile",t:"（小声で）……すっげー。",v:"04_0230"},{w:"elly",f:"serious",t:"……フォルン、おっきくなった。",v:"04_0234"}],[{w:null,t:"ヤマトの目が、二つの炎を見くらべる。"},{w:"hero",t:"フォルコン、あいつを水から上げるな！",v:"04_0245"}]],post:[{w:null,t:"ヤマト、こぶしを胸の前でにぎって、動かない。"},{w:null,t:"フォルコン、前を見たまま、四本の足で土をつかみ直す。"},{w:null,t:"燃えるえりまきが、ぶわっと大きくなる。二本のしっぽの火が、倍にのびる。"},{w:"hero",t:"（オキヤモを指さして）フォルコン、フォックスファイヤー！",v:"04_0267"},{w:"marco",t:"……もういいって。お前、がんばったよ。",v:"04_0272"}]};
GR_EP[4]={"t": "夜明けの火", "sc": [["g04_01", "村を見下ろす坂（夜明け）", 0], ["g04_02", "ホテルの裏・道具小屋（朝）", 0], ["g04_03", "ホテルのテラス（朝）", 0], ["g04_04", "ホテルの門", 0], ["g04_05", "ホテルの裏の畑・向かい合う", 0], ["g04_06", "勝負・炎どうし（2Dアニメ）", 1], ["g04_07", "勝負・止まらない（2Dアニメ）", 1], ["g04_08", "勝負・水から上げない（2Dアニメ）", 1], ["g04_09", "勝負のあと", 0], ["g04_10", "ホテルのロビーと門（昼前）", 0], ["g04_11", "窓のない部屋", 0]]};
GR_SC.g05_01=[{w:null,t:"オリーヴァ村を出た三人は、丘のオリーブの木の下で夜を明かした。",v:"05_0033"},{w:null,t:"丘の中腹。古いオリーブの木の下に、銀色のうすいシートが一枚。"},{w:null,t:"ヤマトだけ、シートからはみ出して、草の上で大の字。"},{w:null,t:"フォルンは、シートのはしで丸くなっている。しっぽの火だけが、シートの外に出ている。"},{w:null,t:"丘の下の道。"},{w:null,t:"アレク、目をあける。"},{w:null,t:"アレク、フォルンのしっぽをつかんで、シートの中へ押しこむ。"},{w:null,t:"アレク、ヤマトの腕をつかんで、シートの下へずるずる引きずりこむ。エリーは、目をつむったまま、自分でころころ転がって場所をあける。"},{w:"hero",t:"（寝ぼけて）……なに。なんで、おれ、シートん中？",v:"05_0043"},{w:"alek",t:"ヴィクターのドローンや。",v:"05_0044"},{w:"hero",f:"serious",t:"……起こせよ、ふつうに。",v:"05_0046"},{w:"alek",t:"ドローンの真下で、大声出せるかい。",v:"05_0047"},{w:"hero",f:"serious",t:"……おい、手袋。",v:"05_0051"},{w:null,t:"第5話　丘の畑",v:"05_0053"}];
GR_SC.g05_02=[{w:null,t:"オリーヴァ村の東。オリーブの丘が、いくつも続いている。",v:"05_0059"},{w:null,t:"道ばたで、収穫ロボットが一台休んでいる。"},{w:"elly",t:"今日のラッキースポットは、古い字のある所だって！",v:"05_0061"},{w:null,t:"ヤマトはフォルンのしっぽを、アレクは丘の下のドローンを見ている。"},{w:null,t:"エリー、ほっぺをぷくっとふくらませる。"},{w:null,t:"となりの大きな丘。"},{w:null,t:"こちらの斜面の畑。"},{w:"hero",t:"あっちの丘はロボットなのに、こっちは手か。",v:"05_0066"},{w:null,t:"ヤマト、ふしぎそうに、網の上の実を一つ拾って、近くの女の人のかごに入れる。"},{w:"x",n:"村の女の人",t:"ありがとう。手で摘むと、高く売れるの。",v:"05_0068"},{w:"x",n:"村の女の人",t:"……あなたたち、この丘を越えて行くの？",v:"05_0069"},{w:"elly",t:"うん。向こうがわに下りたいの。",v:"05_0070"},{w:"x",n:"村の女の人",t:"なら、いちばん上のヤニスさんの畑を通るしかないよ。",v:"05_0071"},{w:null,t:"女の人、丘のいちばん上を見て、小さく首を横にふる。"}];
GR_SC.g05_03=[{w:null,t:"この丘のいちばん上に、ひときわ手入れのいい畑があった。",v:"05_0078"},{w:null,t:"畑の見えるところで、アレクの足が止まる。"},{w:null,t:"アレク、がけの下と石垣の高さを目ではかる。それから、畑の中の道へ歩き出す。"},{w:null,t:"手入れのいい木の並び。"},{w:null,t:"幹の小さな穴のいくつかに、黒い網の切れはしがひっかかったまま。"},{w:null,t:"畑のはしを、石を組んだ溝が流れている。"},{w:null,t:"手前のすみに、昔の脱穀場の、丸い石の床。"},{w:null,t:"畑のはしに、小さな石の家。"},{w:null,t:"男が一人、くずれた溝の石を、だまって積み直している。"},{w:null,t:"【字幕】「ヤニス」。"},{w:null,t:"ヤマト、石の床の上に、どさっと座って、両手をつく。"},{w:"hero",t:"エリー、この石、ぽかぽかしてる！",v:"05_0089"},{w:"hero",t:"朝から引きずりこまれたから、ちょっとだけ寝ていい？",v:"05_0090"},{w:"alek",t:"人の畑やで。",v:"05_0091"},{w:null,t:"エリーの肩から、ピリポンが石の床に、ぴょんと下りる。"},{w:null,t:"ヤマト、石についていた手を、さっと上げる。"},{w:null,t:"ピリポン、自分でびっくりして、エリーの足をかけ上がり、肩から髪の中にもぐる。"},{w:null,t:"太いオリーブの幹に、小さなカブトムシのテリオンがとまっている。"},{w:null,t:"【プロフィール】カブッコ／風／●○○／赤茶の小さなカブトムシ"},{w:"hero",t:"カブトムシだ！",v:"05_0097"},{w:null,t:"ヤマト、幹にかけ寄る。"},{w:null,t:"カブッコが、幹の上で前足を、ぐっとふんばる。それから、つのを右下からすくい上げる。"},{w:null,t:"はじかれたカブッコが、まっすぐうしろへ跳んで、幹にもどる。"},{w:null,t:"エリーだけが、それを見ている。"},{w:null,t:"ピリポンの毛の先から、火花が一つ、幹のカブッコのつのへ、ぴりっと跳ぶ。"},{w:"stavros",f:"serious",t:"……よく見てるな。",v:"05_0107"},{w:"stavros",t:"先月の晩、ここに住んでた小さいのが、みんな連れていかれた。",v:"05_0110"},{w:"stavros",f:"serious",t:"……ヴィクターのチップだな。",v:"05_0114"},{w:"alek",t:"……そこの仕事、受けてます。",v:"05_0115"},{w:"hero",t:"でも、こいつ、まだ一回も狐を運んでねえんだよ！",v:"05_0117"},{w:"stavros",t:"「まだ」か。",v:"05_0118"},{w:"stavros",t:"口では、何とでも言える。",v:"05_0119"},{w:"stavros",t:"通りたいなら、勝負しろ。",v:"05_0121"},{w:"stavros",t:"負けたら、来た道を帰れ。",v:"05_0122"},{w:"alek",t:"ほな、こっちは三体で。",v:"05_0124"},{w:"elly",f:"serious",t:"……ピリポンも？",v:"05_0125"},{w:"alek",t:"ヤマトひとりより、ましやろ。",v:"05_0126"},{w:"hero",f:"serious",t:"……聞こえてんぞ。",v:"05_0127"},{w:"stavros",t:"そっちが三体なら、こっちも三体だ。",v:"05_0128"},{w:"hero",t:"え、三匹もいんの？",v:"05_0130"}];
GR_SC.g05_04=[{w:null,t:"畑のまん中で、勝負が始まる。",v:"05_0138"},{w:null,t:"向こうのはしはオリーブの木。"},{w:null,t:"ヤニス、千年のオリーブの向こうがわ、幹のかげに立って、腕を組む。"},{w:null,t:"カブッコたちが、羽を一度広げる。"},{w:null,t:"羽の風で、手前の草が、さあっと一方へなびく。"},{w:null,t:"フォルン、手前のまん中に出る。"},{w:null,t:"ヤマト、手袋を拾って右手にはめる。"},{w:null,t:"アレク、クロッコを溝のそばの草に下ろす。"},{w:null,t:"エリー、石の床から十歩うしろの、石垣の前に立つ。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"stavros",t:"始め。",v:"05_0150"}];
GR_SC.g05_08=[{w:null,t:"昼。千年のオリーブの下。",v:"05_0245"},{w:null,t:"フォルコンとピリムサとヘラツノの体から、光がすうっと引いていく。"},{w:null,t:"ヤニス、カブッコ三匹のそばにしゃがむ。"},{w:null,t:"エリー、石の床の上のピリポンをだき上げる。"},{w:null,t:"エリー、ピリポンを顔の高さまで持ち上げて、その場でくるっと一回まわる。"},{w:null,t:"ピリポン、エリーのほっぺに、頭をすりすり。エリー、くすぐったそうに笑う。"},{w:"hero",t:"エリー、もう一回、ピリムサにして！",v:"05_0251"},{w:"elly",t:"だめ。ピリポン、もう寝てる。",v:"05_0252"},{w:null,t:"エリーの腕の中で、ピリポン、鼻ちょうちん。"},{w:null,t:"アレク、溝からクロッコをだき上げて、ヤマトの横を通る。"},{w:"alek",t:"……エリーの「右」の方が、速かったな。",v:"05_0255"},{w:"hero",t:"次は、おれの方が速え。",v:"05_0256"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。"},{w:"hero",f:"smile",t:"フォルン、さっきのフォルコン、すっげーかっこよかったぜ！",v:"05_0258"},{w:null,t:"フォルン、前足をなめたまま、ぷいとそっぽを向く。"},{w:null,t:"でも、しっぽの火だけが、ぼっと大きくなる。"},{w:null,t:"火が、ヤマトの前髪に届く。"},{w:"alek",t:"クロッコ、消してやれ。",v:"05_0262"},{w:null,t:"アレクの腕の中から、クロッコがヤマトの頭へ水をぴゅっ。"},{w:null,t:"ヤマト、前髪からしずくをたらして、だまる。"},{w:null,t:"エリー、指でなぞって、ちょっとだけ笑う。"},{w:null,t:"ヤニス、立ち上がって、アレクの前に来る。"},{w:null,t:"ヤニス、クロッコの頭に手のひらをのせる。それから、ふり返って、フォルンの耳のうしろを見る。"},{w:"stavros",t:"ドローンは、最後まで呼ばなかったな。",v:"05_0269"},{w:"alek",t:"勝負は、勝負なんで。",v:"05_0270"},{w:null,t:"ヤニス、石の家からガラスのびんを持ってくる。"},{w:"stavros",t:"しおみずに、二か月つけてある。食ってみろ。",v:"05_0272"},{w:null,t:"ヤマト、一つ口に入れる。顔が、きゅっとすっぱくなる。"},{w:"hero",t:"すっぱ！　……でも、うまい。もう一個、いい？",v:"05_0274"},{w:null,t:"ヤニス、うなずく。"},{w:"hero",t:"（のみこんで、ヤニスを見て）おっちゃん、これ、サンキュ！",v:"05_0276"},{w:null,t:"ヤニス、手首の画面にふれる。入口の柵が、すうっと下がって開く。"},{w:null,t:"ヤニスの手首の画面が、短く一回鳴る。"},{w:null,t:"幹の上のカブッコたちと同じ、小さなカブトムシの子。"},{w:null,t:"写真の下の札が、青から赤に変わる。"},{w:null,t:"写真の中の箱が、知らない字の書いた大きな荷物の箱の列に、ならべられている。"},{w:null,t:"ヤニスの指が、写真の上で止まる。"},{w:null,t:"ヤニス、だまって画面を閉じる。"},{w:null,t:"ヤマトは、ヤニスのななめうしろで、それを見ていた。"},{w:null,t:"アレクも、それを見ていた。"},{w:null,t:"ヤニス、かごを石の家の前に置いて、また、くずれた溝の石を積みはじめる。"},{w:null,t:"アレク、腕の中のクロッコの耳のうしろに、指を入れる。"},{w:null,t:"アレク、それを溝に落とす。"},{w:"stavros",t:"（石を積みながら）その仕事は、どうする。",v:"05_0291"},{w:"alek",t:"やめますわ。今日で。",v:"05_0292"},{w:"hero",t:"え、やめんの？",v:"05_0293"},{w:"stavros",t:"なぜだ。",v:"05_0294"},{w:"alek",t:"割に合わへんので。",v:"05_0295"},{w:"stavros",f:"serious",t:"……そうか。",v:"05_0296"},{w:null,t:"アレク、溝のそばにしゃがむ。"},{w:null,t:"ヤニス、手を止めて、それを見る。"},{w:"hero",f:"serious",t:"……じゃあ、狐は？",v:"05_0299"},{w:"alek",t:"運ばへんわ。もう仕事ちゃう。",v:"05_0300"},{w:"hero",t:"なんだよ。最初からそう言えよ。",v:"05_0301"},{w:"alek",t:"最初は、仕事やったんや。",v:"05_0302"},{w:"hero",t:"じゃあ、もうついて来ねえのか？",v:"05_0303"},{w:"alek",t:"大会の賞金、半分はおれのやろ。",v:"05_0304"},{w:null,t:"アレク、ヤマトの背中を、ばしっとたたく。"},{w:null,t:"エリー、ピリポンを抱いたまま、二人を見てくすっと笑う。"},{w:null,t:"アレク、自分の手首の画面を開く。"},{w:"alek",t:"名無しにしたで。",v:"05_0308"},{w:"hero",t:"おっちゃん、この木って、何年生きてんの？",v:"05_0313"},{w:"stavros",t:"千年は、こえてる。",v:"05_0314"},{w:"hero",t:"千年……。じいちゃんより上じゃん。",v:"05_0315"},{w:"ana",t:"エリー！　きのうの夜、どうしてかけてこなかったの！",v:"05_0319"},{w:"ana",t:"もう少しで、さがしに行くとこだったよ。",v:"05_0320"},{w:"elly",f:"sad",t:"ごめんね。きのうはオリーブの丘の上で寝てて——",v:"05_0321"},{w:"alek",t:"（小声で）場所を言うなや！",v:"05_0323"},{w:"elly",t:"……外で寝てたら、そのまま朝になっちゃったの。",v:"05_0324"},{w:"elly",t:"今夜からは、ちゃんとかけるから。",v:"05_0325"},{w:"ana",t:"……ごはんは、ちゃんと食べてる？",v:"05_0326"},{w:"elly",t:"うん。オリーブ、食べてる。",v:"05_0328"}];
GR_SC.g05_09=[{w:null,t:"夕方。三人は、畑の向こうの、いちばん高い丘のてっぺんに着いた。",v:"05_0334"},{w:null,t:"いちばん高い丘のてっぺんに、三人と三体。"},{w:null,t:"東の空。遠くの森の上に、灰色の煙が一本。"},{w:"hero",t:"あれ、煙だよな。何か燃えてんのか？",v:"05_0337"},{w:null,t:"アレク、ゴーグルを目まで下ろす。"},{w:null,t:"煙の方角の、深い緑の場所。"},{w:"alek",t:"アルカディアの森や。白い都への道、あの中や。",v:"05_0341"},{w:"elly",t:"（肩のピリポンを手でおさえて）……森にいる子たち、逃げられてるかな。",v:"05_0342"},{w:"alek",t:"急ぐで。",v:"05_0343"},{w:null,t:"ヤマト、もう坂をかけ下りている。"},{w:null,t:"アレク、ゴーグルを頭に上げて、古い望遠鏡をのぞく。"},{w:null,t:"ドローンの胴に、オレンジの輪。"}];
GR_BT[5]={mid:[[{w:null,t:"ヤマト、三匹を目で追う。"},{w:"hero",t:"フォルン、まだ出るな。そこから一発いけ。",v:"05_0155"},{w:null,t:"ヤニス、手首をかざす。"},{w:"stavros",t:"カブッコ、進化。",v:"05_0159"},{w:null,t:"ヤマト、左の手首の画面を、フォルンへかざす。"},{w:"hero",t:"フォルン、進化！",v:"05_0165"},{w:null,t:"ヤマトの目は、手首に落ちたまま。"},{w:"hero",f:"angry",t:"なんでだよ。進化だって！",v:"05_0168"}],[{w:"hero",t:"フォルン、進化！",v:"05_0179"},{w:"hero",t:"フォルコン、動くな。来たら、そこでぶっ放せ。",v:"05_0181"},{w:null,t:"ヤマト、腕を大きくうしろへふる。"},{w:"hero",t:"フォルコン、離れろ！　遠くからだ！",v:"05_0186"},{w:"alek",t:"クロッコ、みぞに引きずりこめ！",v:"05_0188"},{w:null,t:"エリーの目は、ヘラツノの前足に止まっている。"}],[{w:"elly",t:"ピリポン、あの子に、ぱちって！",v:"05_0193"},{w:null,t:"ヤマトの目が、ヘラツノの止まった所に行く。"},{w:null,t:"ヤマトの目が、草の上を動く。"},{w:"hero",t:"フォルコン、まだ撃つな。あいつの下がる先で待て。",v:"05_0204"},{w:null,t:"エリー、石垣の前でしゃがむ。自分の手も、少しふるえている。"},{w:"elly",t:"ピリポン、進化！",v:"05_0215"}],[{w:null,t:"ヤニスの組んだ腕の指が、一本だけ動く。"},{w:null,t:"ヤマト、エリーの方を見る。だまって、うなずく。"},{w:"elly",t:"右！",v:"05_0225"},{w:"hero",t:"フォルコン、うしろをふさげ！",v:"05_0227"},{w:"elly",t:"ピリムサ！",v:"05_0230"},{w:"elly",t:"右！",v:"05_0234"}]],post:[{w:null,t:"ヘラツノが、草の上に、ころりと横になる。目を回している。"},{w:null,t:"アレク、ヤマトの腕を、ひじで小突く。"},{w:"alek",t:"……下がる先、いっつも同じやったんか。",v:"05_0239"},{w:null,t:"ヤマト、草の上の二つの跡を、つま先で一回なぞる。"},{w:"elly",t:"ピリムサ、えらいえらい！",v:"05_0241"}]};
GR_EP[5]={"t": "丘の畑", "sc": [["g05_01", "丘のオリーブの木の下（夜明け）", 0], ["g05_02", "丘の斜面（朝）", 0], ["g05_03", "ヤニスの畑", 0], ["g05_04", "向かい合う", 0], ["g05_05", "勝負・押される", 1], ["g05_06", "勝負・下がる先", 1], ["g05_07", "勝負・決着", 1], ["g05_08", "勝負のあと", 0], ["g05_09", "丘のてっぺん（夕方）", 0]]};
GR_SC.g06_01=[{w:null,t:"五日目の昼。アルカディアの森の、川べり。",v:"06_0028"},{w:null,t:"昼の森。乾いた落ち葉が、地面をうめている。"},{w:null,t:"川べりの大きな岩の上に、ニーナが黒い箱を置く。"},{w:null,t:"箱の穴から、言葉のない細い歌がもれる。草むらの奥で、小さな子が首を上げる。"},{w:null,t:"ニーナ、手首の画面にふれる。"},{w:"marco",t:"あばれると、網が破れるんだよなあ。",v:"06_0033"},{w:null,t:"ニーナ、足もとの小さなおりの戸をあける。"},{w:null,t:"【プロフィール】ビリトラ／雷／●○○／毛が逆立つと火花がはぜる"},{w:null,t:"虎の子の背中の毛が、逆立つ。"},{w:"marco",t:"……もう、それくらいでいいだろ。",v:"06_0037"},{w:"marco",t:"ちょっと、止めてくれよ。",v:"06_0040"},{w:"nina",t:"……止まんないのよ、これ。",v:"06_0041"},{w:"marco",t:"……ボスまで、止めねえのかよ。",v:"06_0047"},{w:null,t:"第6話　燃える森",v:"06_0051"}];
GR_SC.g06_02=[{w:null,t:"六日目の昼すぎ。",v:"06_0057"},{w:null,t:"森へ続く道。三人とも、目の下にくま。"},{w:null,t:"アルカディア。楽園という名の森だ。",v:"06_0059"},{w:null,t:"森の入口。木の枠の自動ゲート。"},{w:null,t:"アレク、パーカーのフードを深くかぶる。受付のロボットの目から、顔をそらす。"},{w:null,t:"エリー、白い肩かけカバンから、手のひら大のうすいカードを出す。"},{w:null,t:"カードの上に、のこりのお金の数字が光る。"},{w:null,t:"アレク、横からその数字をのぞきこむ。"},{w:"alek",t:"……減るの、速すぎやろ。",v:"06_0065"},{w:null,t:"アレク、エリーの手から、カードをすっと抜き取る。"},{w:"elly",t:"アレク、お金の計算、好きだもんね。",v:"06_0067"},{w:"alek",t:"好きでやってるんやない。",v:"06_0068"},{w:null,t:"アレク、カードをパーカーの内ポケットにしまう。"},{w:null,t:"ゲートが、すうっと開く。"}];
GR_SC.g06_03=[{w:null,t:"焦げたにおいが、だんだん強くなる。"},{w:null,t:"木のあいだがひらけた所。"},{w:null,t:"小川のふちに、手さげかばんほどの小さなポンプ。"},{w:"x",n:"作業員のおじさん",t:"泡は、これで終わりだ！　あとは水しかないぞ！",v:"06_0076"},{w:null,t:"アレク、もうクロッコを小川に下ろしている。"},{w:null,t:"エリー、肩のピリポンを髪の中へ押しもどして、バケツを回す人たちの中に入る。"},{w:null,t:"フォルン、燃える草の前に立つ。しっぽを、ひと振り。"},{w:null,t:"ヤマト、バケツの列に走っていって、前の人からバケツを受け取る。"},{w:null,t:"煙の向こうで、ぱちぱちっと新しい火の音。"},{w:null,t:"虎の子の頭のうしろで、チップがちかっと光る。目のふちが、オレンジ色。"},{w:"x",n:"作業員のおじさん",t:"あいつだ！　きのうから、あいつが火をつけて回ってる！",v:"06_0083"},{w:null,t:"虎の子を追って、煙の中から、すすだらけの二人組が走り出てくる。"},{w:"hero",t:"あっ！　マカロンと、えーと……！",v:"06_0085"},{w:"nina",t:"なによ、またあんたたちなの？",v:"06_0086"},{w:null,t:"ニーナの目が、小川のクロッコとアレクに止まる。"},{w:"nina",t:"……アレク？　あんた、そっちにいるの？",v:"06_0088"},{w:"alek",t:"（水をくみながら）仕事やめただけや。",v:"06_0089"},{w:"marco",t:"……え、やめれんの？",v:"06_0090"},{w:"hero",t:"お前らが燃やしたのかよ。",v:"06_0091"},{w:"nina",t:"燃えたのよ！　燃やしたんじゃないわ！",v:"06_0092"},{w:null,t:"ニーナの目が、ヤマトの足もとのフォルンに止まる。"},{w:"nina",t:"……ちょうどいいじゃないの。",v:"06_0094"},{w:"nina",t:"ボスがほしがってた狐よ。マルコ、もらっていくわよ！",v:"06_0095"},{w:"marco",t:"え、今か？　森、燃えてんだぞ。",v:"06_0096"},{w:"nina",t:"だからでしょ。だれも手が空いてないじゃないの。",v:"06_0097"},{w:"hero",t:"森が燃えてんのに、なに言ってんだよ！",v:"06_0098"},{w:null,t:"ニーナ、手首の画面を、虎の子の方へ向けてはじく。"},{w:"nina",t:"行きなさい！　狐をやっちゃって！",v:"06_0100"},{w:null,t:"虎の子の毛が逆立つ。"},{w:null,t:"フォルンが、その火の前に跳びこむ。しっぽで吸いこむ。"},{w:null,t:"スミヤモの小さな火と、フォルンのしっぽの火が、一瞬だけ重なって、太く立つ。"},{w:"x",n:"森番のおばあさん",t:"みんな、上の焼けあとまで下がるよ！",v:"06_0106"}];
GR_SC.g06_05=[{w:null,t:"ヤマトが大木のかげから走っていって、フォルンの前にしゃがむ。"},{w:null,t:"フォルン、ふらつきながら、ヤマトのうしろへ回って、座りこむ。"},{w:null,t:"ヤマト、ひざをついたまま、首をのばして、フォルンの背中をのぞく。"},{w:null,t:"背中の毛が、すすで黒い。"},{w:null,t:"ヤマト、こぶしを小さくにぎる。"},{w:"hero",f:"serious",t:"……お前、背中、煙出てんぞ。",v:"06_0182"},{w:null,t:"エリーが焼けあとから走ってくる。"},{w:"elly",t:"フォルン、背中、冷やそ！",v:"06_0184"},{w:null,t:"フォルン、そっぽを向いたまま、エリーの手の水を一回だけなめる。"},{w:null,t:"エリー、小川へもう一杯すくいに行って、もどってくる。"},{w:"hero",t:"エリー、ありがと。こいつ、水きらいなのに。",v:"06_0187"},{w:"elly",t:"え、そうなの？",v:"06_0188"},{w:null,t:"エリー、手の中の水を見る。"},{w:"hero",f:"serious",t:"……お前も、回すのか。",v:"06_0196"},{w:"marco",t:"今、それどころじゃないだろ。バケツ、次に回してくれ。",v:"06_0197"},{w:"hero",f:"serious",t:"……やるじゃん、ニンニクとマカロン。",v:"06_0200"},{w:"nina",t:"誰がニンニクとマカロンよ！",v:"06_0201"},{w:"nina",t:"ドローンが来たわ。写真に写る前に、行くわよ。",v:"06_0203"}];
GR_SC.g06_06=[{w:null,t:"森の裏がわの、舗装された細い道。"},{w:null,t:"木のあいだから、ニーナとマルコが出てくる。"},{w:null,t:"ニーナの手首の画面に、字。"},{w:null,t:"ニーナ、送り先の「本部」の欄を、長く押して消す。"},{w:null,t:"マルコ、スミヤモの耳のうしろのチップを見る。"},{w:null,t:"二人、車に背を向けて、反対がわの草の小道を歩きだす。"},{w:"marco",t:"……朝めし、まだだな。",v:"06_0213"},{w:"nina",t:"……行くわよ。",v:"06_0214"},{w:null,t:"うしろで、ドアがすうっと閉まる。"}];
GR_SC.g06_07=[{w:null,t:"ラドン川。この秋は、夜になると、川から歌が聞こえる。",v:"06_0218"},{w:null,t:"森の外がわを流れる川。"},{w:null,t:"その下に、小さな赤い字。"},{w:null,t:"船着き場に、白い小さな観光船。"},{w:"hero",f:"surprised",t:"（字を見上げて）森、通れねえってさ。",v:"06_0222"},{w:null,t:"アレクは、もう切符の機械の前。エリーは案内のロボットに手をふる。"},{w:"alek",t:"（カードを出しながら）船、安いで。",v:"06_0224"},{w:"hero",f:"serious",t:"……お前、安い時だけ足速えな。",v:"06_0225"},{w:null,t:"アレク、カードを機械に当てる。"},{w:null,t:"エリー、ねむそうなヤマトの背中を押して、アレクのうしろから船に乗る。"}];
GR_SC.g06_08=[{w:null,t:"白い小さな観光船。だれも舵をにぎっていない。"},{w:null,t:"エリー、カバンから光るテリオンのシール帳を出す。"},{w:"elly",t:"ねえねえ、シール交換しよ！",v:"06_0232"},{w:null,t:"ヤマトは、光る川を見ている。"},{w:null,t:"アレク、カードを見たまま、手のひらだけエリーの方へ出す。"},{w:null,t:"エリー、目を丸くして、その手のひらにシールを一枚貼る。"},{w:null,t:"アレク、見もせずに、そのシールをゴーグルのバンドに貼る。"},{w:null,t:"エリー、にこにこして、次のシールを選ぶ。"},{w:null,t:"案内のロボットが、かごを持って回っている。"},{w:null,t:"エリーがフォルンにも耳あてを持っていく。"},{w:null,t:"ヤマトだけ、耳せんを取らない。"},{w:"elly",t:"ヤマト、耳せんしないの？",v:"06_0242"},{w:"hero",t:"だって、どんな歌か聞いてみたいじゃん。",v:"06_0243"},{w:"alek",t:"聞いたら、川に入ってまう歌らしいで。",v:"06_0244"},{w:null,t:"ヤマト、船のまん中の太い柱を見上げる。"},{w:"hero",t:"じゃあさ、あの柱におれをしばっといてくれよ。",v:"06_0246"},{w:"hero",t:"それなら、飛びこめないだろ。",v:"06_0247"},{w:"alek",t:"言うとくけど、着くまで、ほどかへんで。",v:"06_0249"},{w:"hero",t:"いいって。おれ、そんなのに負けねーし。",v:"06_0250"},{w:"elly",t:"……歌を聞いた船長は、自分を柱にしばらせたんだって。",v:"06_0254"},{w:"hero",f:"serious",t:"……で、その船長、どうやってほどいたんだ。",v:"06_0257"},{w:"elly",f:"serious",t:"……歌が終わるまで、そのままだって。",v:"06_0258"}];
GR_SC.g06_09=[{w:null,t:"川幅が広くなる。"},{w:null,t:"歌が聞こえてくる。"},{w:null,t:"船べりのフォルンのしっぽの火が、ぱちぱちと大きく鳴りだす。"},{w:null,t:"フォルン、耳を伏せて、自分の火の音の中にうずくまる。"},{w:null,t:"岸の葦のあいだから、野生の子たちが出てくる。"},{w:null,t:"ヤマトの目が、その子たちを追う。"},{w:"hero",t:"ちょっと、ほどけ！　ちょっとだけでいいから！",v:"06_0270"},{w:"hero",t:"エリー！　ほどけって！　エリーってば！",v:"06_0273"},{w:"hero",t:"フォルン！　あの岩の箱だ！　あそこから鳴ってる！",v:"06_0279"},{w:"alek",t:"なんや、ずっと口が動いてたけど。何か言うてたんか？",v:"06_0288"},{w:"hero",f:"serious",t:"……べつに。ぜんぜん、平気だったし。",v:"06_0289"},{w:"alek",t:"結び目、三つにしといて正解やったな。",v:"06_0290"}];
GR_SC.g06_10=[{w:null,t:"最後の船着き場。"},{w:"alek",t:"あの箱、昼の二人のや。",v:"06_0297"},{w:null,t:"ヤマト、暗い川の上の方を、ふり返る。"},{w:null,t:"岸から上がる道に、細い柱が二本。"},{w:null,t:"ひもの向こうは、まっ暗な森。"},{w:"alek",t:"今夜は、どっか寝るとこさがすしかないわ。",v:"06_0301"},{w:null,t:"道のわきの明かりの方へ歩く。"},{w:null,t:"地面が、ひもで四角く区切ってある。"},{w:"x",n:"女の人",t:"……こんな夜ふけに、何の用？",v:"06_0308"},{w:"elly",t:"こんばんは！　今夜、泊まれる所はありませんか！",v:"06_0309"},{w:"alek",t:"床でええんで。お願いします。",v:"06_0310"},{w:"x",n:"女の人",t:"……床でいいなら、入って。",v:"06_0312"}];
GR_BT[6]={mid:[[{w:"hero",f:"surprised",t:"フォルン、追え！",v:"06_0114"},{w:null,t:"ヤマト、大木のかげから半分身を出して、手をふり回す。"},{w:"marco",t:"出んな！　引っこんでろ！",v:"06_0121"},{w:null,t:"ヤマト、大木のかげのはしで、その声に手が止まる。"},{w:null,t:"ヤマト、転がったフォルンを見る。ふり回していた手を、ゆっくり下ろす。"},{w:"nina",t:"もう一発！",v:"06_0125"},{w:"nina",t:"ちょっと、そっちじゃないわよ！　狐だけでいいの！",v:"06_0132"},{w:null,t:"ニーナ、画面をはじく。"}],[{w:"marco",t:"ニーナ、止めろって！",v:"06_0134"},{w:"nina",t:"……止まんないのよ！",v:"06_0135"},{w:null,t:"ニーナ、画面の「止めるな」を見る。それから、あとずさる村の人たちを見る。"},{w:null,t:"ヤマトの目が、虎の子から、おばあさんの足もとの火へ動く。"},{w:"hero",t:"フォルン、撃つな！　あっちの火だ！",v:"06_0139"},{w:null,t:"ヤマト、焼けあとの手前の火を、まっすぐ指さす。"},{w:null,t:"おばあさんの足もとの火の前に、すべりこむ。しっぽをひと振り。"},{w:null,t:"ヤマトのとなりで、マルコがそれを見ている。"},{w:"marco",t:"……スミヤモ、行くぜ。",v:"06_0147"},{w:"nina",t:"マルコ！　あんた、どっちの味方よ！",v:"06_0148"}],[{w:"marco",t:"森ごと燃えたら、狐もなにもねえだろ！",v:"06_0149"},{w:null,t:"ヤマト、となりのマルコのそでを引く。"},{w:null,t:"ヤマト、人さし指で、スミヤモとフォルンから一本ずつ線を引き、虎の子の上で結ぶ。"},{w:null,t:"マルコの目が、その指を追う。"},{w:"marco",t:"おい！　そっちからも寄せろ！",v:"06_0155"},{w:"hero",t:"おう！　フォルン、前だ！",v:"06_0156"},{w:null,t:"ヤマト、指をそろえた手のひらを、フォルンへまっすぐ立てる。"},{w:"hero",t:"フォルン、今だ！",v:"06_0164"},{w:"marco",t:"スミヤモ、いっしょにやれ！",v:"06_0165"}]],post:[{w:null,t:"頭のうしろのチップが、ぱきっと割れる。目のふちのオレンジ色が、すうっと消える。"},{w:null,t:"虎の子、起き上がって、ぶるっと水をはらう。"},{w:null,t:"焼けあとから、アレクがバケツを下げて走り下りてくる。"},{w:"alek",t:"火ぃ二つ合わせたら、太なるんか。",v:"06_0173"}]};
GR_EP[6]={"t": "燃える森", "sc": [["g06_01", "アルカディアの森・川べりの岩（5日目の昼）", 0], ["g06_02", "アルカディアの森の入口（6日目の昼すぎ）", 0], ["g06_03", "森の中（昼すぎ）", 0], ["g06_04", "勝負・森の火（2Dアニメ）", 1], ["g06_05", "森の中・火のあと（昼すぎ）", 0], ["g06_06", "森の裏の道（夕方前）", 0], ["g06_07", "川の船着き場（夕方）", 0], ["g06_08", "観光船の上（夜）", 0], ["g06_09", "歌の瀬（夜）", 0], ["g06_10", "森の外れの船着き場（夜ふけ）", 0]]};
GR_SC.g07_01=[{w:null,t:"森の外れの発掘場。三人は、ここの小屋に泊めてもらった。",v:"07_0025"},{w:null,t:"組み立て式の小屋の中。"},{w:null,t:"女の人が、床の手前の半分を指さす。"},{w:"x",n:"女の人",t:"奥は、先に来た子が使ってるから。",v:"07_0028"},{w:null,t:"奥の床に、銀色のシート。"},{w:null,t:"【字幕】「レン」。"},{w:"x",n:"女の人",t:"今夜は、迷子がよく来るねえ。",v:"07_0031"},{w:null,t:"ヤマト、手首の画面でテリオンの動画を開く。"},{w:"dimi",f:"serious",t:"……日本の人？",v:"07_0033"},{w:"hero",t:"そうだけど。……え、日本語しゃべれんの？",v:"07_0034"},{w:"dimi",t:"親が日本人なんだ。おれは、アメリカから来た。",v:"07_0035"},{w:"elly",t:"へえ、アメリカから。わたしはエリー。こっちはヤマト。",v:"07_0036"},{w:"dimi",t:"レン。",v:"07_0037"},{w:null,t:"レン、それだけ言って、手首の画面に目をもどす。"},{w:null,t:"アレク、首をのばして、レンの横顔をのぞきこむ。"},{w:"alek",t:"レンって……前の大会で優勝した、あのレンか？",v:"07_0040"},{w:"dimi",t:"ああ。",v:"07_0041"},{w:null,t:"エリー、口に手を当てる。"},{w:"hero",f:"serious",t:"……配信の、蛇のやつか！",v:"07_0043"},{w:"hero",t:"今年も出んのか。",v:"07_0044"},{w:"dimi",t:"出る。",v:"07_0045"},{w:"hero",t:"おれも出る！",v:"07_0046"},{w:null,t:"レンの目が、戸口で丸くなっているフォルンの、しっぽの火に行く。"},{w:"dimi",t:"あの狐、お前の相棒か？",v:"07_0048"},{w:"hero",t:"相棒だよ。……まだ登録してねえけど。",v:"07_0049"},{w:null,t:"ヤマト、戸口の方を指さす。"},{w:null,t:"フォルンの耳だけが、奥のレンの方へ向いている。"},{w:"dimi",t:"その狐、お前の言うこと聞くのか？",v:"07_0052"},{w:"hero",t:"聞くよ！　……たまに。",v:"07_0053"},{w:null,t:"レン、それには何も言わない。手首の画面に目をもどす。"},{w:null,t:"レンの画面に、写真が一枚。"},{w:null,t:"レン、画面を消して、シートに横になる。"},{w:null,t:"ヤマト、エリーに顔を寄せる。"},{w:"hero",t:"（小声で）なんか、感じわりいな。アメリカのやつ。",v:"07_0058"},{w:"elly",t:"（小声で）名前、レンだって。さっき聞いたでしょ。",v:"07_0059"},{w:"hero",t:"（小声で）聞いた。忘れた。",v:"07_0060"},{w:"alek",t:"（小声で）……おれの名前は、覚えてるやろな。",v:"07_0061"},{w:null,t:"第7話　発掘場",v:"07_0063"}];
GR_SC.g07_02=[{w:null,t:"次の日の朝。",v:"07_0069"},{w:null,t:"朝の光。ひもで四角く区切った地面に、掘りかけの穴がいくつも。"},{w:null,t:"奥の床の銀色のシートは、きちんとたたんである。"},{w:null,t:"ヤマト、青いシートのまわりを、ぐるぐる回っている。"},{w:null,t:"小屋から、女の人が出てくる。"},{w:"x",n:"女の人",t:"それ、気になる？",v:"07_0074"},{w:"hero",t:"なる！　きのうの夜から、ずっと気になってたんだよ。",v:"07_0075"},{w:"x",n:"女の人",t:"じゃあ、朝ごはんの前に、ちょっとだけね。",v:"07_0076"},{w:null,t:"女の人、手首の画面にふれる。"},{w:null,t:"シートの下は、赤土の大きな岩。"},{w:null,t:"へこみの中は、空っぽ。"},{w:null,t:"ヤマト、一歩下がって、首をそらして見上げる。"},{w:"hero",f:"serious",t:"……でっけえ。これ、なんの骨？",v:"07_0081"},{w:"x",n:"女の人",t:"骨じゃなくて、骨の型なの。",v:"07_0082"},{w:"alek",t:"型ってことは……骨は、どこにあるんすか。",v:"07_0083"},{w:"x",n:"女の人",t:"三年掘ってるけど、かけら一つ出てこない。",v:"07_0084"},{w:"alek",t:"三年で、ゼロ……。それ、元取れるんすか。",v:"07_0085"},{w:null,t:"足もとのクロッコが、アレクを見上げる。"},{w:"x",n:"女の人",t:"取れてたら、もっといい小屋に住んでるよ。",v:"07_0087"},{w:null,t:"アレク、前髪から水をたらしたまま、真顔で、型のふちを目で追っていく。"},{w:null,t:"ヤマト、型の肩のあたりの、なだらかに盛り上がった線を見上げている。"},{w:null,t:"山のようにまるく盛り上がって、先でがくっと落ちる形。"},{w:"hero",t:"（女の人に）肩んとこ、山みてえ。",v:"07_0092"},{w:"x",n:"女の人",t:"でしょ。……今日は村の子の発掘体験の日なの。",v:"07_0093"},{w:"x",n:"女の人",t:"手伝ってくれる？",v:"07_0094"},{w:null,t:"エリー、アイボリーのニットに、濃い色のまっすぐなデニム。"},{w:null,t:"髪は肩にかけた一本の三つ編み。"},{w:"elly",t:"まかせて！　ふるい、どこ？",v:"07_0097"},{w:"hero",t:"おれは化石掘りたい！　どこ掘りゃいい？",v:"07_0098"},{w:"x",n:"女の人",t:"ひもの中はだめ。ふるいは、小屋の前。",v:"07_0099"},{w:"x",n:"女の人",t:"きみも、子どもたちとふるいの係ね。",v:"07_0100"},{w:null,t:"ヤマト、肩を落とす。"}];
GR_SC.g07_03=[{w:null,t:"村の子どもたちが五人。"},{w:null,t:"仕分けのロボットが、四本の足で歩きながら、ふるいに残った石を箱に分けていく。"},{w:null,t:"ヤマトも、子どもたちにまざって、ふるいをふる。"},{w:null,t:"女の人が、手をたたいて、子どもたちを型の前に集める。"},{w:"x",n:"女の人",t:"はい、休けい。この型の昔話、してあげる。",v:"07_0108"},{w:null,t:"女の人、小屋の壁の古い石板を指さす。"},{w:null,t:"大きな生き物の前で、人が口をあけている彫り物。"},{w:null,t:"エリーも座る。"},{w:"x",n:"女の人",t:"大昔の生き物は、昔の言葉しか聞かないんだって。",v:"07_0112"},{w:"x",n:"村の女の子",t:"じゃあ、昔の言葉で「おすわり」って言ったら？",v:"07_0113"},{w:"x",n:"女の人",t:"するする。骨だけになっても、たぶんするよ。",v:"07_0114"},{w:null,t:"子どもたちが笑う。"},{w:null,t:"エリーの、ピリポンの頭をなでていた指が、一度だけ止まる。"},{w:null,t:"石板のすみ。"},{w:"x",n:"村の男の子",t:"これ、ひもで引っぱってんの？",v:"07_0118"},{w:"x",n:"村の女の子",t:"ひもじゃ無理だよ！　ちぎれちゃうって。",v:"07_0119"},{w:"x",n:"女の人",t:"だよねえ。村のおばあちゃんたちも、知らないの。",v:"07_0120"},{w:null,t:"子どもたちが、日なたのフォルンのまわりに集まる。しっぽの先で、火がゆれている。"},{w:"x",n:"村の女の子",t:"この子、しっぽが燃えてる！　だれの子？",v:"07_0122"},{w:null,t:"ヤマト、ふるいを置いて、すっと立ち上がる。"},{w:"hero",t:"おれの相棒。フォルンっていうんだ。",v:"07_0124"},{w:null,t:"フォルン、目をあけずに、しっぽを一回ふる。"},{w:"x",n:"村の男の子",t:"この子、強いの？",v:"07_0126"},{w:"hero",t:"強えぞ。白い都の大会にも出るしな。",v:"07_0127"},{w:"hero",t:"優勝なんか、楽勝だって。",v:"07_0128"},{w:null,t:"日なたのフォルン、片目だけあけて、ヤマトを見る。"},{w:null,t:"少しはなれたアレク、ため息をひとつ。"},{w:"x",n:"村の男の子",t:"すげえ！",v:"07_0131"},{w:"x",n:"村の女の子",t:"それ、世界じゅうから来る大会でしょ？",v:"07_0132"},{w:"hero",t:"そう。で、おれが世界一。",v:"07_0133"}];
GR_SC.g07_04=[{w:null,t:"ヤマト、子どもたちのあいだを抜けて、レンの方へ歩いていく。"},{w:"hero",t:"おい、アメリカ。今、笑ったろ。",v:"07_0140"},{w:"dimi",t:"笑ってない。",v:"07_0141"},{w:"hero",t:"笑ったって！　ほんとに勝てるから言ってんだよ！",v:"07_0142"},{w:"dimi",t:"大会に出るなら、どうせどこかで当たる。",v:"07_0143"},{w:"dimi",t:"今やるか？",v:"07_0144"},{w:"hero",t:"やって——",v:"07_0145"},{w:null,t:"アレクが、うしろからヤマトの肩をつかむ。"},{w:"alek",t:"待て待て、前の優勝者やぞ。",v:"07_0147"},{w:"alek",t:"テリオンも見えへんのに、受けんなや。",v:"07_0148"},{w:null,t:"ヤマト、アレクの手をふりはらう。"},{w:"hero",t:"テリオンなんか、どっかにいんだろ。やってやるよ！",v:"07_0150"},{w:"x",n:"女の人",t:"はい、そこまで。今は子どもたちがいるでしょ。",v:"07_0151"},{w:"x",n:"女の人",t:"やるなら夕方。ひもの外でね。型にだけは当てないで。",v:"07_0152"},{w:"dimi",t:"わかった。夕方まで待つ。",v:"07_0153"},{w:null,t:"レン、木のかげへもどって、また画面を見る。"},{w:null,t:"ヤマト、ふくれっつらで、ふるいの係にもどる。"},{w:null,t:"レンの足もとの地面。"},{w:null,t:"盛り上がった土のすき間から、緑の目が一つ、のぞく。"},{w:null,t:"小鳥の羽から色が抜けて、灰色のまま、ぴたりと止まる。"}];
GR_SC.g07_06=[{w:null,t:"女の人が来て、型の青いシートの焦げたはしを、指でつまむ。"},{w:"x",n:"女の人",t:"……型は、無事。あの子、強かったね。",v:"07_0233"},{w:null,t:"アレク、灰色のクロッコをだき上げる。"},{w:null,t:"アレク、クロッコの灰色の目と、穴のあとを見くらべる。"},{w:"alek",t:"目ぇ合うたら、固まるんか。",v:"07_0236"},{w:null,t:"ヤマト、アレクの腕の中の、灰色のクロッコを見る。"},{w:null,t:"クロッコの口は、水を吐きに行った形のまま、開いている。"},{w:"hero",t:"分かってるよ。",v:"07_0239"},{w:null,t:"ヤマト、その場にひざをつく。"},{w:"hero",f:"angry",t:"くそっ……！",v:"07_0241"},{w:null,t:"ヤマト、立ち上がって、倒れたフォルンの方へ歩いていく。"},{w:null,t:"レン、何も言わずに小屋の方へ歩いていく。"},{w:"hero",t:"エリー、テリオンの薬、ちょっと借りるぞ。",v:"07_0250"},{w:"elly",t:"いいよ。そっとね。",v:"07_0251"},{w:"elly",t:"ちょっと、また右手！　ほら、見せて。",v:"07_0257"},{w:"hero",t:"サンキュ、エリー。",v:"07_0259"}];
GR_SC.g07_07=[{w:null,t:"光る板の下のテーブル。"},{w:null,t:"女の人が、奥のレンにテーブルを指さして呼ぶ。レンは首を横にふって、奥のシートの上で一人で食べている。"},{w:null,t:"ヤマト、スープに口をつけない。"},{w:"elly",t:"ヤマト、ご飯、先。",v:"07_0266"},{w:"hero",f:"serious",t:"……食ってるって。",v:"07_0267"},{w:null,t:"ヤマト、豆を一つだけ口に入れる。"},{w:null,t:"エリー、自分のパンを半分にちぎって、だまってヤマトの皿に置く。"},{w:"alek",t:"食わへんなら、それ、おれがもらうで。",v:"07_0270"},{w:null,t:"アレクの手が、ヤマトの皿のパンにのびる。"},{w:"alek",t:"なんや、くれへんのか。",v:"07_0272"},{w:null,t:"アレク、自分のスープをすする。"},{w:"elly",t:"ねえ、あの型の主って、何を食べてたの？",v:"07_0275"},{w:"x",n:"女の人",t:"それがね、歯が一本も出てこないの。",v:"07_0276"},{w:"x",n:"女の人",t:"生きてるところ、一回でいいから見てみたいね。",v:"07_0277"}];
GR_SC.g07_08=[{w:null,t:"夜ふけ。みんな寝ている。ヤマトだけ、目をあけている。"},{w:null,t:"ヤマト、シートから出る。"},{w:null,t:"ヤマト、フォルンの背中の前の床に置く。"},{w:null,t:"フォルン、目をあけない。"},{w:null,t:"ヤマト、小屋の戸をそっとあける。"},{w:null,t:"月の光。小屋のわきの地面が、こんもり盛り上がっている。"},{w:null,t:"ヤマト、少しはなれた所に、ひざを抱えて座る。"},{w:null,t:"じっと見ている。"},{w:null,t:"小屋の戸が、うしろで静かにあく。"},{w:"dimi",f:"serious",t:"……まだ見てんのか。",v:"07_0291"},{w:null,t:"ヤマトの背中は動かない。目は、バジリクのまぶたのまま。"},{w:null,t:"レン、ヤマトの見ている先を見る。"},{w:"dimi",t:"あしたの朝、先に出る。",v:"07_0294"},{w:"dimi",t:"大会で待ってる。",v:"07_0295"},{w:"hero",t:"（ふり向かずに）……次は、「終わり」って言わせねえ。",v:"07_0296"},{w:"dimi",f:"serious",t:"……言ってろ。",v:"07_0297"},{w:null,t:"レン、背を向けて、小屋へもどる。"},{w:null,t:"ヤマト、ばんそうこうの指で、足もとの赤土に、閉じた目を一つ描く。"},{w:null,t:"消して、もう一回描く。"},{w:null,t:"小屋の角の暗がり。"},{w:null,t:"フォルン、ヤマトの背中を見ている。しっぽの火が、小さくゆれる。"},{w:null,t:"月が、小屋の屋根の向こうへ動いていく。"}];
GR_BT[7]={mid:[[{w:null,t:"夕方。子どもたちが帰ったあとの発掘場。",v:"07_0164"},{w:null,t:"レン、骨の型の横の、区画のロープの外まで下がって立つ。"},{w:null,t:"ヤマト、息をのむ。"},{w:null,t:"レンの手首の画面。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"……やばいで、こいつ。",v:"07_0174"},{w:"hero",f:"serious",t:"……だったら、三体で囲んでやろうぜ。",v:"07_0176"},{w:"dimi",t:"三体まとめてでいい。",v:"07_0177"}],[{w:"hero",t:"あとで、三対一はずるいとか言うなよ！",v:"07_0179"},{w:"dimi",t:"言わない。いつでも来い。",v:"07_0181"},{w:"elly",t:"ピリポン、いける？",v:"07_0182"},{w:null,t:"ヤマトとエリー、左の手首の画面をかざす。"},{w:"x",n:"二人",t:"進化！",v:"07_0186"},{w:"hero",t:"バラバラに行け！",v:"07_0189"}],[{w:"elly",t:"ピリムサ、前で引きつけて！",v:"07_0190"},{w:"alek",t:"クロッコ、右から回れ！",v:"07_0191"},{w:null,t:"レン、焦げ目を見もせず、画面に目をもどす。"},{w:"dimi",t:"バジリク、もぐれ。",v:"07_0197"},{w:"hero",t:"穴のまわり、かこめ！",v:"07_0200"},{w:null,t:"ヤマトの目だけが、それを見ている。"},{w:"dimi",t:"魔眼封石（まがんロック）。",v:"07_0210"}]],post:[{w:null,t:"小さなクロッコは、灰色になったその場で、ころりと横に倒れて目を回す。"},{w:"elly",t:"ピリムサ！",v:"07_0214"},{w:"alek",t:"クロッコ！",v:"07_0215"},{w:"hero",t:"なんだ、今の……！",v:"07_0216"},{w:null,t:"光の輪は、顔を伏せたフォルコンの背中の毛の上を、すべって消える。"},{w:null,t:"フォルコン、顔を伏せたまま、低い所から炎を吐く。"},{w:null,t:"バジリクの前足の鱗に、小さな黒い焦げあとが一つ。"},{w:null,t:"レン、下を向いたままのフォルコンを見る。"},{w:"hero",t:"フォルコン、よけろ！",v:"07_0222"},{w:"dimi",t:"終わり。",v:"07_0228"}]};
GR_EP[7]={"t": "発掘場", "sc": [["g07_01", "発掘場の小屋（6日目の夜ふけ）", 0], ["g07_02", "発掘場（7日目の朝）", 0], ["g07_03", "発掘場・体験の場所（昼前）", 0], ["g07_04", "型の前（昼）", 0], ["g07_05", "発掘場（夕方）　勝負", 1], ["g07_06", "勝負のあと（夕方）", 0], ["g07_07", "小屋の中（夜）", 0], ["g07_08", "小屋の外（夜ふけ）", 0]]};
GR_SC.g08_01=[{w:null,t:"森の道が開いた朝。三人は、海ぞいの道を港へ向かった。",v:"08_0028"},{w:null,t:"海ぞいの白い道。"},{w:null,t:"ヤマトの右手の指に、ばんそうこう。"},{w:null,t:"ヤマト、ふり返る。"},{w:"hero",f:"serious",t:"……あいつ、ずっと五歩うしろだぞ。",v:"08_0032"},{w:"alek",t:"きのう、お前のことかんだからやろ。",v:"08_0033"},{w:null,t:"エリー、五歩うしろのフォルンと、ヤマトの横顔を見る。"},{w:null,t:"エリー、歩きながら左の手首の白い画面を開く。"},{w:null,t:"光る星の字。"},{w:"elly",t:"ねえねえ、うらない、しよ。ヤマトから。",v:"08_0037"},{w:"elly",t:"旅の予定、決める派？　決めない派？",v:"08_0038"},{w:"hero",t:"決めない。",v:"08_0039"},{w:"elly",t:"はやっ。……知らない子がいたら、話しかける？　見てる？",v:"08_0040"},{w:"hero",t:"話しかける。",v:"08_0041"},{w:"elly",t:"怒られたら、すぐ忘れる？　ずっと気にする？",v:"08_0042"},{w:"hero",t:"忘れる。",v:"08_0043"},{w:null,t:"ヤマトは前を向いたまま。"},{w:"elly",t:"ヤマトは、「自由を愛するエンターテイナー」だって！",v:"08_0046"},{w:"hero",t:"えんたーていなー？　……それ、強いのか。",v:"08_0047"},{w:"alek",t:"強さの占いちゃうねん。",v:"08_0048"},{w:null,t:"ヤマト、首をかしげる。"},{w:"elly",t:"次、アレク。旅の予定、決める派？　決めない派？",v:"08_0050"},{w:"alek",t:"宿は決める。船は値段しだい。行き先は決めへん。",v:"08_0051"},{w:"elly",t:"それ、どっち？",v:"08_0052"},{w:null,t:"エリー、くちびるをとがらせて、画面の問いの字を指で打ち直す。"},{w:null,t:"問いの字が、一行長くなる。"},{w:"elly",t:"アレクは、「孤高の論客」。",v:"08_0056"},{w:null,t:"ヤマト、横から画面の字を見て、目を細める。"},{w:null,t:"アレク、あごに手を当てて、前を向いたまま一回うなずく。"},{w:"alek",t:"孤高……ええやん。",v:"08_0059"},{w:"hero",t:"エリーは？　なんて出たんだよ。",v:"08_0060"},{w:"elly",t:"ないしょ。",v:"08_0061"},{w:"alek",t:"当てたろか。「着がえが、おそい人」や。",v:"08_0062"},{w:null,t:"エリーの肩で、ピリポンが、アレクの方へぷいっとおしりを向ける。"},{w:"hero",t:"腹へった。",v:"08_0064"},{w:"alek",t:"昼は、パンの耳な。",v:"08_0065"},{w:null,t:"二人、そのまま先を歩いていく。"},{w:null,t:"エリー、閉じかけた画面を、二人の方へ少しかたむける。"},{w:null,t:"光る字が一行。"},{w:null,t:"エリー、画面をぱちんと閉じる。"},{w:null,t:"エリー、道ばたの古い石の道しるべの前で、ぴたりと止まる。"},{w:"elly",t:"あっ、ここだ！",v:"08_0071"},{w:null,t:"先を行く二人が、ふり返る。"},{w:"elly",t:"ねえ、ちょっとだけ寄り道していい？",v:"08_0073"},{w:"hero",t:"寄り道って、どこにだよ。",v:"08_0074"},{w:null,t:"エリーの指の先。"},{w:"elly",t:"ぶどう小屋！　毎年、遊びに来てるの。",v:"08_0076"},{w:"alek",t:"港まで、まだ二日かかるんやで。",v:"08_0077"},{w:null,t:"エリー、肩のピリポンをおさえて、道しるべの古い字を指でなぞっている。"},{w:null,t:"なぞり終えると、そのまま坂の下へ走っていく。"},{w:"hero",t:"しょうがねえな。行くぞ、アレク！",v:"08_0080"},{w:"alek",t:"なんでお前が仕切るんや。",v:"08_0081"},{w:null,t:"第8話　エリーのぶどう小屋",v:"08_0083"}];
GR_SC.g08_02=[{w:null,t:"坂の下の小さな村。"},{w:null,t:"通りのすみに、小さな占いの店。"},{w:null,t:"エリー、光る星の看板を見上げたまま、布をくぐって中へ入る。"},{w:"hero",t:"おい、エリー！　ぶどう小屋は？",v:"08_0092"},{w:"alek",t:"……もう、聞こえてへんわ。",v:"08_0093"},{w:null,t:"店の中。うす暗い小さな部屋。"},{w:null,t:"水晶の中を、星の形の字がゆっくり流れている。"},{w:null,t:"占い師は70代くらいの女の人。"},{w:null,t:"エリー、丸いいすに座る。水晶に、両手をそっとかざす。"},{w:null,t:"戸口の布のすきまから、ヤマトとアレクの顔がのぞいている。"},{w:"x",n:"占い師",t:"……近いうちに、大事な物を、一度なくすね。",v:"08_0099"},{w:"elly",f:"surprised",t:"えっ、なくすの？　何を？",v:"08_0100"},{w:"x",n:"占い師",t:"それは、水晶にも映らないよ。",v:"08_0101"},{w:"elly",f:"serious",t:"……ちゃんと、取りもどせる？",v:"08_0102"},{w:"x",n:"占い師",t:"あなたしだいだね。……それから、竜が見える。",v:"08_0103"},{w:"x",n:"占い師",t:"青い目の竜が、あなたを待ってる。",v:"08_0104"},{w:"elly",t:"竜!?　どこで待ってるの？",v:"08_0105"},{w:"x",n:"占い師",t:"東の、ずっと遠く。",v:"08_0106"},{w:"x",n:"占い師",t:"今日のラッキーカラーは、黄色。",v:"08_0107"},{w:null,t:"エリー、自分のアイボリーのニットを見下ろす。"},{w:null,t:"店の外。エリー、布をくぐって出てくる。"},{w:"elly",t:"なくし物するって！　あと、竜が待ってるって！",v:"08_0110"},{w:"hero",t:"そんなん信じんなよ〜",v:"08_0111"},{w:"alek",t:"あんなもん、みんなに当てはまること言うてるだけや。",v:"08_0112"},{w:"elly",t:"（横目で）……孤高、ええやん、って言ってたくせに。",v:"08_0113"},{w:"alek",t:"あれは、当たってたからや。",v:"08_0114"},{w:null,t:"エリーの目は、もう向かいの小さな服の店の窓。"},{w:null,t:"エリー、黄色のニット。"},{w:null,t:"ぬいぐるみの横に、黄色いクッキーの形のチャーム。"},{w:null,t:"肩のピリポン、ぬいぐるみをのぞきこむ。首をかしげる。"},{w:null,t:"ヤマトは坂の下の畑を、アレクは望遠鏡で海の方を見ている。"},{w:"elly",t:"ぶどう小屋、こっちだよ！",v:"08_0121"},{w:null,t:"エリー、通りを先にかけていく。"}];
GR_SC.g08_03=[{w:null,t:"村のはずれ。"},{w:null,t:"棚の下を、収穫のロボットが一台、ゆっくり歩いている。"},{w:null,t:"となりの段は、観光の農園。"},{w:null,t:"棚のはしの、鳥よけの細い網。"},{w:null,t:"【プロフィール】ピーグル／風／●○○／緑の冠羽のタカの子"},{w:null,t:"ヤマト、すぐに網へ手をのばす。"},{w:null,t:"ピーグル、羽を逆立てて、キイッと鳴く。"},{w:"elly",t:"ヤマト、ストップ。",v:"08_0133"},{w:null,t:"エリー、ヤマトの手をそっと下ろさせる。"},{w:null,t:"エリー、ゆっくりまばたきする。両手を、ひざの上で開いて見せる。"},{w:null,t:"ピーグルのばたつきが、止まる。首をかしげて、エリーの指先を見る。"},{w:"elly",t:"こわかったね。今、ほどくからね。",v:"08_0137"},{w:null,t:"エリー、網の目を、一つずつ指でゆるめていく。"},{w:null,t:"網から出たピーグル、エリーの腕を伝って、肩までかけ上がる。"},{w:null,t:"エリー、カバンから小さな薬の筒と、すきとおった貼りものを出す。"},{w:null,t:"ピーグル、エリーの耳のうしろに顔をうずめる。"},{w:null,t:"エリーの髪の中から、ピリポンが顔を出す。"},{w:"elly",t:"ピリポン、やきもちやかないの。",v:"08_0143"},{w:"hero",t:"（ピーグルへ、もう手をのばしながら）なんでエリーには、すぐ寄ってくんだよ。",v:"08_0144"},{w:"elly",t:"（ヤマトの手を見て）……ほら、その手。",v:"08_0145"},{w:null,t:"ヤマト、のびた自分の手を見て、ひっこめる。"},{w:null,t:"五歩うしろのフォルンを見る。"}];
GR_SC.g08_04=[{w:null,t:"棚の高い所に、ロボットの手が届かなかった房が、ぽつぽつ残っている。"},{w:null,t:"アレクのカゴは、まだ底が見えている。"},{w:null,t:"小屋の戸口。"},{w:null,t:"となりの段から、ぶどう畑のおじさんとおばさんが、からのカゴを持って下りてくる（2100年の作業着）。"},{w:"x",n:"おじさん",t:"おう、エリー。今年も来たか。",v:"08_0154"},{w:"elly",t:"来たよ！　この二人、旅の仲間なの。",v:"08_0155"},{w:"hero",t:"なあ、戸の上の石、なんて書いてあんの？",v:"08_0156"},{w:"x",n:"おじさん",t:"昔の字で読めねえ。勇者さまが化け物を追いはらった石だ。",v:"08_0157"},{w:"hero",t:"化け物!?　どんなやつ？",v:"08_0158"},{w:"x",n:"おばさん",t:"それがね、だれも見たことないの。",v:"08_0159"},{w:null,t:"エリー、つま先立ちになる。"},{w:null,t:"苔の下から、字のとなりの彫り物が出てくる。"},{w:"elly",f:"surprised",t:"えっとね……「大きなけものが、ぶどうを食べに来る」。",v:"08_0163"},{w:"elly",t:"「半分あげれば、戸はこわされない」。",v:"08_0164"},{w:"hero",f:"serious",t:"……それだけ？",v:"08_0166"},{w:"elly",t:"うん。あと、「今年は、あげすぎた」だって。",v:"08_0167"},{w:null,t:"おじさんとおばさん、ゆっくり顔を見合わせる。"},{w:"x",n:"おじさん",t:"……勇者さまは？",v:"08_0169"},{w:"elly",t:"どこにも出てこないよ。",v:"08_0170"},{w:"x",n:"おばさん",t:"毎年、あの石に頭下げてたのに……。",v:"08_0171"},{w:"alek",t:"ぶどうの分け方のメモやん。",v:"08_0172"},{w:null,t:"おじさん、カゴを落とす。"},{w:null,t:"坂の上から、村の人が一人、二人と下りてきて、石の前に集まる。"},{w:null,t:"アレク、踏み場のわきの、苔だらけの別の古い石の前にしゃがむ。"},{w:"alek",t:"……『この下に、我が金塊、眠れたし』。",v:"08_0176"},{w:"hero",f:"serious",t:"……お前、読めねえだろ。",v:"08_0177"},{w:"elly",t:"……しゃがんで、じっと。さっきの子みたいに。",v:"08_0180"},{w:"hero",f:"smile",t:"じっと、な。……よし。",v:"08_0181"},{w:null,t:"ヤマト、石段から下りて、しゃがむ。ひざに手を置いて、じっとしている。"},{w:"elly",t:"ヤマトも踏む？　気持ちいいよ！",v:"08_0184"},{w:"hero",t:"踏まねえ。今、練習中だから。",v:"08_0185"},{w:null,t:"フォルン、日なたから立ち上がる。"},{w:null,t:"エリーの足の下で、ぶどうがぶちゅっとつぶれる。紫の汁が槽のふちから飛んで、ヤマトの顔にかかる。"},{w:"hero",t:"うわっ、つめてっ！",v:"08_0188"},{w:null,t:"ヤマト、跳び上がる。"},{w:"elly",t:"ごめーん！",v:"08_0190"},{w:null,t:"アレク、カゴを置いて、ヤマトのとなりに座る。房を一つ、ヤマトの口の前に出す。"},{w:"alek",t:"食うか？",v:"08_0193"},{w:null,t:"ヤマト、目をつむったまま、首を横にふる。"},{w:null,t:"アレク、ヤマトの口の前で、一粒ずつ自分で食べていく。"},{w:null,t:"フォルンが、日なたから歩いてくる。"},{w:"hero",t:"（目をつむったまま）……アレク、それ、わざとだろ。",v:"08_0197"},{w:"alek",t:"何がや。",v:"08_0198"},{w:null,t:"ヤマト、目をあけて、アレクの口に房ごと押しこむ。"},{w:"alek",t:"（口いっぱいで）……何すんねん。",v:"08_0200"},{w:null,t:"フォルン、ヤマトの足をまたいで、そのまま小屋のかげへ行ってしまう。"},{w:"elly",f:"serious",t:"……今の、すっごく惜しかったよ。",v:"08_0202"},{w:"hero",f:"serious",t:"……知ってる。",v:"08_0203"}];
GR_SC.g08_06=[{w:null,t:"森のふち。ベルクマが、木の根もとで止まって、ふり返る。口のまわりの紫を、前足でこすっている。"},{w:null,t:"エリー、棚のあいだを上がっていく。"},{w:"hero",t:"おい、エリー！",v:"08_0279"},{w:"elly",t:"だいじょうぶ。もう、おなかいっぱいの顔してるもん。",v:"08_0280"},{w:null,t:"エリー、低い声で、うなるまねをする。"},{w:null,t:"ベルクマ、首をかしげる。"},{w:"elly",t:"来年は、半分こね！",v:"08_0283"},{w:null,t:"ベルクマ、のそのそ向きを変えて、森の中へ消える。"},{w:null,t:"エリーの肩に、ピーグルが跳び下りてくる。"},{w:null,t:"小屋の前。フォルン、日なたのあとの温かい石の上で、丸くなっている。"}];
GR_SC.g08_07=[{w:null,t:"夜。小屋の前の石段。"},{w:null,t:"エリー、石段のいちばん上で、手首の画面にふれる。空中に、アナの声の波の形だけが出る（声だけの電話・顔は映さない）。"},{w:"elly",t:"お姉ちゃん、今年も来たよ。ぶどう小屋！",v:"08_0291"},{w:"alek",t:"（槽のふちから、小声で）……おれのことも、言うといて。",v:"08_0292"},{w:null,t:"エリーは聞いていない。画面に向かって、手をふっている。"},{w:"ana",t:"旅の途中で寄ったの？　クマの子、今年も来た？",v:"08_0294"},{w:"elly",t:"来た！　ぶどう、半分こしようねって言った。",v:"08_0295"},{w:"ana",t:"去年、戸をこわした子と？",v:"08_0296"},{w:"elly",t:"うん。今年は、ちゃんと話せたよ。",v:"08_0297"},{w:"ana",t:"……また、そんなことして。",v:"08_0298"},{w:null,t:"エリー、笑って、画面を切る。"},{w:null,t:"石段の下の段に、ヤマト。顔の紫のしみが、まだうすく残っている。"},{w:null,t:"棚の上で、ピーグルが羽を広げる。"},{w:"hero",t:"エリー、あんな昔の字、どこで覚えたんだ。",v:"08_0302"},{w:"elly",t:"おばあちゃんの村の言葉が、昔の字とほとんど同じなの。",v:"08_0303"},{w:"alek",t:"読めて、どうするんや。",v:"08_0304"},{w:"elly",t:"世界には、入っちゃいけない古代の遺跡がたくさんあるの。",v:"08_0305"},{w:"elly",t:"それを見て回って、本当の古代の歴史を知りたいんだあ。",v:"08_0306"},{w:"alek",t:"入ったらあかんのやろ。",v:"08_0307"},{w:"elly",t:"だから、見たいんだよ！",v:"08_0308"},{w:"hero",t:"遺跡って、石しかねえじゃん。",v:"08_0309"},{w:null,t:"エリーの髪の中から、ピリポンが顔だけ出す。"},{w:null,t:"ぱちっ。小さな電気が、石段の下のヤマトの頭へ飛ぶ。"},{w:null,t:"ヤマトの髪が、ぶわっとふくらむ。だまる。"},{w:null,t:"槽のふちのアレク、望遠鏡を下ろして、ふくらんだ頭を見る。"},{w:null,t:"エリーは、棚の上のピーグルを見上げている。"},{w:null,t:"ピーグル、棚の上から、ふわっと夜の空へ飛び立つ。"},{w:null,t:"エリー、立ち上がって、両手を大きくふる。"},{w:"elly",t:"またねー！",v:"08_0317"},{w:null,t:"アレク、望遠鏡を、また空に向ける。"},{w:"hero",t:"アレクは？　旅して、どうすんだ。",v:"08_0319"},{w:"alek",t:"金ためて、ロケットであれに行くねん。",v:"08_0320"},{w:null,t:"アレクの望遠鏡の先。"},{w:"hero",t:"火星!?　一人で？",v:"08_0322"},{w:"alek",t:"一人ちゃう。",v:"08_0323"},{w:null,t:"アレク、足の先で、寝ているクロッコをちょんとつつく。"},{w:null,t:"クロッコ、寝たまま、しっぽを一回ふる。"},{w:null,t:"ヤマト、石段にあおむけにねころがる。"},{w:null,t:"フォルン、ヤマトのひざに前足をかける。"},{w:null,t:"ヤマトの体が、固まる。"}];
GR_SC.g08_08=[{w:null,t:"明かりを落とした広い部屋。"},{w:null,t:"窓のそばに、すその長い黒いコートの女。"},{w:null,t:"【字幕】「カシア」。"},{w:null,t:"画面に、空から撮った写真。"},{w:null,t:"カシア、写真を指で広げる。"},{w:null,t:"カシアの指が、そこで止まる。"},{w:null,t:"カシア、画面を閉じる。窓に、カシアの顔だけがうっすら映る。"}];
GR_BT[8]={mid:[[{w:"elly",t:"あっ、またあの子だ。",v:"08_0212"},{w:"alek",t:"また？",v:"08_0213"},{w:"elly",t:"毎年、残りのぶどうを食べに来るの。",v:"08_0214"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:null,t:"ヤマト、もう石段から立っている。"},{w:"hero",t:"フォルン、追っぱらうぞ！",v:"08_0219"},{w:null,t:"ヤマト、左の手首の画面を、フォルンへかざす。"},{w:"hero",t:"フォルン、進化！",v:"08_0223"}],[{w:"hero",t:"フォルコン、火、ふけ！",v:"08_0227"},{w:"alek",t:"待て待て待て！",v:"08_0229"},{w:"hero",t:"フォルコン、待て！",v:"08_0231"},{w:null,t:"エリー、ヤマトの袖をつかむ。首を、横に一回。"},{w:null,t:"エリーの目が、戸の上の古い石へ。"},{w:null,t:"ヤマト、石を見る。"},{w:null,t:"ヤマトの人さし指が、石の彫り物から、カゴへ、一本の線を引く。"},{w:null,t:"ヤマト、カゴのぶどうを両手ですくって、半分を、からのカゴにうつす。"},{w:"elly",t:"こっちは、わたしたちの分。",v:"08_0257"},{w:"alek",t:"……ほんまに、メモどおりやん。",v:"08_0261"}],[{w:"elly",t:"（小声で）来たね。",v:"08_0267"},{w:"hero",t:"（フォルンを見たまま）……しゃべんな。",v:"08_0268"},{w:"alek",t:"（房をヤマトの口の前に出して）食うか？",v:"08_0269"},{w:"hero",f:"angry",t:"……うっせ。",v:"08_0270"},{w:"elly",t:"（小声で）……アレクも、しゃべんないで。",v:"08_0271"}]],post:[{w:null,t:"アレク、口を閉じる。"},{w:null,t:"棚から、ぶどうが一粒落ちる。"},{w:null,t:"フォルン、立ち上がる。"}]};
GR_EP[8]={"t": "エリーのぶどう小屋", "sc": [["g08_01", "海ぞいの道（8日目の朝）", 0], ["g08_02", "坂の下の村（昼前）", 0], ["g08_03", "ぶどう小屋（昼すぎ）", 0], ["g08_04", "ぶどう棚と踏み場（昼すぎ〜夕方）", 0], ["g08_05", "ぶどう棚（夕方）　勝負", 1], ["g08_06", "森のふち（夕方）", 0], ["g08_07", "ぶどう小屋の前（夜）", 0], ["g08_08", "白い都・高い窓の部屋（同じ夜）", 0]]};
GR_SC.g09_01=[{w:null,t:"ぶどう小屋を出て、二日目の朝。港町ナフリアに着いた。",v:"09_0027"},{w:null,t:"朝の港。白い家が坂にびっしり並んでいる。"},{w:null,t:"海から、箱を下げたドローンが何機も飛んでくる。"},{w:null,t:"港の入口の、旅の人用の着がえのボックス。"},{w:null,t:"ボックスの前に、ヤマトとアレク。"},{w:null,t:"フォルンは、8話の五歩より、ずっと近い。"},{w:null,t:"アレク、手首の時計を見て、ボックスの字を見上げる。"},{w:null,t:"ヤマトとアレク、顔を見合わせる。"},{w:null,t:"ボックスの戸が、しゅっと開く。"},{w:null,t:"エリー、青に白い水玉のロングワンピース。"},{w:null,t:"髪はおろして、ゆるいウェーブ。"},{w:"elly",t:"ちょっと！　なんで先に歩いてっちゃうの！",v:"09_0038"},{w:"hero",t:"中で寝てんのかと思った。",v:"09_0039"},{w:null,t:"エリー、ヤマトの肩につかまって、サンダルをはく。"},{w:"elly",t:"連絡船の乗り場って、どっち？",v:"09_0041"},{w:"hero",t:"まかせとけ！　こっちだ！",v:"09_0042"},{w:null,t:"ヤマト、胸を張って先頭を歩く。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"お前、全然違うやんけ！",v:"09_0048"},{w:"alek",t:"無人の船は、登録見るで。……一応、試すか。",v:"09_0051"},{w:"hero",f:"serious",t:"……ここまで歩いてきたのに？",v:"09_0057"},{w:"elly",t:"じゃあ、どうやって白い都まで行くの？",v:"09_0058"},{w:"alek",t:"港には、名前を聞かへん船もおるで。",v:"09_0059"},{w:"hero",t:"アレク、前見て歩けよ。",v:"09_0062"},{w:"alek",t:"客を乗せる船を探してるんやから、話しかけんなや——",v:"09_0063"},{w:null,t:"第9話　海を渡る",v:"09_0070"}];
GR_SC.g09_02=[{w:null,t:"アレクの望遠鏡が、桟橋の板の上に転がっている。"},{w:null,t:"ヤマト、桟橋にはらばいで、手をのばす。"},{w:null,t:"クロッコ、桟橋から海へ跳びこむ。アレクのパーカーのえりに、口を大きく開けて、くわえに行く。"},{w:null,t:"もう一回。つるっ。"},{w:"elly",t:"クロッコ、がんばって！　もうちょっとだよ！",v:"09_0080"},{w:null,t:"そこへ、小さな舟がすうっと寄ってくる。"},{w:null,t:"【字幕】「マリナ」。"},{w:null,t:"マリナ、鉤をのばして、アレクのパーカーのフードに引っかける。"},{w:null,t:"アレク、舟の底にあおむけ。"},{w:null,t:"クロッコも、舟のへりにあごをかけて、よじ登ってくる。"},{w:null,t:"桟橋の上で、ヤマトがはらばいのまま、腹をかかえて笑っている。"},{w:null,t:"ヤマトの足もとのフォルンが、跳び上がって、しっぽでヤマトの顔をぱしっとたたく。"},{w:null,t:"ヤマト、桟橋のへりから身を乗り出す。目は、舟のうしろの青黒い背中。"},{w:"marina",t:"よそ見して歩くやつが、毎朝一人は落ちるんだよ。",v:"09_0089"},{w:null,t:"アレク、舟の底で起き上がる。"},{w:"alek",t:"……どうも。助かりました。",v:"09_0091"},{w:null,t:"アレク、ぬれた前髪を指でととのえる。"},{w:"alek",t:"（一段低い声で）……実は僕、クルーザー持ってまして。",v:"09_0093"},{w:"alek",t:"（一段低い声で）……今度、クルージングしません？",v:"09_0094"},{w:null,t:"マリナ、もう舟のロープを巻いている。"},{w:null,t:"アレク、背すじをのばしたまま、しずくをたらして待つ。クロッコは知らん顔。"},{w:"alek",t:"引き上げてもろたの、タダっすよね。",v:"09_0097"},{w:"marina",t:"タダは、今朝だけだよ。",v:"09_0098"},{w:null,t:"クロッコ、すわったアレクの胸に、ずぶぬれのままよじ登る。"},{w:"alek",t:"かむ力もないくせに、跳びこむなや。",v:"09_0100"},{w:null,t:"アレク、クロッコの頭に、ぬれた手をのせる。"},{w:null,t:"マリナ、舟を桟橋につける。"},{w:null,t:"エリー、拾った望遠鏡を、アレクの胸に置く。"},{w:"elly",t:"お姉さん、白い都まで船、出してる？",v:"09_0104"},{w:"marina",t:"出してるよ。沖の細長いのが、うちの客船。",v:"09_0105"},{w:"alek",t:"三人と、三体。……なんぼですか。",v:"09_0106"},{w:null,t:"マリナ、手首の画面に数字を出して見せる。"},{w:"alek",t:"……足りへんっす。",v:"09_0109"},{w:"hero",t:"じゃあさ、あと払いにしてくれよ！",v:"09_0111"},{w:"hero",t:"白い都の大会の賞金が入ったら、ちゃんと払うから。",v:"09_0112"},{w:"marina",t:"大会に出るの？　その狐で？",v:"09_0113"},{w:"hero",f:"serious",t:"……出るよ。勝つし。",v:"09_0116"},{w:"marina",t:"賞金なんて、勝ってみないと分かんないでしょ。",v:"09_0117"},{w:"alek",t:"負けたら、船の荷物運び三日でどうっすか。",v:"09_0118"},{w:"marina",t:"……夕方出る。乗りな。",v:"09_0120"},{w:"elly",f:"smile",t:"ほんとに!?　やった！",v:"09_0121"},{w:"hero",t:"船長、ありがと！",v:"09_0123"}];
GR_SC.g09_03=[{w:null,t:"その夕方。三人は、マリナの客船に乗った。",v:"09_0127"},{w:null,t:"夕方の港。マリナの客船。"},{w:null,t:"客は少ない。"},{w:null,t:"マリナ、操縦の台で手首の画面にふれる。"},{w:null,t:"アレク、船室の壁ぎわで、まだしめったパーカーを干している。"},{w:null,t:"アレクのひざの上に、クロッコ。"},{w:"hero",t:"（にやにや）へり、すべるぞ。気をつけろよ。",v:"09_0133"},{w:"alek",t:"……うっさいわ。",v:"09_0134"},{w:null,t:"日がしずんだ海。"},{w:null,t:"エリー、男の子の横にしゃがんでいる。"},{w:"elly",t:"ねえ、この子かわいくない？　きみが育ててるの？",v:"09_0137"},{w:"x",n:"男の子",t:"うん。ぼくが卵からかえしたんだよ。",v:"09_0138"},{w:"x",n:"おじいさん",t:"白い都に着いたら、すぐ登録しような。",v:"09_0139"},{w:"elly",t:"それまで、しっかり抱っこしとこうね。",v:"09_0140"},{w:null,t:"エリー、船べりで、自分の手首の画面にふれる。空中に、アナの声の波の形だけが出る（声だけの電話・顔は映さない）。"},{w:"elly",t:"お姉ちゃん！　今、船の上だよ！",v:"09_0142"},{w:"ana",t:"エリー、ちゃんと食べた？",v:"09_0143"},{w:"elly",t:"食べたよ！　さっき、あったかいパンもらったの。",v:"09_0144"},{w:"ana",t:"よかった。夜は冷えるから、気をつけてね。",v:"09_0145"},{w:null,t:"壁ぎわのアレク、アナの声に、背すじだけ、ぴんとのびる。"},{w:null,t:"エリー、笑って手をふって、画面を切る。"},{w:null,t:"エリー、ポケットから、はちみつのあめの、すきとおった包みを出す。"},{w:null,t:"光るお菓子帳に当てる。"},{w:null,t:"甲板のはし。フォルンが、波しぶきを一つ、しっぽの先にもらう。"},{w:"hero",t:"フォルン、そこ、客の荷物の上だぞ。",v:"09_0152"},{w:"hero",f:"serious",t:"……荷物、焦がすなよ。",v:"09_0154"}];
GR_SC.g09_04=[{w:null,t:"月のない海。"},{w:null,t:"甲板に、テリオンが二体。"},{w:null,t:"【プロフィール】アロガルド／森／●●○／とげの葉をまとう緑の獣"},{w:null,t:"黒い船の甲板のすみ。"},{w:null,t:"アロガルドとソヨモモは、そちらを一度も見ない。"},{w:null,t:"そのうしろに、大柄な男。"},{w:null,t:"【字幕】「ゼノ」。"},{w:null,t:"ゼノの足もとで、水の子が一体、大きなあくびをする。"},{w:null,t:"【プロフィール】ラッコン／水／●●○／水のマフラーのラッコ"},{w:null,t:"ゼノの手首の画面。"},{w:"zeno",t:"明かりをつけて、あの船に寄せろ。",v:"09_0167"},{w:null,t:"マリナの客船。"},{w:null,t:"右舷のすぐ横に、黒い船体が、明かりをつけて並ぶ。"},{w:null,t:"マリナ、操縦の台で顔を上げる。"},{w:"marina",t:"……ゼノの船だ。首の光ってない子を、取りに来たんだ。",v:"09_0171"},{w:"alek",t:"（小声で）……目ぇ合わすな。",v:"09_0173"},{w:"hero",t:"知ってんのか、あのでかいの。",v:"09_0174"},{w:"alek",t:"前の仕事で、荷物渡した相手や。",v:"09_0175"},{w:"marina",t:"みんな、船室に入って！　戸から顔を出さないで！",v:"09_0180"},{w:"hero",t:"フォルンが中にいたら、客までやられる。",v:"09_0184"},{w:"zeno",t:"狐は、もらっていく。",v:"09_0191"},{w:"hero",t:"フォルンは渡さねえぞ！",v:"09_0193"},{w:"elly",t:"船室の子たちにも、さわらせないからね！",v:"09_0196"},{w:"zeno",t:"坊主。その狐は、だれの相棒でもない。",v:"09_0197"},{w:"hero",t:"おれの相棒だ！",v:"09_0198"},{w:"x",n:"二人",t:"進化！",v:"09_0205"}];
GR_SC.g09_06=[{w:null,t:"三体の光が引き、もとの姿へ。"},{w:null,t:"小さなクロッコが、甲板をよちよち歩いて、座りこんだアレクのひざに頭をのせる。"},{w:null,t:"アレク、あごの下を指でなでながら、へへっと笑う。"},{w:"hero",f:"smile",t:"……すっげー。クロベク、かっけえ。",v:"09_0292"},{w:"alek",t:"当たり前や。こいつ、やればできんねん。",v:"09_0293"},{w:"alek",t:"船代、これで上がらへんやろな。",v:"09_0294"},{w:"marina",t:"（戸の前で）荷物運びの三日は、なしにしとく。",v:"09_0295"},{w:"alek",t:"……船代は？",v:"09_0296"},{w:"marina",t:"それは別。",v:"09_0297"},{w:null,t:"アレク、だまって、クロベクが伏せていた板をあごでさす。"},{w:"hero",f:"serious",t:"……伏せてたら、あいつら、見なかったな。",v:"09_0299"},{w:null,t:"甲板のフォルン、耳だけこっちへ向けて、しっぽで甲板を一回ぱたり。"},{w:"hero",f:"serious",t:"……お前、ヒゲのおっさんに顔、見られたぞ。",v:"09_0301"},{w:"alek",t:"見せたったんや。",v:"09_0302"},{w:null,t:"アレク、ぬれた前髪を、指でととのえる。"},{w:null,t:"ヤマト、立ち上がって、フォルンの方へ行く。"},{w:null,t:"フォルンは甲板に座りこんだまま、前足をなめる。"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。"},{w:null,t:"ヤマト、となりに座る。"},{w:null,t:"木箱の山のかげから、鳥の子がよちよち出てくる。"},{w:null,t:"エリー、男の子のうしろにしゃがんで、肩を抱く。男の子の手が、エリーの左のそでをつかむ。"},{w:"x",n:"男の子",t:"お姉ちゃん、ひじ……。",v:"09_0310"},{w:"elly",t:"へーき、へーき。",v:"09_0311"},{w:null,t:"エリー、男の子の頭をなでる。"},{w:"elly",f:"serious",t:"……ありがと。",v:"09_0314"},{w:"hero",t:"痛いなら、言えよ。",v:"09_0315"}];
GR_SC.g09_07=[{w:null,t:"夜明け。小雨はやんでいる。"},{w:null,t:"近づくと、港の岸壁に、大きな大会の旗が何本もはためいている。"},{w:null,t:"客たちは船室の入口で眠っている。"},{w:null,t:"エリーも、男の子のとなりで、ひざを抱えて眠っている。"},{w:null,t:"アレクは、壁ぎわで、クロッコをひざにのせたまま眠っている。"},{w:null,t:"船べりに、ヤマト。"},{w:null,t:"ヤマト、旗を見て、にっと笑う。"},{w:null,t:"首に灰色のタオル。"},{w:null,t:"男、手首の画面にふれる。"},{w:null,t:"ゼノの指が、送り先の「本部」を押す。"}];
GR_BT[9]={mid:[[{w:null,t:"ゼノ、手首の画面に一度ふれるだけ。"},{w:"x",n:"男の子",t:"待って！",v:"09_0216"},{w:null,t:"エリー、戸口の前で男の子に飛びつき、抱えて戸口の中へ倒れこむ。"},{w:null,t:"エリー、すぐに笑って、そでを下ろしてひじを隠す。"},{w:"hero",t:"フォルコン、あの緑のでかいのに一発だけ！",v:"09_0221"},{w:"zeno",t:"ラッコン。まとめて返せ。",v:"09_0223"},{w:"hero",t:"フォルコン！",v:"09_0225"},{w:"elly",t:"（戸口から）ピリムサ！　そこから動かないで！",v:"09_0227"},{w:"alek",t:"クロッコ、水を吐け！",v:"09_0230"},{w:null,t:"アレク、壁から、船室の戸の明かりの下へ一歩出る。"},{w:null,t:"ゼノ、画面の指を止めて、明かりの下のアレクの顔を見る。"}],[{w:"alek",t:"クロッコ、上がってこい！",v:"09_0238"},{w:null,t:"アレク、左の手首の画面を、クロッコへかざす。"},{w:"alek",t:"クロッコ、進化！",v:"09_0243"},{w:"alek",t:"クロベク、それや！　かまんでええ、突け！",v:"09_0251"},{w:null,t:"ゼノ、手首の画面を見たまま、指を一本だけ動かす。"},{w:"zeno",t:"ラッコン、突き返せ。",v:"09_0253"},{w:null,t:"ヤマトの目が、アロガルドの目を追う。"},{w:null,t:"ヤマト、右手を上げる。"},{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"09_0263"},{w:null,t:"アレク、倒れたアロガルドと、知らん顔のソヨモモを見る。"},{w:"alek",t:"クロベク、伏せえ！",v:"09_0269"}]],post:[{w:null,t:"アロガルドのチップが、ぱきんと割れる。"},{w:null,t:"黒い船とは反対の海へ飛びこみ、白い都の方へ泳いで逃げていく。"},{w:null,t:"ゼノの手首の画面が光る。"},{w:"zeno",t:"……引き上げる。",v:"09_0281"}]};
GR_EP[9]={"t": "海を渡る", "sc": [["g09_01", "港町ナフリア（10日目の朝）", 0], ["g09_02", "桟橋とマリナの舟（朝）", 0], ["g09_03", "マリナの客船・甲板（10日目の夕方〜夜のはじめ）", 0], ["g09_04", "夜の海・黒い船（夜ふけ）", 0], ["g09_05", "甲板の勝負", 1], ["g09_06", "勝負のあと（夜ふけ）", 0], ["g09_07", "夜明けの海", 0]]};
GR_SC.g10_01=[{w:null,t:"夜の海をこえて、マリナの船は白い都の港に着いた。",v:"10_0026"},{w:null,t:"朝の港。白い石の古い倉庫が並ぶ岸壁。"},{w:null,t:"港のうしろの丘。"},{w:null,t:"マリナの船が岸壁につく。"},{w:null,t:"渡し板を下りる三人と三体。"},{w:null,t:"エリーのひじに、ヤマトのばんそうこう。"},{w:null,t:"エリー、水色と白のジャージの上着。"},{w:null,t:"長いズボンに白いスニーカー。"},{w:null,t:"アレク、肩のヤマトの上着を、見もせずにヤマトの頭へ放る。"},{w:null,t:"ヤマト、上着を頭にのせたまま、岸壁を歩きだす。"},{w:"marina",t:"大会、がんばんなよ。",v:"10_0036"},{w:"marina",t:"ゆうべのあれなら、いいとこまで行けるよ。",v:"10_0037"},{w:"hero",t:"いいとこじゃなくて、優勝するんだって。",v:"10_0038"},{w:"marina",t:"そう言う子から、先に負けて帰ってくるんだよ。",v:"10_0039"},{w:"marina",t:"船代、忘れんじゃないよ。",v:"10_0040"},{w:"alek",t:"……賞金から、払いますわ。",v:"10_0041"},{w:null,t:"マリナは、もう船にもどっている。"},{w:null,t:"ヤマト、港の沖を見る。"},{w:"hero",t:"あのヒゲのおっさん、また来ねえだろうな。",v:"10_0044"},{w:null,t:"エリーの髪の中で、ピリポンが小さくなっている。顔を出さない。"},{w:"elly",t:"もう来なくていいよ。ピリポン、まだ髪から出てこないもん。",v:"10_0047"},{w:"hero",f:"serious",t:"……来たら、ぶっ倒す。",v:"10_0048"},{w:"alek",t:"受付、朝のうちに閉まるで。しゃべってんと行くで。",v:"10_0050"},{w:null,t:"第10話　白い都の大会",v:"10_0052"}];
GR_SC.g10_02=[{w:null,t:"白い都。昔の石の町に、きょうは大会の屋台が並んでいる。",v:"10_0058"},{w:null,t:"白い石畳の坂道。"},{w:null,t:"串焼きの屋台では、ロボットの腕が肉を返している。"},{w:null,t:"世界じゅうから来た人とテリオン。"},{w:null,t:"エリー、歩きながら手首の画面を見る。"},{w:"elly",t:"今日のラッキースポット、また古い字のある所だって！",v:"10_0063"},{w:null,t:"ヤマトは串焼きの屋台を、アレクは値札を見ている。"},{w:null,t:"エリー、手首の画面を、ぱちんと閉じる。"},{w:null,t:"串を見たままのヤマトの目だけが、一回、エリーの閉じた画面へ動く。"},{w:null,t:"エリー、ふと横を向く。石壁のかすれた字が、目のはしに引っかかる。"},{w:null,t:"エリー、小さな屋台の前で止まる。"},{w:null,t:"エリー、手首の画面をちらっと開く。"},{w:null,t:"エリー、壁の古い字を指でなぞる。"},{w:null,t:"その手の下の台に「大会限定」の札。"},{w:"elly",t:"アレク、これ大会の時しか売ってないんだって！",v:"10_0072"},{w:"alek",t:"……で、なんぼや。",v:"10_0073"},{w:"alek",t:"人形は、勝ってからや。",v:"10_0075"},{w:"elly",f:"surprised",t:"ほんと！？　約束だよ。",v:"10_0076"},{w:"hero",f:"serious",t:"……お前のおごり？",v:"10_0083"},{w:"alek",t:"……三本目は、ただやからな。",v:"10_0084"},{w:"hero",t:"で、ただのは、どれ？",v:"10_0085"},{w:"alek",t:"（エリーの串をあごでさして）……それや。",v:"10_0086"},{w:"hero",t:"じゃ、おれのはおごりだな。サンキュ、アレク。",v:"10_0087"},{w:"alek",t:"……おごりちゃう。貸しや。",v:"10_0088"}];
GR_SC.g10_03=[{w:null,t:"坂の上がひらける。"},{w:null,t:"入口に、案内のロボットと、宙に浮かぶ受付の画面。"},{w:null,t:"入口のとなりに、白い石の小さな建物。"},{w:"x",n:"受付のロボット",t:"白い都テリオン大会へ、ようこそ。三体までの部ですね。",v:"10_0095"},{w:"x",n:"受付のロボット",t:"組の名前を、どうぞ。",v:"10_0096"},{w:"hero",t:"チーム・フォルンで！",v:"10_0097"},{w:"elly",t:"えー、ピリポンとクロッコも入れてよ。",v:"10_0098"},{w:null,t:"二人がもめているあいだに、アレクが受付の画面に指で打ちこんでいる。"},{w:"x",n:"受付のロボット",t:"「オリーヴァ村」で、受け付けました。",v:"10_0100"},{w:"elly",t:"（にこっ）オリーヴァ村、いいね！",v:"10_0101"},{w:"hero",f:"serious",t:"……勝手に決めんなよ。",v:"10_0102"},{w:"alek",t:"もめてたら、日ぃ暮れるで。",v:"10_0103"},{w:null,t:"アレク、カードを当てる。"},{w:null,t:"エリー、受け取った番号のバッジを、ジャージの上着に付ける。"},{w:null,t:"受付のロボットが、こちらの三体の首元に、順に光をかざす。"},{w:null,t:"フォルン、うしろ足で首をかく。"},{w:null,t:"ヤマト、画面の赤い字を見る。入口のとなりの白い窓口を、一回だけ見る。"},{w:"x",n:"受付のロボット",t:"開会式のあと、すぐに1回戦です。選手の入口へどうぞ。",v:"10_0109"}];
GR_SC.g10_04=[{w:null,t:"【ここから一つながりのカメラ】"},{w:null,t:"満員の客席。"},{w:null,t:"選手の入口に、三人と三体。"},{w:"x",n:"実況（場内の声）",t:"大会を支える、協賛の会社より、ごあいさつです。",v:"10_0116"},{w:null,t:"大きな画面に、協賛（きょうさん）の会社の名前と印だけが出る。顔は映らない。"},{w:null,t:"カメラ、客席の上を貴賓席へ。"},{w:"victor",t:"みなさん、白い都へ、ようこそ。",v:"10_0119"},{w:"victor",t:"世界じゅうから、強い子が来てくれました。",v:"10_0120"},{w:null,t:"拍手。カメラ、客席を横に流れて、選手の入口のアレクへ。"},{w:null,t:"クロッコの頭をなでていたアレクの手が、止まる。"},{w:"victor",t:"どの子にも、いい試合を期待しています。",v:"10_0123"},{w:null,t:"アレクの目だけが、声の出どころの貴賓席へ上がる。"},{w:null,t:"アレク、パーカーのポケットから古い望遠鏡を出して、貴賓席に向ける。"},{w:"hero",t:"エリー、あそこ。船のヒゲのおっさんがいるぞ。",v:"10_0133"},{w:"elly",f:"surprised",t:"えっ、どこ？",v:"10_0134"},{w:"x",n:"実況（場内の声）",t:"開会式は、ここまで！　まもなく1回戦です！",v:"10_0135"},{w:"hero",t:"なんであいつが、偉い席にいんだよ！",v:"10_0137"},{w:"alek",t:"知らん。休み場、こっちや。",v:"10_0138"}];
GR_SC.g10_05=[{w:null,t:"競技場の裏。"},{w:null,t:"エリーが、休み場の台から、選手に配る軽食の包みを三つもらってくる。"},{w:null,t:"ヤマトの方へ、砂の上を歩いてくる。"},{w:null,t:"ヤマトのうしろ、裏の門が開く。丸い目のライトの、古い黒いスポーツカーが一台。"},{w:null,t:"エンジンの音が、低く鳴る。"},{w:null,t:"エリーの足が止まる。笑顔は、そのまま。"},{w:null,t:"ヤマト、エリーの顔を見る。"},{w:null,t:"黒い車が、貴賓席の下の車寄せに止まる。"},{w:null,t:"運転席から、スーツの男が自分で降りる。"},{w:null,t:"助手席から、大柄な男。"},{w:null,t:"エリー、また、ふつうに歩いてくる。"},{w:"hero",f:"serious",t:"……エリー、今——",v:"10_0154"},{w:"elly",t:"はい、ヤマトの分！",v:"10_0155"},{w:null,t:"ヤマト、包みを受け取る。エリーの顔を見る。"},{w:null,t:"エリー、アレクの長いすに包みを置いて、飲み物を取りに台へ戻っていく。"},{w:null,t:"ヤマト、車寄せの方をもう一度見て、アレクに小さな声で。"},{w:"hero",t:"今の車見て、エリー、止まってた。ヒゲも乗ってたし。",v:"10_0159"},{w:"alek",t:"……ヒゲなんか、どこにでもおるやろ。",v:"10_0160"},{w:null,t:"アレクは、クロッコに水をかける手もとから、目を上げない。"},{w:"x",n:"実況（場内の声）",t:"1回戦が始まります。オリーヴァ村の三人は、試合場へどうぞ。",v:"10_0162"}];
GR_SC.g10_07=[{w:null,t:"選手の通路。"},{w:null,t:"タリク、パオッコを両腕で抱き上げる。"},{w:null,t:"ヤマト、立ち止まる。"},{w:null,t:"登録の光の点は、ない。フォルン、首をぷるっとふって、指からはなれる。"},{w:null,t:"通路の出口。"},{w:"x",n:"子ども",t:"狐のお兄ちゃん、サインちょうだい！",v:"10_0298"},{w:"hero",t:"え、おれ？　……しょうがねえなあ。並べ並べ。",v:"10_0299"},{w:null,t:"ヤマト、子どもの画面に、指で大きくサインを書く。"},{w:"hero",t:"次も勝つから、ちゃんと見とけよ。",v:"10_0301"},{w:"x",n:"子ども",t:"狐にも、サインしてもらって！",v:"10_0302"},{w:null,t:"子どもが、画面をフォルンの鼻先に向ける。"},{w:"hero",t:"こいつ、そういうのやらねえんだよ。……足だけ貸してやるか。",v:"10_0304"},{w:null,t:"ヤマト、子どもの画面を、フォルンの前足の前に差し出す。"},{w:null,t:"フォルン、前足で、画面をぺしっとはらう。"},{w:null,t:"フォルン、そのままヤマトの顔に跳びつき、すすけた前足で、ほっぺを、ぎゅっとふんで、床へ跳び下りる。"},{w:"elly",t:"ヤマト、こっち向いて。……はい、撮れた。",v:"10_0311"},{w:"x",n:"ブラジルの二人",t:"融合！",v:"10_0315"},{w:"x",n:"実況（場内の声）",t:"二体が一つに！　ブラジルの組、融合です！",v:"10_0318"},{w:"hero",f:"serious",t:"……なんだ、あれ……！",v:"10_0324"},{w:"alek",t:"……おれも、初めて見たわ。",v:"10_0325"}];
GR_SC.g10_08=[{w:null,t:"競技場の下の、古い石の壁の控え室。"},{w:null,t:"三体は小さな姿にもどっている。"},{w:null,t:"しっぽの先に、茶色い象の毛が一本からまっている。"},{w:null,t:"とどく前に、フォルン、しっぽをくるっと体の下にしまう。"},{w:"hero",t:"次、中国だって。あと二つで優勝だぜ！",v:"10_0334"},{w:"alek",t:"……あと二つ勝ったら、人形代か。",v:"10_0335"},{w:null,t:"アレク、クロッコの背中を布でふく。"},{w:null,t:"エリー、左のそでの下のばんそうこうを、指でそっと押さえる。"},{w:null,t:"ヤマト、横目でそれを見て、画面の対戦表に目をもどす。"},{w:null,t:"控え室の戸口に、チャコールのストライプのスーツの男が立っている。"},{w:null,t:"男の目が、長いすのはしのフォルンに止まる。"},{w:null,t:"フォルン、顔を上げる。"},{w:null,t:"ヤマトとエリーが、顔を上げて戸口を見る。"},{w:null,t:"男、空中の対戦表の「オリーヴァ村」の字を、指で一回なぞる。笑顔のまま。"},{w:null,t:"男、胸に手を当てて、軽く一礼する。"},{w:null,t:"エリー、白いカバンのひもを、指に巻きつける。"},{w:"hero",t:"アレク、今のスーツのおっさん、だれ？",v:"10_0346"},{w:null,t:"アレクだけが、顔を上げない。"}];
GR_BT[10]={mid:[[{w:null,t:"タリクの目が、フォルンの首元に止まる。"},{w:"tarik",t:"その狐も、登録なしか。",v:"10_0180"},{w:"hero",t:"そっちもだろ。",v:"10_0181"},{w:"tarik",t:"ああ。優勝すれば、登録できる。",v:"10_0182"},{w:"hero",f:"serious",t:"……こっちもだ。優勝は、ゆずらねえ。",v:"10_0183"},{w:"x",n:"審判",t:"始め！",v:"10_0184"},{w:null,t:"タリク、手首の画面をかざす。"}],[{w:"tarik",t:"進化！",v:"10_0187"},{w:null,t:"三人が、手首の画面をかざす。"},{w:"x",n:"三人",t:"進化！",v:"10_0194"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"クロベク、水や。",v:"10_0203"},{w:null,t:"ヤマトの目が、砂の線をたどって、壁で止まる。"},{w:"hero",t:"フォルコン、壁の前で見張れ！",v:"10_0215"},{w:null,t:"ヤマトの目は、床じゅうの石のすき間を、順に追っている。"},{w:"hero",t:"フォルコン！",v:"10_0233"},{w:null,t:"ヤマト、くちびるをかむ。"}],[{w:"elly",t:"ピリムサ、あの穴の前に立って。わざと見えるように。",v:"10_0248"},{w:"alek",t:"クロベク、穴の横に回れ。正面やなくて、横や。",v:"10_0249"},{w:"tarik",t:"パオドン、ふりほどけ！",v:"10_0267"},{w:"elly",t:"ピリムサ、顔に、ぱちって！",v:"10_0269"},{w:"alek",t:"クロベク、タイダルランス！",v:"10_0271"},{w:null,t:"ヤマト、ふたの石の穴を見たまま、アレクの横に並ぶ。"},{w:"hero",f:"serious",t:"……穴、一個しかなかった。",v:"10_0276"}]],post:[{w:null,t:"アルマド、倒れたパオドンの鼻先に、丸い体をくっつけて動かない。"},{w:null,t:"タリク、帽子を取って、審判に手を上げる。"},{w:null,t:"フォルコン、しっぽをはなして、床にあごをつける。"},{w:"alek",t:"（ヤマトの横で）……きれいに、だまされたな。",v:"10_0285"}]};
GR_EP[10]={"t": "白い都の大会", "sc": [["g10_01", "白い都の港（11日目の朝）", 0], ["g10_02", "屋台の町（朝）", 0], ["g10_03", "古い競技場の受付（朝）", 0], ["g10_04", "開会（一つながりのカメラ）", 0], ["g10_05", "競技場の裏の休み場（1回戦の前）", 0], ["g10_06", "1回戦", 1], ["g10_07", "選手の通路（1回戦のあと）", 0], ["g10_08", "控え室（1回戦のあと）", 0]]};
GR_SC.g11_01=[{w:null,t:"大会の二日目。三人は、アレクが見つけた一番安い宿で朝を迎えた。",v:"11_0025"},{w:null,t:"古い石の建物の上の階。"},{w:null,t:"ヤマト、寝棚の上であぐらをかいて、手首の画面を見ている。"},{w:"hero",t:"エリー、見ろよ。きのうの1回戦、ニュースになってる！",v:"11_0028"},{w:null,t:"空中の画面。"},{w:null,t:"窓のへりで、フォルンがしっぽの火でオリーブを焼いている。"},{w:null,t:"宿の台所のロボットが、いちばん安い朝ごはんの盆（パンと、はちみつのヨーグルト）を出す。"},{w:null,t:"アレクの盆にだけ、アレクが自分で買ったぶどうジュース。"},{w:"elly",t:"ニュースより、ご飯、先！",v:"11_0033"},{w:null,t:"ピリポンが、エリーのヨーグルトのふたを、はしからなめている。"},{w:null,t:"アレク、パンをかじりながら、自分の手首の画面で大会の対戦表を見ている。"},{w:"alek",t:"きょうの相手、中国の道場の子らしいで。",v:"11_0036"},{w:"hero",t:"じゃあ、おれたちが最初に倒してやろうぜ！",v:"11_0038"},{w:null,t:"ヤマト、寝棚から身を乗り出して、空中の画面をフォルンの鼻先へ向ける。"},{w:"hero",t:"見ろ、フォルン。お前、ニュースに出てるぞ！",v:"11_0040"},{w:null,t:"窓のへりのフォルン、オリーブから目を上げずに、そっぽを向く。"},{w:null,t:"しっぽの火だけが、ぼっと大きくなる。"},{w:"alek",t:"クロッコ、消してやれ。",v:"11_0043"},{w:null,t:"足もとのクロッコが、ヤマトの頭へ水をぴゅっ。"},{w:"alek",t:"（早口で）……貴様、おれのジュース飲んで、水で薄めたやろ！",v:"11_0051"},{w:"hero",t:"（口のはしが紫）……飲んでねえ。",v:"11_0052"},{w:"alek",t:"しばく！",v:"11_0053"},{w:"elly",t:"（ヨーグルトを食べながら）朝から元気ね。",v:"11_0055"},{w:null,t:"第11話　準決勝",v:"11_0057"}];
GR_SC.g11_02=[{w:null,t:"競技場の下の通路。"},{w:"elly",t:"ねえねえ、三人おそろい。オリーヴァ村の印！",v:"11_0064"},{w:null,t:"アレク、受け取って、見もせずにポケットへ入れる。"},{w:null,t:"ヤマト、画面を見たまま、手首に通す。"},{w:null,t:"エリー、拾う。"},{w:null,t:"エリー、自分とヤマトの腕輪を、ぴかっと光らせる。"},{w:null,t:"ヤマト、光った手首を顔の前に上げる。"},{w:null,t:"エリーが前を向いたすきに、アレク、ポケットの腕輪を手首にはめる。"},{w:null,t:"競技場の下の、石の壁の通路。"},{w:null,t:"すれちがいざま、カマコロがハオの肩からひょいと床に下りる。"},{w:"hero",t:"おい、フォルン！　まだ始まってないって！",v:"11_0075"},{w:"hao",t:"すみません。",v:"11_0077"},{w:"hao",t:"翻訳機、使ってないんですか。",v:"11_0085"},{w:"elly",t:"うん。聞いてたら、わかるよ。",v:"11_0086"},{w:"alek",t:"（あきれ顔で）……聞いてたら、て。",v:"11_0088"},{w:"elly",t:"フォルン、勝負の前から負けず嫌いだね。",v:"11_0092"},{w:"hero",t:"負けず嫌いなのは、向こうのかまきりの方だろ。",v:"11_0093"},{w:"alek",t:"（ぼそっと）……お前が言うな。",v:"11_0094"}];
GR_SC.g11_03=[{w:null,t:"競技場のまん中。"},{w:null,t:"ヤマトの足もとのフォルン、しっぽの火の先を、黒い石にのせる。"},{w:null,t:"フォルン、しっぽを白い石の方へよける。"},{w:null,t:"相手の陣の前。"},{w:null,t:"幅は、大きなクジラが寝そべれるほど。"},{w:null,t:"表面に、すりへった古い字が彫られている。"},{w:null,t:"選手の入口から床に出たヤマト、だまって一枚石のそばにしゃがむ。"},{w:null,t:"ヤマト、一枚石の外のへりに、手のひらをつく。"},{w:null,t:"ホエマルの潮吹きが、ぽちゃっと低く落ちる。"},{w:null,t:"エリー、一枚石の古い字の横に、彫り物を見つける。"},{w:null,t:"エリー、ヤマトの袖を引いて、そこを見せる。"},{w:null,t:"ヤマトの人さし指が、彫り物のクジラから、溝の中のホエマルへ、一本の線を引く。"},{w:null,t:"貴賓席。日よけの下で、チャコールのストライプのスーツの男が座っている。"},{w:"x",n:"実況（場内の声）",t:"選手は、陣へ戻ってください。",v:"11_0113"},{w:null,t:"ヤマト、立ち上がる。"},{w:null,t:"選手の入口で、アレク、貴賓席に背を向けて、クロッコを溝の近くへ下ろす。"},{w:"x",n:"実況（場内の声）",t:"準決勝、第一試合！　中国代表、ハオ選手の組！",v:"11_0116"},{w:"x",n:"実況（場内の声）",t:"対するは、オリーヴァ村の三人！",v:"11_0117"}];
GR_SC.g11_05=[{w:null,t:"エルレオンの光がほどけて、フォルンとピリポンの小さな姿に分かれてもどる。"},{w:null,t:"ハオ、倒れたホエマルを両手でかかえ上げて、溝の水にそっと浸けてやる。"},{w:null,t:"ヤマト、フォルンを両手で持ち上げようとする。"},{w:null,t:"手がとどく前に、フォルン、するっとよけて、ヤマトの足もとに座る。"},{w:null,t:"エリーのひざの上で、ピリポンが毛のしずくを放電で飛ばす。"},{w:"elly",t:"ヤマト、今の、すごかったね！",v:"11_0248"},{w:null,t:"エリー、ヤマトの頭をなでようと、手をのばす。"},{w:"hero",t:"（よけながら）だろ！　エリーのピリムサもな。",v:"11_0250"},{w:null,t:"うしろから、アレクが二人のあいだに顔を出す。"},{w:null,t:"ヤマト、分かれたフォルンとピリポンを、一体ずつ指でさす。"},{w:"hero",t:"（アレクに）二体いっぺん、やられなかったぞ。",v:"11_0253"},{w:"alek",t:"（画面を見たまま）……たまたまや。",v:"11_0254"},{w:"hero",t:"たまたまで、賞金の欄、見てんのかよ。",v:"11_0255"},{w:"hao",t:"竹の森に来たら、案内します。",v:"11_0259"},{w:"hero",t:"竹の森って、どこにあんの？",v:"11_0260"},{w:"hao",t:"中国の、ずっと山の方です。画面に送っておきます。",v:"11_0261"}];
GR_SC.g11_06=[{w:null,t:"通路の壁の大きな空中の画面。"},{w:null,t:"相手の三体のうち、バジリクの方を見ていた二体から色が抜けて、灰色に止まる。顔をそむけていた一体だけは、色が抜けない。"},{w:null,t:"ヤマトの目が、画面の、色の抜けなかった一体に止まる（1カット・台詞なし）。"},{w:"x",n:"実況（場内の声）",t:"決勝は、あすの午後！",v:"11_0271"},{w:"x",n:"実況（場内の声）",t:"オリーヴァ村の三人　対　前回の優勝者、レン選手！",v:"11_0272"},{w:"x",n:"実況（場内の声）",t:"レン選手は、今年も一人と一体で勝ち上がってきました！",v:"11_0273"},{w:null,t:"画面に、決勝の組み合わせ。"},{w:null,t:"通路の向こうから、レンが一人で歩いてくる。"},{w:null,t:"ヤマト、立ち止まる。"},{w:null,t:"レン、ヤマトの横を通りすぎる。"},{w:null,t:"ヤマト、ふり向く。"},{w:null,t:"ヤマトのうしろに、アレクとエリー。"},{w:"alek",t:"（ヤマトの横に並んで）……決勝、あいつか。",v:"11_0280"},{w:"hero",f:"serious",t:"……今度は、勝つ。",v:"11_0281"},{w:null,t:"通路の先。レン、歩きながら手首の画面を開く。"},{w:null,t:"送った字は「あした、決勝」。"},{w:null,t:"レン、画面を閉じる。"}];
GR_BT[11]={mid:[[{w:null,t:"ハオ、拳を手のひらに当てて礼。"},{w:"hao",t:"もう、足が前に出てますよ。",v:"11_0128"},{w:null,t:"ヤマトのつま先が、陣の線から半分はみ出している。"},{w:"x",n:"審判",t:"始め！",v:"11_0131"},{w:null,t:"ハオ、両手を横に開いてから、手首の画面をかざす。"},{w:"hao",t:"進化。",v:"11_0134"},{w:"x",n:"三人",t:"進化！",v:"11_0135"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"hero",f:"serious",t:"……フォルコン、まだだ。",v:"11_0143"}],[{w:"alek",t:"クロベク、溝に入れ！",v:"11_0144"},{w:"hao",t:"カマケン、溝のワニを。",v:"11_0150"},{w:null,t:"ヤマトの目が、見えなくなったクワガタを探す。"},{w:"hao",t:"カマケン、狐を。",v:"11_0161"},{w:null,t:"ヤマト、走ってくるカマケンを指さす。"},{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"11_0167"},{w:null,t:"ハオ、手首の画面を静かにかざす。"},{w:"hao",t:"……ホエルン、進化。",v:"11_0179"}],[{w:"alek",t:"クロベク、ふちにつかまれ！",v:"11_0183"},{w:null,t:"エリー、ふらつくピリムサを見る。自分の左の手首を、胸の前に上げる。"},{w:"elly",t:"ヤマト、いっしょにやろう。",v:"11_0189"},{w:null,t:"ヤマトの目が、エリーの手首に行く。"},{w:"alek",t:"くっつけたら、やられる時は二体いっぺんやで。",v:"11_0191"},{w:null,t:"ヤマトの目が、フォルコンへもどる。"},{w:"hero",f:"serious",t:"……フォルコン、行け！",v:"11_0193"},{w:null,t:"ヤマト、こぶしを握ったまま、フォルコンを見る。"},{w:null,t:"ヤマト、息を一つはく。"},{w:"x",n:"二人",t:"フォルコン、ピリムサ、融合！",v:"11_0203"}],[{w:"hero",t:"エルレオン！",v:"11_0209"},{w:null,t:"エリー、ヤマトを見て、一回うなずく。"},{w:null,t:"ヤマトの目が、溝のふちのホエリオスと、そのうしろの一枚石を、一回ずつ見る。"},{w:null,t:"ヤマト、ホエリオスを指さす。"},{w:"hero",t:"エルレオン、引っぱり上げろ！",v:"11_0217"},{w:null,t:"エリー、ピリムサの方の手首を、ぐっと手前に引く。"},{w:null,t:"ヤマトとエリー、手首を並べて上げる。"},{w:"hero",t:"エルレオン、エレキスパーク！",v:"11_0228"},{w:"elly",t:"うん！",v:"11_0229"},{w:null,t:"アレク、ヤマトの肩をこぶしで軽く押して、一枚石の上のホエリオスを指さす。"},{w:"alek",t:"……陸に上げたら、水出せへんのか。",v:"11_0234"},{w:"elly",t:"ね、引っぱったでしょ！",v:"11_0236"}]],post:[]};
GR_EP[11]={"t": "準決勝", "sc": [["g11_01", "安い宿（朝）", 0], ["g11_02", "競技場の選手の通路（昼前）", 0], ["g11_03", "古い石の床に、水の溝（昼）", 0], ["g11_04", "準決勝", 1], ["g11_05", "勝負のあと（床のはし）", 0], ["g11_06", "客席の下の通路（準決勝、第二試合のあと）", 0]]};
GR_SC.g12_01=[{w:null,t:"決勝の前の夜。",v:"12_0029"},{w:null,t:"宿の廊下の小さな窓辺。"},{w:"elly",t:"お姉ちゃん、あしたね、決勝なんだよ。",v:"12_0031"},{w:"ana",t:"決勝！？　村のみんなに言わなきゃ。ロビーの画面で流すからね。",v:"12_0032"},{w:"elly",t:"えー、やめてよ。はずかしいもん。",v:"12_0033"},{w:"ana",t:"そんなことより、ちゃんと食べた？",v:"12_0034"},{w:"elly",t:"食べたよ。アレクが、安い串のお店を見つけてくれたの。",v:"12_0035"},{w:"ana",t:"あの子、ほんとに安いとこ見つけるのがうまいね。",v:"12_0036"},{w:"elly",t:"うん。でも人形は、勝ってからだって。",v:"12_0037"},{w:null,t:"声の波形が、笑い声で大きくゆれる。"},{w:null,t:"部屋。明かりを落とした中。"},{w:null,t:"ヤマトだけ、寝棚の上に座っている。"},{w:null,t:"ヤマトの画面。閉じた目の絵。"},{w:null,t:"アレク、寝返りを打って、ヤマトの背中を見る。"},{w:"alek",t:"……画面、まぶしいねん。寝られへんやん。",v:"12_0043"},{w:"hero",t:"（画面から目を上げずに）……あと一枚。",v:"12_0044"},{w:null,t:"アレク、体を起こして、ヤマトの画面をのぞく。閉じた目の絵が、何枚も。"},{w:null,t:"アレク、少しのあいだ、その絵を見ている。"},{w:null,t:"アレク、掛け物を頭までかぶる。"},{w:null,t:"窓のへりで丸くなっていたフォルンが、片目だけあけて、ヤマトの指の動きを見ている。"},{w:null,t:"フォルン、窓のへりから下りる。"},{w:null,t:"第12話　決勝",v:"12_0052"}];
GR_SC.g12_02=[{w:null,t:"宿の前の石段。"},{w:"alek",t:"……三十分たったで。遅れたら、賞金ゼロや。",v:"12_0059"},{w:null,t:"二階の窓から、エリーの声だけ。"},{w:"elly",t:"ねえ、リボン、白と水色どっちがいい？",v:"12_0061"},{w:"hero",t:"どっちでもいい！　入口で待ってるからな！",v:"12_0062"},{w:null,t:"ヤマト、もう坂を下りだしている。"},{w:null,t:"アレク、二階の窓と坂の下を見くらべてから、あとを追う。"},{w:null,t:"競技場の選手の入口。"},{w:"x",n:"案内のロボット",t:"組のバッジを、お見せください。",v:"12_0066"},{w:null,t:"ヤマト、自分の胸を見る。"},{w:null,t:"アレク、パーカーのポケットを探る。"},{w:"elly",t:"（息を切らして）間に合った！",v:"12_0071"},{w:"hero",t:"エリー、助かった！",v:"12_0073"},{w:"alek",t:"……遅れてきたん、本人やけどな。",v:"12_0075"}];
GR_SC.g12_03=[{w:null,t:"大会の三日目。決勝の客席は、上の方の席まで人でうまっていた。",v:"12_0080"},{w:null,t:"満員の客席。"},{w:null,t:"床の水の溝は、石のふたでふさがれている。"},{w:null,t:"貴賓席。日よけの下に、チャコールのストライプのスーツの男。"},{w:"x",n:"実況（場内の声）",t:"白い都テリオン大会、決勝！",v:"12_0085"},{w:"x",n:"実況（場内の声）",t:"前回の優勝者、レン選手！",v:"12_0086"},{w:null,t:"向こうの入口から、レンが一人で歩いてくる。"},{w:"dimi",f:"serious",t:"……バジリク。",v:"12_0088"},{w:null,t:"床のまん中で、地面がふくらむ。"},{w:"x",n:"実況（場内の声）",t:"対するは、オリーヴァ村の三人！",v:"12_0090"},{w:null,t:"選手の入口の横に、テリオン用の水の鉢。"},{w:"elly",t:"ラッキーカラーは、白だって！",v:"12_0093"}];
GR_SC.g12_05=[{w:null,t:"光が引いて、フォルンに。"},{w:null,t:"大きな画面の勝ち残りの表から、レンの名前の光がすっと消える。"},{w:null,t:"レン、しゃがんだまま、その画面を見上げる。"},{w:null,t:"レン、立ち上がる。"},{w:"hero",f:"serious",t:"……またやろうぜ、レン。",v:"12_0209"},{w:null,t:"レン、振り向かずに手を一回だけ上げる。"},{w:null,t:"登録の欄の、大人の男の名前。"},{w:null,t:"レン、画面を閉じる。"}];
GR_SC.g12_06=[{w:null,t:"床のまん中に、白い小さな台。係の人（2100年の白っぽい制服）が、空中に光の窓口を開く。"},{w:"x",n:"係の人",t:"相棒の登録です。手首を、窓口にかざしてください。",v:"12_0218"},{w:null,t:"ヤマト、左の手首をかざす。"},{w:null,t:"ヤマト、立ち上がる。"},{w:null,t:"ヤマト、手首の横の板を、フォルンの鼻先へ近づける。"},{w:null,t:"フォルン、においもかがずに、くるっとうしろを向く。"},{w:null,t:"客席が、どっと笑う。"},{w:null,t:"ヤマト、板を差し出していた手を、ゆっくり下ろす。"},{w:"hero",f:"serious",t:"……ちぇっ。別に。",v:"12_0225"},{w:null,t:"ヤマト、窓口に背を向けて、歩き出す。"},{w:null,t:"エリーが、一歩前に出かけて、止まる。アレクは腕を組んだまま、動かない。"},{w:null,t:"フォルン、走る。"},{w:null,t:"下ろしたままのヤマトの手のひらに、ぴょんと跳び乗る。"},{w:null,t:"ヤマトの足が止まる。"},{w:null,t:"フォルン、ヤマトの手のひらの上から、手首の横に浮かぶ光の板へ、前足をのばす。"},{w:null,t:"「キャウ！」。"},{w:null,t:"針が次の印へ、かちり。"},{w:null,t:"板が光る。字が変わる。"},{w:null,t:"フォルンの首元に、小さな光の点がともる。"},{w:null,t:"客席が、一拍遅れて、わっと沸く。"},{w:null,t:"フォルン、ヤマトの手のひらの上で、もう知らん顔をして、前足をなめている。"}];
GR_SC.g12_07=[{w:"x",n:"実況（場内の声）",t:"優勝、オリーヴァ村！　協賛の会社より、盾が贈られます！",v:"12_0242"},{w:null,t:"貴賓席から、チャコールのストライプのスーツの男が床へ下りてくる。いつもの笑顔。"},{w:null,t:"男、ヤマトの前に立つ。"},{w:"victor",t:"優勝、おめでとうございます。",v:"12_0245"},{w:null,t:"フォルン、手のひらから、ヤマトの肩へ跳び移る。"},{w:null,t:"男、ヤマトの肩の上のフォルンに、手をのばしかける。"},{w:null,t:"フォルン、チャコールのストライプのスーツをにらんで、のどの奥で低くうなる。"},{w:null,t:"男、手を止めて、笑ったまま引っこめる。"},{w:"victor",t:"おっと。これは、失礼。",v:"12_0250"},{w:"victor",t:"よく、しつけてありますね。",v:"12_0251"},{w:"hero",t:"しつけてねえよ。自分で乗ってきたんだ。",v:"12_0252"},{w:null,t:"男、笑顔のまま、フォルンの首元の光の点に、一度だけ目を落とす。"},{w:null,t:"男、付き人から盾を受け取って、ヤマトに渡す。"},{w:"hero",t:"ありがとな、スーツのおっさん！",v:"12_0256"},{w:"victor",t:"……誰が、おっさんですか。",v:"12_0257"},{w:null,t:"男、笑顔のまま。"},{w:null,t:"男、アレクの前へ。手を差し出す。"},{w:"victor",t:"あなたも、見事でした。",v:"12_0260"},{w:"alek",t:"……どうも。",v:"12_0261"},{w:null,t:"アレク、手をはなす。"},{w:"victor",t:"才能が、おありだ。",v:"12_0265"},{w:"elly",t:"ありがとうございます！",v:"12_0266"}];
GR_SC.g12_08=[{w:null,t:"係のお姉さんが、賞金の光の板を出す。アレク、その顔を見て、すっと前に出る。"},{w:null,t:"アレク、前髪を手ぐしで直す。"},{w:"alek",t:"（一段低い声で）……実は僕、この競技場のオーナーの息子でして。",v:"12_0276"},{w:"alek",t:"……毎年、一番ええ席で見てるんすわ。",v:"12_0277"},{w:null,t:"係のお姉さん、にこっと笑って、光の板をヤマトの方へ向ける。"},{w:"x",n:"賞金の係の人",t:"賞金は、優勝した方へ。",v:"12_0279"},{w:null,t:"ヤマト、盾を抱えたまま、肩でアレクを前へ押し出す。"},{w:null,t:"アレク、背すじをのばしたまま、光の板の数字をのぞきこむ。"},{w:"alek",t:"……なんぼや。",v:"12_0282"},{w:null,t:"係のお姉さんが、アレクのカードに光の板を当てる。"},{w:null,t:"アレク、すぐパーカーの内ポケットにしまう。"},{w:null,t:"フォルン、ヤマトの肩の上から、盾のふちをかじっている。"}];
GR_SC.g12_09=[{w:null,t:"貴賓席のうしろの小部屋。"},{w:null,t:"空中の画面の字。"},{w:null,t:"その下に、国ごとの光る地図。"},{w:null,t:"画面に、決勝のフォルレオンの写真。"},{w:null,t:"下に、小さな字「この子のような子を　かりたい人　十二人」。"},{w:null,t:"画面が替わる。"},{w:"kasia",t:"今月、拾った子です。四十体。",v:"12_0295"},{w:"victor",t:"値がつけば、だれかが大事にする。",v:"12_0296"},{w:null,t:"画面がもう一枚。"},{w:"victor",t:"あの子にも、学校のお金を出せ。",v:"12_0298"},{w:null,t:"ガラスの向こう、盾を抱えて歩くヤマトたち。"},{w:"victor",t:"カシア。今夜、字を読むあの子を呼べ。おれが会う。",v:"12_0300"},{w:null,t:"カシア、一礼して部屋を出る。男、ガラスの向こうから目を離さない。"}];
GR_SC.g12_10=[{w:null,t:"その夜。白い都の屋台の町は、遅くまで明かりが消えなかった。",v:"12_0307"},{w:null,t:"屋台の長い机。"},{w:null,t:"アレク、串にも手をつけずに、カードの、のこりのお金の数字を見ている。"},{w:null,t:"指で、けたを一つずつ数えている。"},{w:null,t:"アレク、カードをパーカーの内ポケットにしまう。"},{w:null,t:"エリーは、大会の初日に買えなかった大会限定の光る人形を、手のひらにのせて、にこにこしている。"},{w:"hero",t:"それ、アレクが買ったのか？",v:"12_0313"},{w:"alek",t:"……約束は、約束や。",v:"12_0314"},{w:null,t:"エリー、人形を両手で包んで、アレクにぺこりと頭を下げる。"},{w:null,t:"アレク、串をかじりながら、手首の画面をエリーへ向ける。"},{w:null,t:"エリー、画面は見ないで、人形を机に立てて、頭をなでる。"},{w:"hero",t:"串、あと二本！",v:"12_0319"},{w:null,t:"店のロボットの腕が、まん中の皿に、串を一本だけのせる。"},{w:null,t:"屋台の品書きに、『品切れ』の札が一瞬光る。"},{w:"alek",t:"じゃんけんや。",v:"12_0324"},{w:"hero",f:"serious",t:"……おう。一発で決めるぞ。",v:"12_0325"},{w:"hero",t:"（かじって）……うめえ。",v:"12_0336"},{w:"elly",t:"ジュース、おかわりもらってくるね！",v:"12_0337"},{w:"alek",t:"ほな、おれのは大きいのな。",v:"12_0338"},{w:"elly",t:"はーい。大きいのね！",v:"12_0339"}];
GR_BT[12]={mid:[[{w:null,t:"レン、手首の画面を見ずに立つ。地面から顔を出すバジリク。"},{w:null,t:"ヤマトの手首の画面の端に、きのうの夜描いた絵が一瞬（閉じた目の絵がいくつも）。"},{w:"x",n:"審判",t:"始め！",v:"12_0106"},{w:null,t:"三人が、手首の画面をかざす。"},{w:"x",n:"三人",t:"進化！",v:"12_0109"},{w:"hero",t:"フォルコン、一番うしろだ。",v:"12_0111"},{w:"hero",t:"ピリムサは左、クロベクは右！　はなれろ！",v:"12_0112"},{w:"elly",t:"分かった。ピリムサ、左ね！",v:"12_0113"},{w:"alek",t:"は？　フォルコン、前に出さへんの？",v:"12_0114"}],[{w:"hero",t:"見てろって。",v:"12_0115"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"岩には水やろ！　クロベク、突け！",v:"12_0121"},{w:null,t:"レンは、画面も見ずに、バジリクの背中だけを見ている。"},{w:"dimi",t:"魔眼封石（まがんロック）。",v:"12_0127"},{w:"alek",t:"クロベク！",v:"12_0129"},{w:null,t:"ヤマト、壁のむこうの線の外で膝をつく。"},{w:"hero",t:"フォルコン、待ってくれ。",v:"12_0135"},{w:"dimi",f:"serious",t:"……見ないのか。",v:"12_0143"},{w:null,t:"レン、バジリクの背中から、初めて目を上げる。"},{w:null,t:"レンの目が、光るフォルコンと、ヤマトの手のひらを往復する。"},{w:null,t:"ヤマトの目が床へ落ちる。"}],[{w:"hero",t:"フォルコン、前見てろ。合図したら、すぐ行け。",v:"12_0156"},{w:null,t:"ヤマト、手のひらを下ろす。"},{w:"elly",t:"ピリムサ、一回だけでいい！",v:"12_0159"},{w:"alek",t:"クロベク、回りこめ。出た所を横から突くで。",v:"12_0160"},{w:null,t:"ヤマト、左の手首の画面を、フォルコンへかざす。"},{w:"hero",t:"フォルコン、進化！",v:"12_0167"},{w:"dimi",t:"魔眼――",v:"12_0180"},{w:null,t:"アレクのレンズ。"},{w:null,t:"レンの口が、言いかけたまま止まる。"},{w:"hero",t:"いっけえ、フォルレオン！　灼熱地獄（しゃくねつじごく）！！",v:"12_0184"},{w:null,t:"ヤマトの声で、フォルレオンが跳ぶ。"}]],post:[{w:null,t:"バジリクが目を開けかける。"},{w:null,t:"審判の旗。観客席が一拍遅れて爆発する。"},{w:"hero",f:"smile",t:"……勝った。勝ったぞ、フォルン！！",v:"12_0192"},{w:null,t:"アレク、ヤマトの方を向いて、自分のまぶたを指でとんとさす。"},{w:"alek",t:"砂入ったら、目ぇ閉じるんや。",v:"12_0194"},{w:"elly",f:"smile",t:"ヤマト、勝った！　勝ったよ！",v:"12_0196"}]};
GR_EP[12]={"t": "決勝", "sc": [["g12_01", "宿（決勝の前の夜）", 0], ["g12_02", "宿の前〜選手の入口（決勝の日の昼）", 0], ["g12_03", "決勝の日の競技場（午後）", 0], ["g12_04", "決勝", 1], ["g12_05", "勝負のあと（表示と、名前を呼ぶ）", 0], ["g12_06", "登録の窓口", 0], ["g12_07", "表彰", 0], ["g12_08", "表彰のあと（賞金）", 0], ["g12_09", "貴賓席のうしろの小部屋（夕方）", 0], ["g12_10", "お祝いの夜（屋台の町）", 0]]};
GR_SC.g13_01=[{w:null,t:"大会が終わった夜。港のそばの屋台の町は、お祭りだった。",v:"13_0024"},{w:null,t:"港のそばの屋台の町。"},{w:null,t:"屋台が並ぶ。"},{w:null,t:"通りのまん中の空中の画面に、きょうの決勝がくり返し流れている。"},{w:null,t:"屋台の長い机。"},{w:null,t:"ヤマトのまわりに、子どもたちが五、六人。"},{w:"x",n:"屋台の子ども",t:"ねえ、優勝した狐って、この子？",v:"13_0030"},{w:"hero",t:"そうだぜ。今は寝てるけどな。",v:"13_0031"},{w:"x",n:"屋台の子ども",t:"決勝の火、すごかった！　さわってもいい？",v:"13_0032"},{w:"hero",t:"いいけど、決めんのはこいつな。",v:"13_0033"},{w:null,t:"ヤマト、左の手のひらを上にして、フォルンの前に置く。"},{w:null,t:"フォルン、片目をあける。"},{w:null,t:"フォルン、女の子の手のひらに、前足をぽんとのせる。"},{w:null,t:"女の子が、きゃあっと跳びはねる。子どもたち、わっと笑う。"},{w:null,t:"フォルン、何もなかった顔で、また丸くなる。"},{w:null,t:"机の向かいの、アレクの席は空いている。"},{w:null,t:"アレク、通りのくじの屋台から、景品の小さな袋をかかえて戻ってくる。"},{w:null,t:"フォルンの寝ている横に、どさっと山。"},{w:"hero",t:"アレク、それ全部くじか？",v:"13_0042"},{w:"alek",t:"（早口で）全部や。一軒一回、ただやねん。",v:"13_0043"},{w:"hero",t:"それ、何に使うんだよ。",v:"13_0044"},{w:"alek",t:"……使わへん。",v:"13_0045"},{w:"x",n:"屋台の女の子",t:"それ、一個ちょうだい。",v:"13_0047"},{w:"alek",t:"……あかん。売ったら五十ジェムや。",v:"13_0048"},{w:"hero",t:"ただでもらったやつだろ。",v:"13_0049"},{w:"x",n:"屋台の女の子",t:"……ケチ。",v:"13_0050"}];
GR_SC.g13_02=[{w:null,t:"飲み物の屋台。"},{w:null,t:"エリー、からのカップを返しに、屋台の裏の細い道へ。"},{w:null,t:"うしろに、黒いコートの女。"},{w:"kasia",t:"エリーさんね。優勝、おめでとう。",v:"13_0063"},{w:"elly",f:"surprised",t:"ありがとう！　……えっと、だれ？",v:"13_0064"},{w:"kasia",t:"カシアよ。ヴィクターさまが、お呼びよ。",v:"13_0065"},{w:null,t:"エリーの笑顔が、止まる。"},{w:null,t:"エリーの目が、カシアの耳のオレンジの輪へ行く。それから、通りの空中の画面。"},{w:"elly",f:"serious",t:"……行かない。友だちが待ってるもん。",v:"13_0068"},{w:"kasia",t:"あら。聞いてるんじゃないのよ。",v:"13_0069"},{w:null,t:"カシアの指が、エリーの手首の白い画面の上で止まる。"},{w:"kasia",t:"（耳もとで）アナさんのホテル、白い屋根がきれいね。",v:"13_0071"},{w:null,t:"エリーの目が、大きくなる。"},{w:null,t:"第13話　さらわれた夜",v:"13_0083"}];
GR_SC.g13_03=[{w:null,t:"屋台の机。机の上で丸くなっていたフォルンの耳が、ぴんと立つ。"},{w:null,t:"通りの石だたみを、からのカップが一つ、ころがってくる。"},{w:null,t:"ヤマト、顔を上げる。"},{w:"hero",f:"serious",t:"……エリー？",v:"13_0092"},{w:null,t:"ヤマト、もう走りだしている。"},{w:null,t:"アレク、串を放り出し、盾とクロッコをかかえて追う。"},{w:null,t:"細い道の奥。"},{w:null,t:"カバンの黄色いピリポンのぬいぐるみが、石の上で横を向いている。"},{w:null,t:"ヤマト、走りながらカバンをつかみ上げ、肩にかける。"}];
GR_SC.g13_04=[{w:null,t:"屋台の明かりが、背中の方に遠くなる。"},{w:null,t:"海へまっすぐのびる一本の桟橋。"},{w:null,t:"ヤマトの目が、欠けた光の玉に一回だけ止まる。"},{w:null,t:"桟橋の先に、明かりを消した黒い船。ゼノが、エリーをかついだまま、船へ上がっていく。"},{w:null,t:"甲板のエリーが、こっちを見る。口が動く。"},{w:"hero",t:"待ってろ！　今行く！",v:"13_0106"}];
GR_SC.g13_06=[{w:null,t:"黒い船の明かりが一つ、ともる。"},{w:null,t:"ヤマト、走る。"},{w:null,t:"甲板のへりに、エリー。ゼノの手をふりはらって、手すりから身を乗り出す。"},{w:"elly",t:"ヤマト！",v:"13_0187"},{w:null,t:"ヤマト、走りながら、右手をいっぱいにのばす。"},{w:null,t:"ヤマト、桟橋のいちばん先で止まる。"},{w:null,t:"のばした手が、宙に残る。"},{w:null,t:"ゼノの大きな手が、エリーの肩をうしろへ引く。"},{w:null,t:"船の明かりが、沖へ小さくなっていく。"},{w:null,t:"ヤマト、のばした手を、ゆっくりにぎる。"},{w:null,t:"にぎったこぶしで、桟橋の杭を、一回なぐる。"},{w:null,t:"アレク、桟橋のなかほどで立ち止まっている。"},{w:null,t:"フォルンが、よろよろと歩いてきて、ヤマトの足もとで止まる。ヤマトの顔を見上げる。"}];
GR_SC.g13_07=[{w:null,t:"安い宿の部屋。"},{w:null,t:"アレク、盾を壁に立てかける。"},{w:null,t:"ヤマト、エリーの白いカバンを、テーブルの上に置く。"},{w:null,t:"ヤマトの手首で、エリーがしめ直したおそろいの腕輪が、小さく光る。"},{w:null,t:"窓ぎわのアレク、パーカーのそでを、手首の上まで引き下ろす。"},{w:null,t:"フォルンが、テーブルに跳び上がる。"},{w:null,t:"ヤマトの手首が、呼び出しの音で鳴る。"},{w:null,t:"ヤマト、画面を見たまま、止まる。一回だけ息をすって、自分で画面にふれる。"},{w:null,t:"声だけの電話。空中に、アナの声の波形が小さく浮かぶ（顔は映さない）。"},{w:"ana",t:"ヤマト！　見てたよ、優勝！　村じゅう大さわぎよ。",v:"13_0213"},{w:"ana",t:"で、エリーは？　さっきから、かからないの。",v:"13_0214"},{w:"hero",f:"serious",t:"……アナさん。エリー、連れてかれた。",v:"13_0215"},{w:null,t:"声の波形が、平らになる。"},{w:"ana",t:"……だれに。",v:"13_0217"},{w:"hero",t:"黒いコートの女と、ヒゲのでかいおっさん。",v:"13_0218"},{w:"hero",t:"耳と胸に、オレンジの輪つけてた。",v:"13_0219"},{w:"ana",t:"……あの黒い車の連中ね。",v:"13_0221"},{w:"ana",t:"村のみんなに、心当たりを聞いて回る。",v:"13_0222"},{w:"hero",f:"serious",t:"……あした、迎えに行く。",v:"13_0223"},{w:"ana",t:"……ヤマト。あんたまで、いなくならないでよ。",v:"13_0224"}];
GR_SC.g13_08=[{w:null,t:"アレク、窓ぎわに立っている。"},{w:null,t:"指が、一つの行で止まる。"},{w:null,t:"アレク、その行を消そうとして、指を止める。"},{w:null,t:"ヤマト、それを見ていない。"},{w:"hero",t:"アレク。あしたの朝、行くぞ。",v:"13_0234"},{w:"alek",t:"……どこ行くんや。",v:"13_0235"},{w:"hero",t:"知らねえよ。探すの、お前の得意だろ。",v:"13_0236"},{w:null,t:"アレク、答えない。"},{w:null,t:"ヤマト、ふり向く。"},{w:"hero",t:"お前、なんか隠してんだろ。",v:"13_0239"},{w:"alek",t:"……それより、あしたの朝めし代、割り勘な。",v:"13_0240"},{w:"hero",t:"話、そらすな。",v:"13_0241"}];
GR_SC.g13_09=[{w:null,t:"同じ夜。白い都から遠く離れた、丘の上。",v:"13_0246"},{w:null,t:"丘の頂上に、古い石の門。"},{w:null,t:"門の奥に、白い屋敷。"},{w:null,t:"丘のふもとから、黒塗りのロボタクシーが坂を上っていく。"},{w:null,t:"車のうしろの窓。エリーの横顔。"},{w:null,t:"門が、内側から開く。"}];
GR_BT[13]={mid:[[{w:"kasia",t:"その子は、もう話がついてるの。",v:"13_0112"},{w:"hero",t:"どけよ！　エリー返せ！",v:"13_0113"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:null,t:"ヤマトとアレクが、手首の画面をかざす。"},{w:"x",n:"二人",t:"進化！",v:"13_0118"},{w:null,t:"ヤマト、左の手首の画面を、フォルコンへかざす。"},{w:"hero",t:"フォルコン、進化！",v:"13_0125"},{w:null,t:"ヤマト、手首を見て、それからフォルコンを見る。"},{w:null,t:"ヤマトとアレク、二体のうしろ、岸の側へ大きく下がって立つ。"},{w:"hero",t:"フォルコン、撃て！",v:"13_0129"}],[{w:"alek",t:"クロベク、行け！",v:"13_0131"},{w:null,t:"レンズの字が『見失いました』で止まる。"},{w:null,t:"ヤマト、暗い空を探すのをやめる。"},{w:null,t:"ヤマト、手のひらを下ろす。右手で、二本目の街灯の真上の暗がりを指す。"},{w:"alek",t:"クロベク、今や！",v:"13_0148"},{w:null,t:"アレク、ヤマトの横へ走りこんで、二本目の街灯を指でさす。"},{w:"alek",t:"光が欠けたとこに、おったんか。",v:"13_0152"},{w:null,t:"ヤマト、うなずく。"},{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"13_0156"},{w:"hero",f:"surprised",t:"うそだろ……！",v:"13_0165"}]],post:[{w:null,t:"ルナウル、柱の根もとで羽をたたんだまま、動かない。"},{w:null,t:"ヤマトの目が、ちかちかする目に止まる。"},{w:"hero",t:"フォルコン、つめろ！　あいつ、止まってる！",v:"13_0168"},{w:"alek",t:"クロベク、寄せえ！",v:"13_0169"},{w:null,t:"フォルコンとクロベクが、左右から柱の根もとへ跳びこむ。"},{w:"alek",t:"……画面押して、無理やり変えよった。",v:"13_0177"}]};
GR_EP[13]={"t": "さらわれた夜", "sc": [["g13_01", "白い都・屋台の町（夜）", 0], ["g13_02", "飲み物の屋台の裏", 0], ["g13_03", "屋台の机〜裏の階段", 0], ["g13_04", "三番桟橋（夜）", 0], ["g13_05", "勝負（2Dアニメ）", 1], ["g13_06", "桟橋の先", 0], ["g13_07", "安い宿の部屋（夜ふけ）", 0], ["g13_08", "安い宿の部屋（同じ夜）", 0], ["g13_09", "獅子門の丘（夜）", 0]]};
GR_SC.g14_01=[{w:null,t:"エリーのいない朝。二人は、白い都を出た。",v:"14_0024"},{w:null,t:"宿の入口で、アレクが優勝の盾を、預かりのロボットに渡す。"},{w:null,t:"宿の前の道に、白いロボタクシーがすっと止まる。"},{w:null,t:"車の中の空中の文字「行き先をどうぞ」。"},{w:"hero",t:"で、どこ行くんだよ。",v:"14_0028"},{w:null,t:"アレク、頭のゴーグルも下ろさずに、空中の文字に言う。"},{w:"alek",t:"獅子門の丘。北の坂の下まで。",v:"14_0030"},{w:null,t:"空中の文字「獅子門の丘　北の坂の下　約1時間30分」。"},{w:"hero",f:"serious",t:"……早っ。地図も見ねえで。",v:"14_0032"},{w:null,t:"アレク、窓の外を見たまま、ゴーグルのふちを指で一回はじく。"},{w:"alek",t:"……前に、仕事で来た。",v:"14_0034"},{w:"hero",t:"仕事って、なんの。",v:"14_0035"},{w:null,t:"アレク、窓の外を見たまま、答えない。"},{w:null,t:"第14話　獅子門の丘",v:"14_0039"}];
GR_SC.g14_02=[{w:null,t:"坂の下の道。"},{w:null,t:"坂の下のオリーブ林。"},{w:"alek",t:"かたっ。きのうのパンやん。割り勘したのに。",v:"14_0047"},{w:"hero",t:"フォルン、ちょっとだけ、あっためてくれ。",v:"14_0048"},{w:null,t:"ヤマト、パンをフォルンの前に置く。"},{w:null,t:"ぼっ。パンが、まっ黒なかたまりになる。"},{w:null,t:"ヤマト、まっ黒なかたまりを二つに割って、片方をアレクにわたす。自分の方を、平気な顔でばりばりかじる。"},{w:null,t:"アレク、まっ黒なはしを、かじる。顔じゅうしわだらけになる。"},{w:"alek",t:"……よう、うまそうに食えるな。",v:"14_0053"},{w:"hero",t:"うまいじゃん。",v:"14_0054"},{w:"hero",f:"serious",t:"……いらねえのかよ。",v:"14_0056"},{w:"alek",t:"捨てたら損やろ。お前の腹に入れとく。",v:"14_0057"}];
GR_SC.g14_03=[{w:null,t:"丘の上に、石の獅子が二頭、門を守っていた。",v:"14_0065"},{w:null,t:"丘の頂上。古い石の門。"},{w:null,t:"門の内側に、新しい白い柵。"},{w:null,t:"黒いドローンが一機、門の上で止まっている。"},{w:null,t:"二人が呼ぶ前に、白い柵が、すうっと横に開く。"},{w:null,t:"門の内側に、あの協賛の男が立っている。笑顔。"},{w:null,t:"ネクタイはない。"},{w:null,t:"右の小指に、小さな金の印章の指輪。"},{w:null,t:"男のうしろに、大きな黒い影。"},{w:null,t:"【プロフィール】ヴァンプロード／闇／●●●／紫の羽をコートにする"},{w:null,t:"そのまたうしろに、ゼノ。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"……あかん、こいつ。",v:"14_0078"},{w:null,t:"ヴィクター、一歩前へ出る。"},{w:"victor",t:"早かったな。",v:"14_0081"},{w:"hero",t:"あんた……大会で盾くれたおっさん！",v:"14_0082"},{w:"victor",t:"……小僧。",v:"14_0083"},{w:"victor",t:"ヴィクターだ。",v:"14_0084"},{w:null,t:"ヤマト、男の指の輪を見る。"},{w:"hero",f:"serious",t:"……やっぱり、お前らか。",v:"14_0086"},{w:"hero",t:"エリー返せよ！",v:"14_0087"},{w:null,t:"ヤマト、門の内へ、一歩ふみこむ。"},{w:"victor",t:"……ここでは、勝手に動くな。",v:"14_0089"},{w:"hero",t:"おれに命令すんな。",v:"14_0090"},{w:null,t:"ヴィクターの指輪の指が、門の柱を、とん、とん。"},{w:"victor",t:"……ヴァンプロード。出ろ。",v:"14_0092"},{w:"hero",f:"serious",t:"……フォルン、撃て！",v:"14_0098"},{w:"victor",t:"狐は、あとでいい。話があるのは、そっちだ。",v:"14_0114"},{w:"victor",t:"エリーなら上だ。……上がれ。茶を出す。",v:"14_0116"},{w:"hero",t:"茶なんかいらねえ。",v:"14_0117"}];
GR_SC.g14_04=[{w:null,t:"屋敷の奥のテラス。"},{w:null,t:"テラスの前は、刈りこんだ芝の庭。"},{w:null,t:"ヴァンプロードは、ヴィクターの椅子のうしろに立っている。"},{w:null,t:"ヴィクター、カップを持ち上げる。"},{w:null,t:"ヴィクターの横の空中に、ロケットの図面が一枚。"},{w:"victor",t:"アレク。ロケットの金なら、いくらでも出す。",v:"14_0128"},{w:null,t:"ヴィクター、胸のポケットから、手のひらほどのうすいカードを出す。"},{w:null,t:"テーブルの上を、アレクの前へすべらせる。"},{w:null,t:"胸のポケットの奥に、角のすり切れた古い単語帳が見える。"},{w:null,t:"アレク、カードを見る。手をのばさない。"},{w:"hero",f:"serious",t:"……アレク。こいつのこと、知ってたのかよ。",v:"14_0134"},{w:null,t:"アレクの指が、テーブルのふちを一回こする。"},{w:"hero",t:"フォルン運べって、こいつに言われてたのか？",v:"14_0136"},{w:null,t:"アレクの手が、テーブルの下で、パーカーのすそをにぎる。"},{w:null,t:"ヴィクター、カップを置く。笑顔のまま。"},{w:"victor",t:"……仕事を頼んだのは、おれだ。",v:"14_0139"},{w:null,t:"ヤマトの目が、アレクの手首の画面に行く。"}];
GR_SC.g14_05=[{w:null,t:"屋敷の中から、テラスへ下りる白い階段。"},{w:null,t:"階段の上に、カシアが立っている。"},{w:"hero",t:"エリー！",v:"14_0148"},{w:null,t:"ヤマト、椅子をけって立つ。"},{w:"hero",t:"けがしてねえか？　帰るぞ！",v:"14_0150"},{w:"elly",t:"してないよ。ピリポンも、ほら。",v:"14_0151"},{w:null,t:"ピリポン、エリーの髪から顔を出して、小さく、ぱちっ。"},{w:"hero",t:"じゃあ、下りてこいよ。",v:"14_0153"},{w:"elly",t:"うん。……アレクも、来てくれたんだ。",v:"14_0154"},{w:"alek",t:"（テラスから、カードを見たまま）……ついでや。",v:"14_0155"},{w:null,t:"ヤマト、横目でアレクを見る。すぐ、エリーに目をもどす。"},{w:null,t:"エリー、一段下りる。その目が、庭の柱の字で止まる。"},{w:null,t:"すり減った昔の字。"},{w:null,t:"ヴィクター、笑顔のまま立ち上がる。"},{w:"victor",t:"読めたか。",v:"14_0160"},{w:null,t:"エリー、柱の字を見たまま、小さくうなずく。"},{w:"victor",t:"ここの記録、全部読ませてやる。読むだけでいい。",v:"14_0162"},{w:null,t:"ヴィクター、指を一度だけ動かす。エリーの目の前の空中に、画面が一枚開く。"},{w:null,t:"テラスのアレクの目が、その画面に止まる。"},{w:null,t:"ヴィクター、指輪の指を、階段の手すりに置く。"},{w:"victor",t:"……決めろ。",v:"14_0167"},{w:null,t:"エリーの目の前で、画面が閉じる。"},{w:null,t:"エリーの目が、手首の白い画面に落ちる。"},{w:null,t:"さっきの映像と同じ向きの、白い屋根とため池。前で、アナとエリーが手をふっている。"},{w:null,t:"エリーの指が、待ち受けのアナに、そっとふれる。"},{w:"hero",t:"なに言ってんだよ。エリー、行くぞ。",v:"14_0174"},{w:"elly",t:"わたし、ここに残る。",v:"14_0177"},{w:"hero",f:"angry",t:"は？　ふざけんなよ。",v:"14_0178"},{w:"hero",t:"こいつの言うことなんか、信じんなよ！　来いって！",v:"14_0180"},{w:"hero",f:"serious",t:"……エリー。ほんとに、いいのかよ。",v:"14_0191"},{w:"elly",f:"serious",t:"……へーき、へーき。",v:"14_0193"},{w:"victor",t:"ゼノ。客が帰る。門まで送れ。",v:"14_0196"}];
GR_SC.g14_06=[{w:null,t:"門の外。うしろで、ゼノが白い柵を閉める。"},{w:null,t:"屋敷の裏の道から、黒い荷車が出てきて、二人を追いこす。"},{w:null,t:"ヤマト、手首の画面を上げて、札を一枚撮る。"},{w:null,t:"丘を下りる道。"},{w:null,t:"アレクが前、ヤマトがうしろ。"},{w:null,t:"アレク、パーカーのポケットから研究のお金のカードを出す。"},{w:null,t:"道ばたの、ごみを集めるロボットの箱が、口をあけて待っている。"},{w:null,t:"アレク、カードを箱の上にかざす。……そのまま、ポケットに戻す。"},{w:null,t:"ヤマトは、それを見ている。"},{w:null,t:"坂の下。アレクが手首で車を呼ぶ。"},{w:null,t:"アレクが車の方へ歩く。"},{w:null,t:"ヤマト、車の方へは行かない。"},{w:"hero",t:"おれ、ここで寝る。",v:"14_0215"},{w:null,t:"ヤマト、右の手首に白いリボンを結び直す。目は、丘の上の門。"},{w:null,t:"アレク、車のドアの前で止まる。"},{w:"alek",t:"……ほな、今夜は宿代、いらんな。",v:"14_0218"},{w:null,t:"ヤマト、門を見たまま、根もとの横を少しだけあける。"},{w:null,t:"アレク、荷物から、銀色のうすいシートを出す。"}];
GR_SC.g14_07=[{w:null,t:"古い木の下に、銀色のうすいシートが一枚。"},{w:null,t:"シートの下で、アレクがヤマトに背中を向けて横になっている。"},{w:null,t:"ヤマトは、あおむけ。右の手のひらを、顔の前に上げて見ている。"},{w:null,t:"右の手首に、さっき結んだ白いリボン。"},{w:null,t:"ヤマト、手をにぎる。"},{w:null,t:"草をふむ、小さな足音。"},{w:null,t:"フォルン、シートにもぐりこむ。"},{w:null,t:"ヤマト、手を胸の上に下ろす。"},{w:null,t:"ヤマトとフォルンの間に、指一本ぶんのすき間。"},{w:null,t:"背中を向けたアレクの手首が、小さく光る。"},{w:null,t:"「エリー、いました」と打って、送る。"},{w:null,t:"背中を向けたアレクの目が、暗い中で、あいている。"}];
GR_SC.g14_08=[{w:null,t:"同じ夜。屋敷の、地下。",v:"14_0237"},{w:null,t:"天井の低い、白い部屋。"},{w:null,t:"画面に、古い石の扉。"},{w:null,t:"エリーが、扉の前に立っている。"},{w:null,t:"うしろの暗がりに、ヴィクターの青い濃紺のスーツ。"},{w:null,t:"エリー、扉のいちばん上の字を見る。"},{w:"victor",t:"近いうちに、本物を見せてやる。",v:"14_0243"},{w:null,t:"エリー、映った扉の字を、指でなぞりはじめる。"},{w:null,t:"扉の字が、エリーの指の速さで、一つずつ白く光っていく。"},{w:null,t:"エリー、指を止めずに、ヴィクターの方をふり向く。にっこり笑う。"},{w:null,t:"ヴィクター、指輪の指で、胸ポケットの古い単語帳を、上からそっと押さえる。"},{w:null,t:"ヴィクターの笑顔が、少しだけ止まる。"},{w:null,t:"エリー、前を向き直して、指をはなす。"},{w:null,t:"エリー、左の手首の白い画面を、そっとさわる。"}];
GR_EP[14]={"t": "獅子門の丘", "sc": [["g14_01", "白い都の宿の前（朝）", 0], ["g14_02", "丘のふもとのオリーブ林（昼）", 0], ["g14_03", "獅子の門", 0], ["g14_04", "屋敷のテラス", 0], ["g14_05", "テラスの階段", 0], ["g14_06", "帰り道（夕方）", 0], ["g14_07", "丘のふもとのオリーブ林（夜）", 0], ["g14_08", "屋敷の地下（夜）", 0]]};
GR_SC.g15_01=[{w:null,t:"オリーブの木の横。"},{w:null,t:"間に空いた席。"},{w:null,t:"空中の文字「行き先をどうぞ」。"},{w:"hero",t:"（空中の文字に）……コリンタ。",v:"15_0029"},{w:"alek",t:"村ちゃうんか。",v:"15_0030"},{w:null,t:"ヤマト、手首の画面をアレクの顔の前に向ける。"},{w:null,t:"アレク、ゴーグルにふれず、窓の外を見る。"},{w:null,t:"町を南北にまっすぐ走る運河。"},{w:null,t:"空中の文字の下に、赤い字「この先の橋　通れません」。"},{w:null,t:"前に、運河をまたぐ低い橋。"},{w:null,t:"止まった車の中。"},{w:"hero",f:"serious",t:"……あいつのこと、なんで黙ってたんだよ。",v:"15_0038"},{w:"alek",t:"言うたら、ロケットの金、止まってたやろ！",v:"15_0039"},{w:"hero",t:"金かよ。エリー、連れてかれたんだぞ。",v:"15_0040"},{w:null,t:"アレク、ドアを乱暴に開けて、先に降りる。"},{w:null,t:"橋の向こうの運河。"},{w:null,t:"橋のたもとに、小さな机。"},{w:null,t:"胸に、オレンジの輪と、大きな名札。"}];
GR_SC.g15_02=[{w:null,t:"ヤマト、車から降りて、机の前へ。"},{w:null,t:"机の上に、端末が一台。"},{w:"hero",t:"おい、名札。橋いつ開くんだよ。",v:"15_0049"},{w:"nomos",t:"誰が名札ですか。ノモスです。",v:"15_0050"},{w:"nomos",t:"決まりですから、通せません。",v:"15_0051"},{w:null,t:"ノモスの目が、橋の向こうの黒い荷の船へ、一回だけ行く。"},{w:null,t:"第15話　運河の町コリンタ",v:"15_0054"}];
GR_SC.g15_03=[{w:null,t:"ヤマト、ノモスの胸のオレンジの輪を見る。"},{w:"hero",t:"お前、あいつの——",v:"15_0061"},{w:"alek",t:"（ヤマトの前に出て）待合所、一泊いくらっすか。",v:"15_0062"},{w:null,t:"ヤマト、アレクの背中をにらむ。"},{w:"hero",t:"おい。",v:"15_0064"},{w:null,t:"アレク、聞いていない。"},{w:null,t:"岸の上の、古い石の倉庫を直した待合所。"},{w:"nomos",t:"一人、十五ジェムコインです。",v:"15_0067"},{w:"alek",t:"テリオンは、ただっすよね。",v:"15_0068"},{w:"nomos",t:"テリオンも一人に数える、と決まりに書いてあります。",v:"15_0069"},{w:"alek",t:"ほな、こいつら外で寝かせるんで。",v:"15_0070"},{w:null,t:"アレクの足もとのクロッコが、運河のへりに首をつっこむ。"},{w:null,t:"アレク、ずぶぬれのまま、真顔で手首の画面の計算を続ける。"},{w:"nomos",t:"テリオンを外で寝かせるのは、決まりで禁止です。",v:"15_0073"},{w:null,t:"アレク、画面を打つ指のまま、固まる。"},{w:null,t:"ヤマト、口を手でおさえて、肩をふるわせる。"},{w:null,t:"自分の手首の画面で払って、運河名物の揚げ菓子を一袋買って戻る。"},{w:"alek",t:"……そんなもん、なんぼしたんや。",v:"15_0078"},{w:null,t:"アレクのパーカーのポケットから、同じ揚げ菓子の袋がのぞいている。"},{w:"hero",t:"（足もとのフォルンに）お前は、半分な。",v:"15_0081"}];
GR_SC.g15_04=[{w:null,t:"橋の手前の、運河ぞいの石だたみの広場。"},{w:null,t:"植えこみの前に、小さな札。"},{w:null,t:"字の下に、人の絵とテリオンの絵。"},{w:null,t:"庭師のロボットが、葉の先をそろえている。"},{w:null,t:"ホタルンが一匹、植えこみの葉のあいだへ、すっともぐる。"},{w:null,t:"【プロフィール】ホタルン／光・森／●●○／葉のかげにもぐるホタル"},{w:null,t:"光だけが、葉のすき間からもれる。"},{w:null,t:"ヤマト、船のへりのケースの前に立つ。"},{w:null,t:"ヤマトの手が、ケースのふたにかかる。"},{w:null,t:"橋のたもとで、ノモスが立ち上がる。"},{w:"nomos",t:"荷にさわるのは、禁止です。",v:"15_0096"},{w:"hero",t:"中にテリオンいるじゃねえか！　こんなの、ほっとけるかよ！",v:"15_0097"},{w:null,t:"ノモス、机の上の端末を押す。"},{w:null,t:"船の屋根から、光る虫のような子が二匹、ふわっと飛び立つ。"}];
GR_SC.g15_06=[{w:null,t:"橋の向こうから、丸い目のライトの、古い黒いスポーツカー。"},{w:null,t:"ノモスが、机のうしろで背すじをのばし直す。"},{w:null,t:"運転席から、青い濃紺のスーツの男が降りる。"},{w:null,t:"うしろに、オレンジの輪の黒い大きな車。"},{w:null,t:"最後に、紫の羽をコートのように肩にかけたヴァンプロードが、のそりと降りる。"},{w:null,t:"大きな車が、ふっと軽く浮き上がる。"},{w:null,t:"ヴィクター、広場の石だたみの焦げあとを見る。それから、ノモスを見る。"},{w:null,t:"ヴィクター、ノモスの机を、指輪の指で、とん、とん。"},{w:"victor",t:"荷を先に出せ。橋はそのあとだ。",v:"15_0182"},{w:"nomos",t:"はい。決まりどおりに。",v:"15_0183"},{w:"victor",t:"その狐も、言うことを聞くようにしてやる。",v:"15_0189"},{w:"hero",t:"さわんな！",v:"15_0190"},{w:"hero",t:"フォルン！",v:"15_0193"},{w:"victor",t:"光ったか。……なら、うちの品じゃない。",v:"15_0202"},{w:"victor",t:"……自分から来る子は、高く売れるんだがな。",v:"15_0204"},{w:"victor",t:"……勝手に動くと、すぐ使えなくなるぞ。",v:"15_0209"}];
GR_SC.g15_07=[{w:null,t:"運河の岸。待合所の裏。"},{w:null,t:"アレク、岸の石に腰をおろす。"},{w:null,t:"アレクの手首に、着信「アナ」がずらり。"},{w:null,t:"アレク、一つ息をはいて、ふれる。"},{w:null,t:"声だけの電話。空中に、アナの声の波形が小さく浮かぶ（顔は映さない）。"},{w:"ana",t:"やっと出た。ゆうべから、何回かけたと思ってるの。",v:"15_0224"},{w:"alek",t:"……すんません。エリー、自分で残るって。",v:"15_0225"},{w:null,t:"声の波形が、しばらく平らなまま。"},{w:"ana",t:"……あの子が、自分で？",v:"15_0227"},{w:"alek",t:"はい。村、チップの子に囲まれてます。",v:"15_0228"},{w:"alek",t:"気ぃつけてください。",v:"15_0229"},{w:"ana",t:"……村は、ヤニスさんたちと見てるから。",v:"15_0231"},{w:"ana",t:"港で、黒い車の人が話してた。エリー、あさって山の向こうへ。",v:"15_0232"},{w:null,t:"ヤマト、顔を上げる。"},{w:"ana",t:"ヤマト、そこにいる？",v:"15_0234"},{w:"hero",t:"いる。聞いてた。",v:"15_0235"},{w:"ana",t:"今から送るの、エリーに会えたら見せて。",v:"15_0236"},{w:null,t:"ヤマトの手首が、ぴこん、と鳴る。"},{w:null,t:"ヤマト、それを開かずに、画面を見ている。"},{w:"ana",t:"あんたたちは、エリーをお願い。",v:"15_0239"},{w:"hero",t:"エリーは、連れて帰る。",v:"15_0240"},{w:null,t:"声の波形が消える。"}];
GR_SC.g15_08=[{w:null,t:"アレク、立ち上がる。"},{w:null,t:"アレク、パーカーのポケットから、研究のお金のカードを出す。"},{w:null,t:"長い数字が光っている。"},{w:"alek",t:"……これ、返しといてください。",v:"15_0247"},{w:"nomos",t:"……お預かりします。",v:"15_0248"},{w:null,t:"ノモス、カードを両手で受け取って、子どもの絵の写真立ての横に、まっすぐ置く。"},{w:null,t:"ヤマト、靴のつま先で、岸の小石を一つ転がす。"},{w:null,t:"ヤマト、橋の下の、遠ざかる黒い荷の船を見る。"},{w:null,t:"ヤマト、手首の画面にふれる。"},{w:"hero",t:"アレク。谷だ。",v:"15_0253"},{w:null,t:"アレク、自分の手首の地図で、谷の印を指で一回なぞる。だまって閉じる。"},{w:null,t:"アレク、手首の画面にふれる。"},{w:null,t:"アレク、先に乗る。"},{w:null,t:"二人のあいだに、空いた席が一つ。"}];
GR_SC.g15_09=[{w:null,t:"その夜。獅子門の丘の屋敷。",v:"15_0260"},{w:null,t:"エリー、スプーンを持ったまま、食べていない。"},{w:null,t:"屋敷の地下。"},{w:null,t:"エリーが、はだしで入ってくる。"},{w:null,t:"檻の中の小さな丸い子が、オレンジの目でエリーを見る。"},{w:"elly",t:"ピリポン、見て。この子、かわいくない？",v:"15_0266"},{w:null,t:"ピリポン、エリーの髪の中から顔を出す。"},{w:null,t:"エリー、檻の格子の前に、指を一本さし出す。"}];
GR_SC.g15_10=[{w:null,t:"山あいの暗い道。"},{w:null,t:"車の中。ヤマトとアレクが、両はしの窓にもたれて眠っている。"},{w:null,t:"前の空中の文字「大理石の谷まで　あと9時間」。"},{w:null,t:"エリー、手首の白い画面に、字を一つずつ写す。"},{w:null,t:"写した行を、画面の奥の、名前のない欄へ動かす。"},{w:null,t:"戸の外で足音。"},{w:null,t:"閉じる前の画面に、字が一行。"},{w:null,t:"廊下の先、エリーの部屋の戸の下から、細い明かり。"}];
GR_BT[15]={mid:[[{w:null,t:"ヤマト、左の手首の画面を、フォルンへかざす。"},{w:null,t:"ヤマト、しぶきのかかる運河のへりを見て、フォルコンの印に指をかける。"},{w:"hero",t:"フォルン、進化！",v:"15_0108"},{w:"alek",t:"クロッコ、進化！",v:"15_0109"},{w:null,t:"ヤマト、横のアレクをにらむ。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"hero",t:"フォルコン、撃て！",v:"15_0120"},{w:"hero",t:"アレク、合わせろ！",v:"15_0124"}],[{w:"hero",t:"フォルコン、クロベク、融合！",v:"15_0127"},{w:null,t:"アレクの声は重ならない。"},{w:null,t:"アレク、手首をパーカーのポケットに入れる。"},{w:"hero",f:"angry",t:"……なんでだよ！",v:"15_0131"},{w:null,t:"アレク、ポケットに手を入れたまま、前だけ見る。"},{w:null,t:"アレク、葉のあいだの光を目で追って、舌打ちする。"},{w:"hero",f:"serious",t:"……テリオンにも、×ついてんぞ。",v:"15_0145"},{w:"nomos",t:"ホタルン、出なさい。決まりですから。",v:"15_0149"}],[{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"15_0152"},{w:null,t:"ノモス、端末を持ったまま、背すじをのばして立っている。"},{w:null,t:"アレク、ノモスを見たまま、ひじでヤマトの腕を一回つつく。"},{w:"alek",t:"……テリオンも一人、やもんな。",v:"15_0158"},{w:"nomos",t:"（端末を見たまま）……数え方は、合っています。",v:"15_0159"},{w:null,t:"ヤマト、アレクを見る。"},{w:"hero",t:"さっきの融合、わざとだな。",v:"15_0162"},{w:"alek",t:"合わさんでも、勝てたやん。",v:"15_0163"},{w:null,t:"ヤマト、船のへりのケースへ走る。ふたに手をかける。"},{w:null,t:"ヤマト、ふたに手をかけたまま、動けない。"}]],post:[]};
GR_EP[15]={"t": "運河の町コリンタ", "sc": [["g15_01", "ロボタクシーの中〜運河の橋の前（朝）", 0], ["g15_02", "橋のたもと・ノモスの机", 0], ["g15_03", "橋のたもと（昼前）", 0], ["g15_04", "運河ぞいの広場・黒い荷の船", 0], ["g15_05", "勝負（2Dアニメ）", 1], ["g15_06", "運河ぞいの広場（ヴィクター）", 0], ["g15_07", "運河の岸・アナの電話（夕方）", 0], ["g15_08", "ノモスの机〜地図（夕方）", 0], ["g15_09", "屋敷・檻の部屋（夜）", 0], ["g15_10", "夜の道", 0]]};
GR_SC.g16_01=[{w:null,t:"獅子門の丘の屋敷。"},{w:null,t:"エリー、寝台のはしに座っている。"},{w:null,t:"戸が軽く二回鳴って、開く。"},{w:"kasia",t:"おはよう。あした、山の向こうへ移るわ。",v:"16_0030"},{w:"elly",f:"serious",t:"……山の向こう？　なんで？",v:"16_0031"},{w:"kasia",t:"ヴィクターさまの用が済むまで、向こうにいてもらう。",v:"16_0032"},{w:"elly",t:"お姉ちゃんの村から、遠くなる？",v:"16_0033"},{w:"kasia",t:"遠くはないわ。……眺めは、いいそうよ。",v:"16_0034"},{w:null,t:"カシア、戸を閉める。"},{w:null,t:"エリー、窓の外を見る。"},{w:null,t:"エリー、左の手首の画面を開く。"}];
GR_SC.g16_02=[{w:null,t:"大理石の谷。山がまるごと、白い石でできている。",v:"16_0040"},{w:null,t:"谷の入口の道。"},{w:null,t:"谷の両側の山はだが、白い。"},{w:null,t:"ヤマト、肩の白いカバンをかけ直して、谷の奥へ歩きだす。"},{w:null,t:"アレク、少しおくれて歩く。"},{w:"alek",t:"で、谷に来て、どうするんや。",v:"16_0045"},{w:"hero",t:"あいつらの荷が来てんだろ。何かあるに決まってる。",v:"16_0046"},{w:"alek",t:"何かって、何や。",v:"16_0047"},{w:"hero",t:"行きゃ分かる。谷の奥だ、奥。",v:"16_0048"},{w:null,t:"ヤマト、足を止めない。"},{w:null,t:"第16話　大理石の谷",v:"16_0051"}];
GR_SC.g16_03=[{w:null,t:"日が上がる。"},{w:null,t:"粉が、ヤマトの黒い髪に積もる。"},{w:"hero",t:"（くしゃみ）アレク、お前もまっ白。",v:"16_0059"},{w:null,t:"アレク、パーカーのフードをかぶって、ひもをきゅっとしぼる。顔が半分になる。"},{w:null,t:"谷のいちばん奥。"},{w:null,t:"入口の前に、新しい黒い柵。"},{w:null,t:"柵の上に、黒いドローンが一機。"},{w:null,t:"入口の前の地面に、太いタイヤのあとが何本も。"},{w:null,t:"アレク、しゃがんでタイヤのあとを見る。"},{w:null,t:"ヤマト、柵の前に立つ。"},{w:"alek",t:"待て待て待て。開けといてくれるん、気味悪いて。",v:"16_0067"},{w:null,t:"ヤマト、聞かずに、もう中へ入っていく。"}];
GR_SC.g16_05=[{w:null,t:"グリフォ、起き上がる。"},{w:null,t:"ヤマト、グリフォの羽のつけ根の帯を見る。"},{w:null,t:"グリフォ、くちばしをかちっと鳴らす。"},{w:null,t:"ヤマトの手が、宙で止まる。"},{w:null,t:"ヤマト、自分の右手を見る。"},{w:null,t:"ヤマト、手を下ろす。"},{w:null,t:"ヤマト、うしろへ下がる。"},{w:null,t:"フォルンが、ヤマトのとなりに来て座る。しっぽを体に巻く。"},{w:"alek",t:"……なんで座りこむねん。",v:"16_0150"},{w:null,t:"アレク、ヤマトの目の先を追う。"},{w:null,t:"入口から入る光が、床の上に長くのびている。"},{w:null,t:"奥で、アレクがケースのふたの空中の札を、指で一つずつ出している。"},{w:null,t:"ヤマトは、グリフォから目を離さない。"},{w:null,t:"光の筋が、白いカバンのところまで来る。"},{w:null,t:"グリフォ、首をのばす。"},{w:null,t:"グリフォ、一歩、出る。"},{w:null,t:"グリフォ、カバンの前まで来る。"},{w:null,t:"グリフォ、顔を上げる。"},{w:null,t:"ヤマト、動かない。"},{w:null,t:"グリフォ、カバンのひもをくわえる。"},{w:null,t:"グリフォ、ヤマトのひざの横にカバンを置く。"},{w:null,t:"ヤマトの左の手首の画面が、ぽうっと一度だけ光る。"},{w:null,t:"ヤマト、ゆっくり息をはく。"},{w:"alek",t:"（ケースの方から、ちらっとふり向いて）……そいつ、エリーのカバンに頭のせさすなよ。",v:"16_0165"},{w:"hero",f:"angry",t:"うっせ。毛は、あとではたく。",v:"16_0166"},{w:null,t:"グリフォ、カバンに頭をのせたまま、目だけでヤマトを見ている。"},{w:null,t:"左の羽は、体に寄せたまま。"},{w:null,t:"フォルン、ヤマトの肩に跳び上がり、そこから頭の上に乗る。グリフォを見下ろして、しっぽを立てる。"},{w:null,t:"グリフォ、すっと立つ。"},{w:null,t:"アレク、荷物を見る。"},{w:null,t:"グリフォ、頭を上げて出口へ。"},{w:null,t:"ヤマトを見る。"},{w:null,t:"ヤマト、カバンを拾って肩にかける。"}];
GR_SC.g16_06=[{w:null,t:"保管庫の前。ヤマト、谷の入口の道の方を指さす。"},{w:"hero",t:"ほら、こっちだ。車で行こうぜ。",v:"16_0178"},{w:null,t:"グリフォ、動かない。首を、谷の奥の山の方へ向けている。"},{w:null,t:"グリフォ、山の方へ歩きだす。"},{w:null,t:"ヤマト、グリフォの背中を見る。"},{w:"hero",t:"エリーも、山の向こうだ。ついてく。",v:"16_0182"},{w:null,t:"ヤマト、グリフォの方へ歩きだす。"},{w:null,t:"フォルンはヤマトの頭の上。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"……山越えか。",v:"16_0187"},{w:null,t:"アレク、ゴーグルを上げる。"},{w:"alek",t:"（ヤマトの背中に）……まあ、一体増えたしな。タダで。",v:"16_0189"},{w:null,t:"ヤマト、ふり向かない。"},{w:null,t:"指が、ひもをさがす。……白いカバンは、ない。"}];
GR_SC.g16_07=[{w:null,t:"その夜。山の中腹の、岩かげ。",v:"16_0195"},{w:null,t:"大きな岩が屋根のように張り出した下。"},{w:null,t:"まん中に、手のひらほどの折りたたみの加熱板。"},{w:null,t:"アレクが鍋をかきまぜている。"},{w:null,t:"グリフォは、少しはなれた岩の上で、体を丸くしている。目はあいている。"},{w:null,t:"ヤマトは、岩のはしで光の地図を広げて、印のあたりを指で大きくしたり小さくしたりしている。"},{w:null,t:"アレク、鍋の火を止める。"},{w:"alek",t:"ヤマト、ほら、ご飯、先——",v:"16_0202"},{w:"hero",f:"serious",t:"……しょっぱ。",v:"16_0207"},{w:"alek",t:"……しょっぱ。",v:"16_0209"},{w:"hero",t:"多めじゃん。ありがとな、アレク。",v:"16_0214"},{w:"hero",t:"（地図を開き直して、アレクを見ずに）……ロケットの金の話、まだ済んでねえからな。",v:"16_0216"}];
GR_SC.g16_08=[{w:null,t:"獅子門の丘の屋敷。",v:"16_0233"},{w:null,t:"屋敷の広い台所。"},{w:null,t:"はだしのエリーが、廊下から入ってくる。"},{w:null,t:"冷やす棚の明かりだけが、ついている。"},{w:null,t:"ヴィクターの手に、小さなプラスチックのカップ。"},{w:null,t:"カウンターの上に、角のすり切れた小さな単語帳が、開いたまま伏せてある。"},{w:null,t:"エリー、入口で止まる。ヴィクター、顔を上げない。"},{w:"victor",t:"眠れんのか。",v:"16_0240"},{w:"elly",f:"serious",t:"……のどが、かわいただけ。",v:"16_0241"},{w:null,t:"ヴィクター、冷やす棚から同じカップを一つ出して、エリーの方へすべらせる。"},{w:"victor",t:"……食わないのか。",v:"16_0243"},{w:"victor",t:"あした、扉の前に立て。",v:"16_0250"},{w:"elly",t:"扉の向こうも、読むだけで、いいんだよね。",v:"16_0251"},{w:"victor",t:"約束だ。",v:"16_0252"}];
GR_BT[16]={mid:[[{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:null,t:"アレク、レンズを一回たたく。"},{w:null,t:"ヤマト、一歩下がって、グリフォを見上げる。"},{w:null,t:"ヤマトの目が、その左の羽に止まる。"},{w:"hero",t:"フォルン、進化！",v:"16_0089"},{w:"alek",t:"クロッコ、進化！",v:"16_0090"},{w:"alek",t:"クロベク、柱から目ぇ離すな！",v:"16_0101"},{w:"hero",t:"フォルコン、まっすぐ撃て！",v:"16_0104"}],[{w:"alek",t:"クロベク、しっかりせえ！",v:"16_0111"},{w:null,t:"アレク、ゴーグルのレンズを見る。"},{w:"alek",t:"クロベク、二本目や！",v:"16_0114"},{w:null,t:"ヤマト、もう一度グリフォを見る。"},{w:"hero",t:"フォルコン、羽には撃つな。",v:"16_0120"},{w:null,t:"ヤマト、右手で、グリフォの右の、柱と柱のあいだを指す。"},{w:null,t:"ヤマト、指をそろえた右の手のひらを、まっすぐ立てる。"},{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"16_0130"}]],post:[{w:null,t:"同じ時、柱に押しつけられていたボロウルも、クロベクの二発目の突きで目を回す。"},{w:null,t:"フォルコンの光が引いてフォルンに戻る。"},{w:null,t:"アレク、グリフォの寄せたままの左の羽を見る。"},{w:"alek",t:"……右にしか、跳べへんかったんか。",v:"16_0135"}]};
GR_EP[16]={"t": "大理石の谷", "sc": [["g16_01", "屋敷・エリーの部屋（夜明け）", 0], ["g16_02", "谷の入口（夜明け）", 0], ["g16_03", "谷の奥（朝）", 0], ["g16_04", "保管庫（2Dアニメ）", 1], ["g16_05", "保管庫（勝負のあと・待つ）", 0], ["g16_06", "保管庫の外（昼）", 0], ["g16_07", "山の中腹の岩かげ（夜）", 0], ["g16_08", "屋敷の台所（夜中）", 0]]};
GR_SC.g17_01=[{w:null,t:"山の向こう。古い迷宮の、いちばん奥。",v:"17_0028"},{w:null,t:"天井の高い、円い石の部屋。"},{w:null,t:"部屋の左右に、太い柱が一本ずつ。"},{w:null,t:"いちばん奥の壁いっぱいに、大きな石の扉。"},{w:null,t:"扉のすきまから、寝息のような低い音。"},{w:null,t:"扉の前の高い段に、ヴィクター、カシア、エリー。"},{w:null,t:"段の下に、オレンジの輪のしるしの機械が一台。"},{w:null,t:"ヴィクター、ふり返って、エリーを見る。"},{w:"victor",t:"エリー。扉の字は読めるか。",v:"17_0036"},{w:null,t:"エリー、扉の字を指でなぞって、小声で読んでいく。"},{w:null,t:"ヴィクターの手首の画面に、その声の波形が流れる。"},{w:"elly",t:"うん。寝てる子のことが書いてある。",v:"17_0039"},{w:"elly",t:"あと、いちばん下に「起こさないで」って。",v:"17_0040"},{w:"victor",t:"いちばん下は、聞かなかったことにする。",v:"17_0041"},{w:"elly",t:"待って！　その子、寝てるのに！",v:"17_0044"},{w:"elly",f:"serious",t:"……読むだけだって、言った。",v:"17_0050"},{w:"victor",t:"読ませてやっただろう。",v:"17_0051"},{w:null,t:"第17話　迷宮",v:"17_0056"}];
GR_SC.g17_02=[{w:null,t:"昼前。がけの下に、古い石の門が口をあけていた。",v:"17_0062"},{w:null,t:"がけをくりぬいた石の門。"},{w:null,t:"門の中は、まっ暗。フォルンのしっぽの火が、入口の壁を照らす。"},{w:null,t:"グリフォ、迷わず右の道の前へ行って、座る。"},{w:"alek",t:"……右の道、行くで。",v:"17_0066"},{w:"hero",t:"お前の言う道なんか、行かねえよ。",v:"17_0067"},{w:null,t:"アレク、肩をすくめる。"},{w:null,t:"ヤマト、あごを上げて、グリフォの前を通りすぎる。"},{w:null,t:"アレク、入口の壁にもたれて、腕を組む。"},{w:null,t:"左の道の奥で、フォルンの火が小さくなっていく。"},{w:null,t:"……しばらくして。"},{w:null,t:"グリフォは、右の道の前に座ったまま。"},{w:null,t:"ヤマト、コケの顔を見て、止まる。"},{w:null,t:"アレク、腕をほどく。"},{w:null,t:"フォルン、ヤマトの頭の上から、しっぽでヤマトのおでこを、ぺしっ。"},{w:null,t:"ヤマト、耳まで赤くなって、右の道へずんずん入っていく。"},{w:null,t:"アレク、横を向いて、ゴーグルを指で一回はじく。"}];
GR_SC.g17_03=[{w:null,t:"細い石の通路。フォルンのしっぽの火の明かり。"},{w:null,t:"床が細い石の橋になって、下は暗い穴。"},{w:null,t:"ヤマトの頭の上のフォルンと、前を行くグリフォが、にらみ合う。"},{w:null,t:"足もとの石が、がらっと崩れる。"},{w:null,t:"フォルンがヤマトの頭から跳ぶ。"},{w:null,t:"ヤマトとアレクも、一人ずつ跳んでわたる。"},{w:null,t:"その先で、道が五つに分かれている。"},{w:"alek",t:"クロッコ、まんなか行くで。",v:"17_0088"},{w:null,t:"アレク、まんなかの道へ入る。"},{w:null,t:"ヤマト、足もとの砂を、靴でざっとけちらす。"},{w:null,t:"まんなかの道の入口。"},{w:null,t:"ヤマト、足を止める。"},{w:null,t:"ヤマト、立ち上がって、アレクのあとを追う。"},{w:null,t:"ヤマト、指についた石の粉を見る。ふかずに、そのまま手をにぎる。"},{w:null,t:"通路の出口。"}];
GR_SC.g17_04=[{w:null,t:"右はひびだらけで傾き、左は一本岩で、まわりの床も岩のまま。"},{w:null,t:"奥に、こじあけられた扉と台座。"},{w:null,t:"段の手すりに、胸に金の三日月の茶色いフクロウ、ルナウル（13話の夜の姿のまま）。"},{w:null,t:"回廊から広間へ、石の階段が下りている。"},{w:null,t:"台座の上で、ミノタスが半分目をあけている。"},{w:null,t:"台座の上で、ミノタスの足が、ぴくりと床を打つ。"},{w:null,t:"赤い光が、床の上をひとすじ走る。"},{w:null,t:"かげの小石は動かない。"}];
GR_SC.g17_10=[{w:null,t:"長い通路をぬけると、日はもう傾きはじめていた。",v:"17_0267"},{w:null,t:"奥の通路をぬけると、山の反対側の斜面。"},{w:null,t:"ヤマトとアレク、出口に並んで立って、息を切らしている。"},{w:null,t:"助手席の窓に、紺のドレスのそでが一瞬。"},{w:null,t:"分かれ道で、もう一台の黒い車が海の方へ曲がる。"},{w:null,t:"二台とも、すぐに木のかげに消える。"},{w:null,t:"ヤマト、木のかげに消えた道から、目を離さない。"},{w:null,t:"ヤマト、手首の光の地図を開く。"},{w:null,t:"アレク、横からヤマトの手首をつかむ。"},{w:null,t:"光る印は、オリーヴァ村の外れの、古い競技場の真下。"},{w:null,t:"アレク、ゴーグルを額に上げて、前髪を指で一回なでつける。"},{w:"alek",t:"村の真下か。……アナさん、おるやん。",v:"17_0279"},{w:null,t:"ヤマト、手首をふりほどいて、アレクの肩を一回どつく。"},{w:null,t:"二人、山を下りる道を歩きだす。"},{w:"alek",t:"……ほな、下りは歩きや。車代、なんぼする思てんねん。",v:"17_0282"},{w:null,t:"坂の下の道に、白いロボタクシーがすっと止まる。"},{w:null,t:"ヤマトの手首が、ぶっと鳴る。"},{w:null,t:"アレク、長いため息。"},{w:null,t:"ヤマト、先にフォルンを車に押しこむ。ふり返って、アレクの目を見る。"},{w:"hero",t:"サンキュ。あとで返す。",v:"17_0287"},{w:null,t:"アレク、返事のかわりに、ヤマトの頭を車の中へ押しこむ。"},{w:null,t:"ハンドルを握るヴィクターの、手首の画面。"},{w:null,t:"扉の字の写しと、エリーの声の波形。"},{w:null,t:"ヴィクターの指輪の指が、その行の上で止まる。"}];
GR_BT[17]={mid:[[{w:null,t:"ヴィクターの指輪の指が、段の手すりを、とん、とん。"},{w:null,t:"ヴィクター、回廊の階段を下りてくる二人に気づく。"},{w:"victor",t:"グリフォに案内させたか。",v:"17_0121"},{w:"hero",t:"（グリフォをあごでさして）こいつに聞けよ。",v:"17_0122"},{w:null,t:"ヤマトの目が、段の上のエリーで止まる。"},{w:"hero",t:"エリー！",v:"17_0124"},{w:"elly",t:"来ちゃだめ！　その子、起こされたばっかりなの！",v:"17_0126"},{w:"hero",t:"エリー置いて、帰れるかよ！",v:"17_0127"},{w:"victor",t:"用が済んだら、返してやる。",v:"17_0128"},{w:null,t:"エリー、段のふちへ一歩出る。ドレスのすそを、両手でにぎる。"},{w:null,t:"エリーの横に、カシア。"}],[{w:"hero",t:"おい、ピアスのおばさん！　そこどけ！",v:"17_0131"},{w:"kasia",t:"誰がおばさんよ。お姉さんと呼びなさい。",v:"17_0132"},{w:null,t:"カシア、エリーの横に立ったまま、まばたきもしない。"},{w:null,t:"ヤマト、段の下から、カシアをにらむ。"},{w:null,t:"エリー、ミノタスの方を向く。"},{w:null,t:"カシアがエリーの腕を取り、段の奥の通路の入口まで連れていく。"},{w:null,t:"アレク、足もとのクロッコの頭に手を置く。"},{w:null,t:"ヴィクター、手首の画面にふれる。"},{w:"kasia",t:"ルナウル。ここで止めて。",v:"17_0140"},{w:"hero",t:"（つばをのんで）……でけえ。",v:"17_0146"},{w:"hero",t:"フォルン、進化！",v:"17_0150"},{w:"alek",t:"クロッコ、進化！",v:"17_0152"}],[{w:null,t:"ヤマトの目が、グリフォと、うしろの一本岩の柱に止まる。"},{w:"alek",t:"クロベク、まだや！　気ぃ抜くな！",v:"17_0169"},{w:"hero",t:"フォルレオン、灼熱地獄！",v:"17_0172"},{w:null,t:"アレク、ヤマトの見ている先を追って、小さくうなずく。"},{w:"alek",t:"クロベク、足止めせえ！",v:"17_0179"},{w:null,t:"ヤマトとアレク、赤いふちの外へ。"},{w:null,t:"ヤマトの目：左の柱。"},{w:null,t:"アレクの目：同じ左の柱。"},{w:"hero",t:"左の柱！",v:"17_0192"},{w:null,t:"ヤマトの右手が、左の柱を指す。"},{w:null,t:"ヤマトとアレク、同時に左の手首をかざす。"},{w:"x",n:"二人",t:"フォルレオン、クロベク、融合！",v:"17_0200"},{w:"hero",t:"グレンカイザー！！",v:"17_0206"},{w:"alek",t:"……でかなったな、お前ら。",v:"17_0207"}],[{w:"hero",f:"surprised",t:"グリフォ、あのフクロウ、追っぱらえ！",v:"17_0221"},{w:null,t:"ヤマト、右手で、焦げた角の先を指さす。"},{w:"hero",t:"グレンカイザー、紅蓮竜顎（ぐれんアギト）！",v:"17_0226"},{w:null,t:"アレクの声が、同じ技の名前に重なる。"},{w:null,t:"アレク、床の焦げた角の先から、ヤマトへ目を移す。"},{w:"alek",t:"乾いた角の先やったら、火ぃ効くんやな。",v:"17_0233"},{w:null,t:"ヤマト、にっと笑う。"},{w:null,t:"カシア、通路の入口から指を一本。"},{w:null,t:"ヴィクター、手すりを、とん、とん。"},{w:"victor",t:"……立て。",v:"17_0241"},{w:null,t:"ヴィクター、笑顔のまま、命じるのをやめる。"},{w:"victor",t:"……もういい。見えた。",v:"17_0244"},{w:null,t:"ヴィクター、回廊の階段の下の二人を見る。"},{w:"victor",t:"この子は置いていく。",v:"17_0249"},{w:"victor",t:"カシア。港で待て。お客を待たせるな。",v:"17_0252"},{w:"kasia",t:"ええ。お先に。",v:"17_0253"}]],post:[]};
GR_EP[17]={"t": "迷宮", "sc": [["g17_01", "迷宮のいちばん奥の広間（朝）", 0], ["g17_02", "迷宮の入口（昼前）", 0], ["g17_03", "迷宮の通路（昼前）", 0], ["g17_04", "広間を見下ろす回廊（昼前）", 0], ["g17_05", "迷宮の奥の広間・勝負の頭", 1], ["g17_06", "勝負・押される", 1], ["g17_07", "勝負・左の柱", 1], ["g17_08", "勝負・角の先", 1], ["g17_09", "止める", 1], ["g17_10", "迷宮の裏の出口（昼すぎ）", 0]]};
GR_SC.g18_01=[{w:null,t:"その夜。二人は、ロボタクシーで村の外れの競技場に来ていた。",v:"18_0027"},{w:null,t:"月の下の競技場。"},{w:null,t:"細長い広場。"},{w:null,t:"ヤマト、柵の前で手首の光の地図を開く。"},{w:null,t:"うしろからアレク。"},{w:null,t:"アレク、手首の画面にふれる。"},{w:null,t:"「ヤマトに貸し　タクシー代（フォルンの席も）・豆のスープ　86ジェムコイン」。"},{w:null,t:"アレク、だまって、その数字をヤマトの顔の前に向ける。"},{w:null,t:"ヤマト、数字を見る。だまって、手で画面をよける。"},{w:null,t:"アレク、だまって、画面をまたヤマトの顔の前へ。"},{w:"hero",t:"タクシー、フォルンは膝の上だったぞ。",v:"18_0037"},{w:"alek",t:"膝の上も席や。",v:"18_0038"},{w:null,t:"フォルン、ヤマトの頭から、アレクの頭の上へ跳び移る。"},{w:null,t:"頭の上から、フォルンが前足で、アレクの画面をぺしっと閉じる。"},{w:null,t:"アレク、閉じた画面を見たまま、止まる。"},{w:"hero",t:"この真下だ。先に入って待とうぜ。",v:"18_0043"},{w:"alek",t:"お前にしたら、ちゃんと考えてるやん。",v:"18_0044"},{w:"ana",t:"ヤマト？　どうしたの、こんな時間に。",v:"18_0047"},{w:"hero",t:"アナさん。もうすぐ、エリーに会えるかもしれない。",v:"18_0048"},{w:"ana",t:"……ほんと？　どこで。",v:"18_0049"},{w:"hero",t:"言ったら来ちゃうだろ。あのスーツのおっさんも、たぶん来る。",v:"18_0050"},{w:"ana",t:"……分かった。この前の動画、ちゃんと見せてね。",v:"18_0052"},{w:"hero",t:"うん。会ったら、すぐ見せる。",v:"18_0053"},{w:"alek",t:"（横から画面に顔を寄せて）アナさん、おれもおりますんで。",v:"18_0054"}];
GR_SC.g18_02=[{w:null,t:"競技場の、真下。",v:"18_0059"},{w:null,t:"ひんやりした石の通路。"},{w:null,t:"通路は、扉の横の広い広間に出る。"},{w:null,t:"フォルン、水路から一歩はなれる。"},{w:null,t:"広間のつきあたりに、大きな石の扉。"},{w:null,t:"広間の右手に、上へ続く石の階段。"},{w:null,t:"ヤマト、扉と反対側の壁のくぼみを指さす。"},{w:null,t:"ヤマト、エリーの白い肩かけカバンを肩から下ろして、ひざの上に抱える。"},{w:null,t:"ヤマト、右の手首のリボンをほどいて、カバンの口に入れる。"},{w:null,t:"カバンのはしで、黄色いピリポンのぬいぐるみがゆれる。"},{w:null,t:"第18話　競技場の下",v:"18_0073"}];
GR_SC.g18_03=[{w:null,t:"あくる朝。オリーヴァ村へ下りていく道。",v:"18_0079"},{w:null,t:"丘の道。丸い目のライトの古い黒いスポーツカー。"},{w:null,t:"車の中。助手席にエリー。"},{w:null,t:"窓の外。坂の上のため池のまわりに、黒い車が三台。"},{w:null,t:"エリー、窓の外を見たまま。"},{w:"elly",t:"ヴィクターさん。扉の向こうにも、古い字はある？",v:"18_0084"},{w:null,t:"ヴィクター、前から目をはなさない。"},{w:"victor",t:"ある。寝てる子もな。",v:"18_0086"},{w:"victor",t:"起きたら、すぐチップを入れる。",v:"18_0087"},{w:null,t:"指輪の指が、ハンドルを、とん、とん。"},{w:"victor",t:"字を読め。それだけでいい。",v:"18_0089"},{w:null,t:"エリーの笑顔が、少しだけ止まる。"},{w:null,t:"窓の外。池のまわりのチップの子たち。"},{w:null,t:"エリー、ホテルの白い屋根が、窓のはしから消えていくのを見ている。"},{w:null,t:"車が、村の外れの競技場の前に止まる。"}];
GR_SC.g18_04=[{w:null,t:"右手の階段の上で、板がはずされる。"},{w:null,t:"ヴィクター、ゼノ、エリーが下りてくる。"},{w:null,t:"ヴィクターとゼノは、階段の下の岸に残る。"},{w:null,t:"エリー、ふり返る。"},{w:null,t:"エリー、その目を見ている。"},{w:null,t:"くぼみの中。"},{w:null,t:"天井から、ぽたん。"},{w:null,t:"エリー、手首の画面を扉の字に当てる。"},{w:null,t:"字が一つ光るたびに、扉の向こうで、低い寝息が少しずつ大きくなる。"},{w:null,t:"くぼみから、ヤマトが出る。"},{w:"hero",t:"エリー！",v:"18_0107"},{w:null,t:"エリー、ふり返る。目が大きくなる。"},{w:"victor",t:"続けろ、エリー。",v:"18_0115"},{w:"ana",n:"アナ（動画の中）",t:"エリー。ご飯、作って待ってるからね。",v:"18_0118"},{w:"ana",n:"アナ（動画の中）",t:"村の子たちも、みんな待ってるよ。",v:"18_0119"},{w:"ana",n:"アナ（動画の中）",t:"早く帰っておいで。",v:"18_0120"},{w:"victor",t:"開けろ。",v:"18_0128"},{w:"victor",t:"おまえの読みたい記録は、その向こうだ。",v:"18_0129"},{w:"elly",f:"serious",t:"……助けて。",v:"18_0140"},{w:"hero",t:"おう。",v:"18_0141"},{w:"victor",t:"……そうか。",v:"18_0145"},{w:"victor",t:"ゼノ。片づけておけ。",v:"18_0148"}];
GR_SC.g18_10=[{w:null,t:"ゼノ、階段を下りてきて、黙って水路の底に入り、ラッコンを抱え上げる。首のタオルで、ラッコンの顔の水をふく。"},{w:null,t:"ゼノ、一度だけ、こちらを見る。"},{w:"hero",t:"おい、ヒゲのおっさん。そいつ、休ませてやれよ。",v:"18_0237"},{w:"zeno",t:"……誰がヒゲだ。",v:"18_0238"},{w:null,t:"ゼノ、ラッコンを抱えて、階段を上がっていく。"},{w:null,t:"グレンカイザーの光がほどけて、フォルンとクロッコに戻る。"},{w:null,t:"グリフォ、扉のくぼみから出てきて、エリーの足もとに座る。エリーが、その頭に手を置く。"},{w:null,t:"ヤマト、くぼみに置いてきた白い肩かけカバンを取ってきて、エリーの前に出す。"},{w:"hero",t:"これ。あの夜、階段に落ちてたやつ。",v:"18_0243"},{w:null,t:"エリー、カバンを両手で受け取る。"},{w:null,t:"フォルン、カバンから白いシフォンのリボンをくわえ出して、エリーの手に落とす。"},{w:"elly",t:"わたしのカバン……ずっと持っててくれたの？",v:"18_0246"},{w:"hero",t:"フォルンが毎晩この上で寝るから、置いてけなかったんだよ。",v:"18_0247"},{w:null,t:"フォルンが跳んで、エリーの抱えたカバンの上に乗る。"},{w:null,t:"カバンの口から、光るシール帳と、光るお菓子帳の角がのぞいている。"},{w:null,t:"ヤマト、カバンに鼻がつくほど、フォルンに顔を近づける。"},{w:"hero",t:"な、フォルン。カバン番、えらかったな。",v:"18_0251"},{w:null,t:"フォルン、そっぽを向く。しっぽの火だけ、ぼっと燃え上がる。"},{w:"alek",t:"クロッコ、消してやれ。",v:"18_0254"},{w:"alek",t:"お前迎えに来たタクシー代、貸しにしといたで。",v:"18_0260"},{w:"elly",t:"なにそれ。わたし、乗ってないもん。",v:"18_0261"},{w:"hero",t:"それ、おれにも貸しにしてただろ。",v:"18_0262"},{w:"alek",t:"……ほな、半分ずつや。",v:"18_0263"},{w:"hero",t:"上はあいつらの道だ。来た道で出るぞ。",v:"18_0267"}];
GR_SC.g18_11=[{w:null,t:"その日の夕方。村のいちばん上の丘。",v:"18_0278"},{w:null,t:"夕日。丘の頂上の研究所あと。"},{w:null,t:"くぼみの中に、山のように大きな体が丸くなって眠っている。"},{w:null,t:"くぼみのふちに、ヴィクター。"},{w:null,t:"ゼノが、首にタオルをかけたまま、少しはなれて立っている。"},{w:null,t:"腕の中に、ぐったりしたラッコン。"},{w:null,t:"ヴィクター、ゼノの腕のラッコンを、一度だけ見る。"},{w:null,t:"ヴィクター、ラッコンの耳のうしろのチップに指を一本当てる。"},{w:"victor",t:"次に出すのは、おれが決める。",v:"18_0286"},{w:null,t:"ゼノ、だまってうなずく。"},{w:null,t:"ヴィクター、手首の画面を空中に開く。"},{w:null,t:"画面から、エリーの声が小さく流れる。"},{w:null,t:"ヴィクター、その行を指でなぞりながら、くぼみのふちを下りる。"},{w:null,t:"もう片方の指で、画面のオレンジの輪を押す。"},{w:"victor",t:"（古代ギリシャ語・字幕）起きろ。",v:"18_0292"},{w:null,t:"眠る巨体の首のチップが、強く光る。"},{w:null,t:"大きなまぶたが、ゆっくり開く。"},{w:null,t:"アトラードの目に、夕日が映る。"},{w:null,t:"【プロフィール】アトラード／光・地／赤い●／星の玉をかかげる石の巨人"}];
GR_BT[18]={mid:[[{w:null,t:"エリー、ヤマトの手を離して、水路から離れた古い石の台（大人の胸ほどの高さ）に上がる。"},{w:"x",n:"三人",t:"進化！",v:"18_0162"}],[{w:"alek",t:"クロベク、ふちから撃て！",v:"18_0168"},{w:null,t:"ゼノ、手首の画面にふれる。"}],[{w:null,t:"ヤマトの目が、ちかちかするチップに止まる。"},{w:null,t:"アレク、レンズのはしで、その手を見る。"},{w:"x",n:"二人",t:"フォルレオン、クロベク、融合！",v:"18_0194"},{w:"hero",t:"まだだ。岸まで下がって待て。",v:"18_0200"}],[{w:null,t:"エリーの目：扉のまわりの、厚く深くくぼんだ石。"},{w:"elly",t:"グリフォ、扉のくぼみ！",v:"18_0211"},{w:"hero",t:"グレンカイザー、ピリムサの前だ！　撃ち終わるまで動くな！",v:"18_0213"},{w:null,t:"ヤマト、その手を下ろして、ラクドリスを指さす。"},{w:"hero",t:"グレンカイザー、紅蓮竜顎（ぐれんアギト）！",v:"18_0224"},{w:null,t:"アレクの声が、同じ技の名前に重なる。"}]],post:[{w:null,t:"湯気が晴れる。ラクドリス、底にあおむけになって、目を回している。"},{w:null,t:"アレク、からになった水路の底を、あごでさす。"},{w:"alek",t:"水がのうなったら、火ぃ細ならへんのか。",v:"18_0229"},{w:null,t:"ヤマト、上げっぱなしだった腕を、ぶらぶらふる。"},{w:"hero",f:"serious",t:"……腕、しびれた。",v:"18_0231"}]};
GR_EP[18]={"t": "競技場の下", "sc": [["g18_01", "夜の古代の競技場（夜）", 0], ["g18_02", "競技場の下・地下の通路（夜ふけ）", 0], ["g18_03", "村へ下りる道・ヴィクターの車の中（朝）", 0], ["g18_04", "地下の扉の前（朝）", 0], ["g18_05", "勝負・頭", 1], ["g18_06", "勝負・チップの進化", 1], ["g18_07", "勝負・大波", 1], ["g18_08", "勝負・しのぐ", 1], ["g18_09", "勝負・決着", 1], ["g18_10", "勝負のあと・逃げる", 0], ["g18_11", "丘の上・研究所あと（夕方）", 0]]};
GR_SC.g19_01=[{w:null,t:"村はチップの子だらけ。三人は、日が暮れるまで地下で待った。",v:"19_0026"},{w:null,t:"その夜ふけ。裏の畑の道から、ホテルへ帰った。",v:"19_0027"},{w:null,t:"収穫のすんだ段々のぶどう畑。"},{w:null,t:"坂の上。ため池のまわりに、黒い車の小さな明かりが三つ。"},{w:null,t:"ホテルの白い壁。裏口の戸。"},{w:null,t:"アナ。2100年の作業着の上に、夜の見張りの上着。"},{w:null,t:"アナ、エリーを上から下まで、一回だけ見る。"},{w:null,t:"エリー、肩のカバンを、胸の前に抱える。"},{w:"elly",f:"serious",t:"……ただいま。",v:"19_0034"},{w:"ana",t:"おかえり。早く入って。",v:"19_0035"},{w:null,t:"第19話　空の寝床",v:"19_0037"}];
GR_SC.g19_02=[{w:null,t:"ホテルの台所。"},{w:null,t:"アナ、エリーをテーブルの前に座らせる。グリフォがエリーの足もとに横になって、すぐに目を閉じる。"},{w:"ana",t:"わたし、ヤニスさんと交代で池の見張りなの。",v:"19_0045"},{w:"ana",t:"スープ、鍋にあるから。温めてあげて。",v:"19_0046"},{w:"alek",t:"はい、やっときますわ。",v:"19_0047"},{w:null,t:"アナ、そう言ったまま、出ていかない。"},{w:null,t:"コンロの前。"},{w:null,t:"スープの皿が、エリーの前に置かれる。"},{w:null,t:"エリー、スプーンで一口。"},{w:null,t:"アナ、腕を組んだまま、それを見ている。"},{w:null,t:"エリー、スープを最後まで飲む。"},{w:null,t:"アレク、パーカーのそでで手をふいて、アナの前にも小皿を置く。"},{w:null,t:"アレク、鍋をのぞいて、自分の皿にお代わりをよそう。"},{w:"alek",t:"（ヴィクターの声色で）……お茶。",v:"19_0058"},{w:"ana",t:"朝まで寝てて。今夜は、みんなとロビーね。",v:"19_0062"},{w:"elly",f:"serious",t:"……ここ、まだちょっと痛いんだけど。",v:"19_0071"},{w:"hero",f:"sad",t:"悪かった。",v:"19_0072"},{w:"elly",t:"お姉ちゃんのジャムパン、一個で許してあげる。",v:"19_0073"},{w:"hero",f:"serious",t:"……二個やる。",v:"19_0074"},{w:"alek",t:"（皿を洗う手のまま）それ、アナさんのパンやん。",v:"19_0075"}];
GR_SC.g19_03=[{w:null,t:"東の空が、うっすら白くなりはじめたころ。",v:"19_0079"},{w:null,t:"薄暗いロビー。"},{w:null,t:"もう一つのソファで、エリー。"},{w:null,t:"枕もとのカバンに、黄色いピリポンのぬいぐるみとクッキーのチャーム。"},{w:null,t:"窓ガラスが、かたかたと小さく鳴る。"},{w:null,t:"エリーの手首の画面が鳴る。"},{w:"ana",t:"エリー、起きてる？　丘の上で、何か動いてる。",v:"19_0085"},{w:"ana",t:"あんたたちは、ホテルから出ないで。",v:"19_0086"},{w:null,t:"三人、窓にかけ寄る。"},{w:"elly",t:"お姉ちゃん、まだ池にいる！",v:"19_0090"},{w:"hero",t:"行くぞ！",v:"19_0091"},{w:"alek",t:"待て待て待て、出るな言われたやろ！",v:"19_0092"}];
GR_SC.g19_04=[{w:null,t:"三人が丘に駆け上がる。"},{w:null,t:"ヤマトが、大またでまたいで越える。"},{w:null,t:"くぼみの前に、巨体が立っている。"},{w:null,t:"その足もとに、ヴィクター。"},{w:null,t:"アトラードが、低く長い一声をあげる。"},{w:null,t:"ヴィクター、ゆっくり歩いて、くぼみのうしろの崩れた壁の上に上がる。"},{w:"ana",t:"（土手から、声をはり上げて）エリー！　出るなって言ったでしょ！",v:"19_0111"},{w:"hero",f:"serious",t:"……うわ。",v:"19_0115"},{w:"x",n:"三人",t:"進化！",v:"19_0119"},{w:"alek",t:"……冗談きついわ、ほんま。",v:"19_0127"},{w:"hero",t:"（小さく）……倍じゃねえか。",v:"19_0129"},{w:"victor",t:"ヴァンプロード。やれ。",v:"19_0133"}];
GR_SC.g19_08=[{w:null,t:"ヴィクター、崩れた壁の上で、手首の画面を空中に広げる。知らない国の人の顔が、いくつも並ぶ。"},{w:null,t:"倒れたピリポンを抱いたエリーが、流れる訳の字を見ている。"},{w:null,t:"ヴィクター、話を止める。画面の顔たちの返事を待つ。"},{w:null,t:"エリー、腕の中のピリポンの頭に、ほおを寄せる。"},{w:null,t:"ヴィクター、画面の顔たちに向かって、また話しだす（外国の言葉・字幕なし）。"},{w:null,t:"その声が始まると、アトラードの大きな顔が、ゆっくりヴィクターの方へ戻る。"},{w:null,t:"ヴィクター、話を終えて画面を閉じる。"},{w:"elly",f:"serious",t:"……わたしを、連れていかないの？",v:"19_0216"},{w:"victor",t:"起こし方は、もう読んでもらった。",v:"19_0217"},{w:null,t:"ヴィクター、指輪の指で、自分の手首の画面のふちを、とん、とん。"},{w:"victor",t:"見に来い。おまえの読んだ字の、使い道だ。",v:"19_0219"},{w:null,t:"エリー、ピリポンを抱く腕に、力が入る。目を伏せる。"},{w:null,t:"ヴィクターの手首の画面が、空中に字を一行だけ映す。"},{w:null,t:"石垣のきわのヤマト、ひざをついたまま、その字を見上げる。"},{w:null,t:"ヴィクター、坂を下りていく。"},{w:null,t:"ヴァンプロードが、羽のすそを引きずって、そのうしろを重い足音でついていく。"},{w:null,t:"池ぞいの道に、丸い目のライトの古い黒いスポーツカー。"},{w:null,t:"ヤマト、石の床に手をつく。"},{w:null,t:"ヤマト、ひざを立てる。"},{w:"hero",t:"おい、スーツのおっさん。……あさって、そこで待ってろ。",v:"19_0228"},{w:null,t:"ヴィクター、坂の途中でふり返る。笑顔のまま。"},{w:"victor",t:"……口を慎め、小僧。",v:"19_0230"},{w:null,t:"ヤマトの奥歯が、ぎりっと鳴る。"},{w:null,t:"ヴィクター、背を向けて、また坂を下りる。"},{w:null,t:"ヴィクター、自分で運転席に乗りこむ。"},{w:null,t:"ピリポンを抱いたエリー、ヤマトの背中を見上げる。"},{w:null,t:"カバンのひもを、指に一回、きつく巻く。"},{w:null,t:"ヤマト、倒れたフォルンの横に、またひざをつく。"},{w:null,t:"アトラード、くぼみの中に体を丸めて、横になる。長い寝息。"},{w:null,t:"池の向こうの土手から、アナが坂を駆け上がってくる。"},{w:null,t:"ヤマト、ひざをついたまま、倒れたフォルンを見ている。フォルンの左の前足が、小さくふるえている。"}];
GR_SC.g19_09=[{w:null,t:"ホテルのロビー。"},{w:null,t:"フォルンは窓のふちで、丘の上の巨体を見ている。"},{w:null,t:"ヤマト、窓のふちのフォルンの左の前足に、目をやる。"},{w:"hero",f:"serious",t:"……フォルンの足、医者に見せる。",v:"19_0245"},{w:null,t:"エリーが、ぬれたタオルを持ってくる。だまって、フォルンの左の前足に巻く。"},{w:null,t:"フォルン、よけない。"},{w:null,t:"ヤマト、しゃがんで、タオルを巻くエリーと目の高さをそろえる。"},{w:"hero",t:"ありがと、エリー。",v:"19_0249"},{w:null,t:"エリー、目を上げずに、結び目を結ぶ。"},{w:null,t:"フォルン、首をかしげて、エリーの顔をのぞきこむ。"},{w:"elly",t:"うん。下の動物病院、夜も開いてるよ。",v:"19_0252"},{w:null,t:"アレク、皿の焼いたオリーブを一つつまんで、かじる。"},{w:null,t:"ヤマト、残りをフォルンの方へ押す。"},{w:null,t:"足もとに、左の前足を浮かせたフォルン。"},{w:"alek",t:"（戸の札を見て、ヤマトの背中に）……医者代、だれが払うねん。",v:"19_0258"},{w:null,t:"ヤマト、ふり返らずに、戸をもう一回たたく。"}];
GR_SC.g19_10=[{w:null,t:"夜明け前。ロビーの明かりは、すみの小さな灯りだけ。"},{w:null,t:"ヤマト、ソファのはしに座っている。"},{w:null,t:"ヤマト、フォルンを両腕ですくい上げる。"},{w:"hero",t:"お前は、もう出なくていい。",v:"19_0268"},{w:null,t:"ヤマトの腕に、力が入る。"},{w:null,t:"フォルン、身をよじる。"},{w:null,t:"フォルン、床に下りる。"},{w:null,t:"ヤマトに背中を向けて、丸くなる。目を閉じる。"},{w:null,t:"ヤマトの腕は、抱えた形のまま、空っぽ。"},{w:null,t:"ヤマト、その腕をゆっくり下ろす。"},{w:null,t:"ヤマト、窓の外を見る。"},{w:null,t:"ヤマト、画面を閉じる。"},{w:null,t:"ヤマト、立ち上がる。"},{w:null,t:"ロビーの戸を、音を立てずに開けて、出ていく。"}];
GR_BT[19]={mid:[[{w:"hero",t:"フォルレオン、一回当てたら、すぐ下がれ！",v:"19_0137"},{w:"alek",t:"クロベク、池のふちに立て！",v:"19_0143"}],[{w:null,t:"エリー、ピリムサの背中を見る。"},{w:null,t:"エリー、左の手首の画面を、ピリムサへかざす。"},{w:"elly",t:"ピリムサ、進化！",v:"19_0156"},{w:"elly",t:"ナルカミ、かみなりおとし！",v:"19_0162"},{w:null,t:"ヤマト、もう手首の画面をかざしている。"},{w:null,t:"アレクの画面も、同じ時に上がっている。"},{w:"x",n:"二人",t:"フォルレオン、クロベク、融合！",v:"19_0167"},{w:"hero",t:"グレンカイザー、紅蓮竜顎（ぐれんアギト）！",v:"19_0169"}],[{w:"alek",t:"赤いとこから出ろ！",v:"19_0181"}]],post:[{w:null,t:"ナルカミだけ、走らない。"},{w:null,t:"聖地重圧。空をささえるような大きな力が、上から赤い床にのしかかる。"},{w:null,t:"重さが、すっと抜ける。"},{w:"alek",t:"……羽閉じられたら、何も通らへん。",v:"19_0199"}]};
GR_EP[19]={"t": "空の寝床", "sc": [["g19_01", "ホテルの裏口（夜ふけ）", 0], ["g19_02", "ホテルの台所（夜ふけ）", 0], ["g19_03", "ホテルのロビー（東が白むころ）", 0], ["g19_04", "丘の上・研究所あと（東が白むころ）", 0], ["g19_05", "勝負・全部出す", 1], ["g19_06", "勝負・ナルカミ", 1], ["g19_07", "勝負・つぶされる", 1], ["g19_08", "負けのあと（日の出前）", 0], ["g19_09", "オリーヴァ村（昼）", 0], ["g19_10", "ホテルのロビー（夜明け前）", 0]]};
GR_SC.g20_01=[{w:null,t:"オリーヴァ村。負けた次の日の、夜明け前。",v:"20_0029"},{w:null,t:"堰のすぐ横に、アトラードが座っている。大きな右手が、要石の上にのっている。"},{w:null,t:"堰の下から坂が始まる。"},{w:null,t:"池のまわりを、チップの子たちがぐるりと囲んでいる。目の奥に、オレンジの光。"},{w:null,t:"池のそばの道に、丸い目のライトの古い黒いスポーツカー。"}];
GR_SC.g20_02=[{w:null,t:"村の坂道。家々は暗い。"},{w:null,t:"ヤマトが一人で、坂道を歩いてくる。"},{w:null,t:"ヤマト、丘のすその、畑のあいだの細い道を回っていく。"},{w:null,t:"丘の向こうの、小さな石の家（2話のおばあさんの家）。"},{w:null,t:"ヤマト、戸の前で止まる。手を上げる。"},{w:null,t:"もう一回上げて、戸をたたく。"},{w:null,t:"戸が開く。おばあさん。"},{w:"hero",t:"おばあさん、研究所で働いてたんだろ。",v:"20_0045"},{w:"hero",t:"あのでっかいやつのこと、教えてくれ。",v:"20_0046"},{w:null,t:"おばあさん、少しのあいだ、ヤマトを見ている。それから、庭の長いすに座る。"},{w:null,t:"おばあさん、手首の画面に、古い動画を一つ出す。"},{w:null,t:"ヤマト、画面とおばあさんの顔を、一回ずつ見る。"},{w:null,t:"おばあさんは、だまってカップを口に運ぶ。"},{w:null,t:"ヤマト、丘の上の丸屋根を見る。それから、堰のそばの巨体がいる方を見る。"},{w:null,t:"ヤマト、立ち上がる。"},{w:null,t:"次の瞬間には、もう坂を駆け上がっている。"},{w:null,t:"おばあさん、カップを持ったまま、その背中を見ている。"},{w:null,t:"第20話　オリーヴァのため池",v:"20_0060"}];
GR_SC.g20_03=[{w:null,t:"食堂。エリーが、テーブルでパンをちぎっている。"},{w:null,t:"となりの席に、手つかずのパンの皿が一つ。"},{w:null,t:"アレクは窓ぎわで、古い望遠鏡のレンズを布でふいている。"},{w:null,t:"窓ぎわの日だまりで、フォルンが丸くなっている。"},{w:null,t:"アナが、焼きたてのパンのかごを運んでくる。"},{w:null,t:"窓ぎわのアレク、望遠鏡をふく手が止まる。"},{w:"alek",t:"（一段低い声で）実は僕、ぶどう畑を三つ持ってまして。",v:"20_0072"},{w:"alek",t:"（一段低い声で）お姉さん、僕とお茶しません？",v:"20_0073"},{w:null,t:"アナ、パンのかごをテーブルに置く。"},{w:"ana",t:"……どこの畑？",v:"20_0075"},{w:null,t:"アレク、前髪をなでつけた手のまま、止まる。"},{w:null,t:"足もとのクロッコは、あくびをして目を閉じる。"},{w:null,t:"アナ、エプロンのポケットから画面を出して、テーブルの上に表を広げる。"},{w:"ana",t:"見張りの順番、決めたから。アレクは、池の番か、ホテルの番ね。",v:"20_0079"},{w:"alek",t:"（声がもとに戻って）夜通しっすか。",v:"20_0080"},{w:"ana",t:"（表を見たまま）畑、三つあるんでしょ。一晩くらい、見張れるよね。",v:"20_0081"},{w:"alek",t:"……ホテルの番で、お願いします。",v:"20_0082"},{w:null,t:"アナ、もう次の表を開いている。"},{w:null,t:"食堂の入口に、ヤマトが立っている。肩をふるわせて、口を手でおさえている。"},{w:null,t:"アレク、手つかずの皿に、そっと手をのばす。"},{w:null,t:"その前に、ヤマトがパンを一つ取って、口に放りこむ。"},{w:null,t:"アレク、のばした手を引っこめる。"},{w:null,t:"ヤマトの目は、窓ぎわのフォルンの包帯に止まっている。"},{w:"hero",t:"医者代、ありがとな。",v:"20_0094"},{w:"alek",t:"（すぐ望遠鏡に目をもどして）分割でええで。",v:"20_0095"},{w:"hero",t:"分割って、何回に分けんだよ。",v:"20_0096"},{w:"alek",t:"おれが、ええって言うまでや。",v:"20_0097"},{w:"elly",t:"はい。貸しは、食べてから。",v:"20_0100"},{w:"elly",t:"ヤマト、朝早くから、どこ行ってたの？",v:"20_0101"},{w:"hero",t:"お前んちの、おばあさんとこ。",v:"20_0102"},{w:"elly",t:"おばあちゃんち？　なんで？",v:"20_0103"},{w:"hero",f:"serious",t:"……あとで言う。パン食ってから。",v:"20_0105"}];
GR_SC.g20_04=[{w:null,t:"坂の途中のテラス。"},{w:null,t:"フォルンは、テラスのはしの植木鉢の横。"},{w:null,t:"アナが、空中の画面をいくつも開いたまま、テラスに出てくる。"},{w:null,t:"アナ、ヤマトの見ている先に、目をやる。"},{w:null,t:"アナ、画面の地図の、坂の下の家々に、青い印を一つずつ置いていく。"},{w:null,t:"アナの地図。"},{w:null,t:"ヤマト、坂の下の村の屋根を見る。"},{w:null,t:"アナ、画面の表を一つ閉じる。"}];
GR_SC.g20_05=[{w:null,t:"ホテルの裏。"},{w:null,t:"フォルンは、ヤマトから二歩はなれた石の上。"},{w:null,t:"ヤマト、土に棒で描く。口を開けた顔と、大きな頭。"},{w:null,t:"口を、×で消す。"},{w:"elly",t:"ねえ、おばあちゃん、なんて？",v:"20_0122"},{w:"hero",t:"おばあさんは、なんも言わねえ。",v:"20_0123"},{w:null,t:"ヤマト、棒の先で小さい顔をつつく。それから、エリーを指さす。"},{w:"hero",t:"あいつ、スーツのおっさんが黙ったら、お前の方、向いた。",v:"20_0125"},{w:"elly",t:"（自分を指さして）……わたし？",v:"20_0126"},{w:null,t:"ヤマト、うなずく。"},{w:"alek",t:"で、あのコウモリ、だれが押さえんねん。おれは嫌やで。",v:"20_0128"},{w:null,t:"ヤマトの目が、二歩先のフォルンの背中に行く。"},{w:null,t:"ヤマト、目をもどす。"},{w:"hero",t:"融合で行く。おれとお前だ。",v:"20_0131"},{w:"alek",t:"……結局、おれも入ってるやん。",v:"20_0132"},{w:null,t:"アレク、パーカーのひもを両方、きゅっと引く。"},{w:null,t:"フォルンの耳が、ぴくりと動く。"},{w:"alek",t:"でかい方は、どないすんねん。三体で撃ったら止まるやろ。",v:"20_0135"},{w:"elly",t:"だめ。",v:"20_0136"},{w:null,t:"ヤマトとアレク、エリーを見る。"},{w:"elly",t:"あの子だけは、だれも撃たないで。",v:"20_0138"},{w:null,t:"アレク、パーカーのひもをにぎったまま、口をとがらす。"},{w:"hero",t:"撃たねえよ。",v:"20_0140"},{w:"alek",t:"撃たんと、どないして止めんねん。",v:"20_0141"},{w:"elly",t:"わたしが、あの子のそばまで行く。",v:"20_0142"},{w:"alek",t:"それ、作戦ちゃうやろ。",v:"20_0143"},{w:null,t:"ヤマト、アレクを見ない。"},{w:"hero",t:"やばくなったら、すぐ戻れよ。",v:"20_0145"},{w:"elly",t:"うん。",v:"20_0146"},{w:null,t:"アレク、にぎっていたパーカーのひもを、だまって離す。"},{w:null,t:"エリーの目は、もう堰の方。"},{w:null,t:"エリーの手首の画面が鳴る。"},{w:"ana",t:"エリー、池に来て。チップの子たちが、みんなを追い出してる。",v:"20_0150"},{w:null,t:"三人が立ち上がる。"},{w:"elly",t:"グリフォは、ここにいて。ホテルをお願い。",v:"20_0152"},{w:null,t:"グリフォ、ホテルの裏口の前に座る。"},{w:"alek",t:"グリフォ、番、代わってな。",v:"20_0154"},{w:null,t:"グリフォ、アレクの顔を見て、そっぽを向く。"}];
GR_SC.g20_06=[{w:null,t:"夜のため池。"},{w:null,t:"池の左の土手。"},{w:null,t:"坂の上の古いスポーツカー。"},{w:null,t:"チップの子たちのあいだから、雷の子が一体、前に出る。"},{w:null,t:"【プロフィール】トールジン／雷／●●○／火花をまとう雷の子"},{w:null,t:"トールジン、水ぎわの石に片足をのせる。"},{w:null,t:"池のまん中に浮いた水鳥の子は、顔も上げない。"},{w:null,t:"三人が、土手のはしに駆けつける。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:null,t:"ヤマトは、村の人たちの横、土手のはしに立つ。"},{w:null,t:"フォルンは、うしろの暗いオリーブの木の下で止まっている。"},{w:null,t:"ヤマトに背中を向けたまま。"},{w:null,t:"クロッコだけが、池に入る。"},{w:null,t:"エリーとアレク、手首の画面をかざす。"},{w:"x",n:"二人",t:"進化！",v:"20_0181"},{w:null,t:"その場で約3秒。"},{w:null,t:"光っている間は、二体とも動かない。"}];
GR_SC.g20_10=[{w:null,t:"クロコディロス、へりの水に首を下ろす。"},{w:null,t:"光が引いて、クロッコに戻る。"},{w:null,t:"ナルカミも光が引いて、ピリポンに戻る。"},{w:null,t:"しぶきでずぶぬれのアレクが、パーカーのすそをしぼる。"},{w:null,t:"ヤニスが、熱を通さない銀色のシートを、アレクの頭にばさっとかける。"},{w:"alek",t:"（シートの下から、すそをしぼったまま）……このパーカー、一枚しかないねんで。",v:"20_0294"},{w:null,t:"エリー、ほっとして笑う。"},{w:null,t:"ヤマト、アレクの背中をばしばしたたく。"},{w:null,t:"アナが、クロッコの頭を両手でわしわしなでる。クロッコ、目を細める。"},{w:null,t:"土手のはしの、暗いオリーブの木の下。"},{w:null,t:"ヤマト、フォルンの背中を見る。"}];
GR_SC.g20_11=[{w:null,t:"東の空の下のふちが、ほんの少しだけ白みはじめる。"},{w:null,t:"坂の下の家々は、明かりが一つもない。"},{w:null,t:"空のあちこちに、小さな明かりが一つ、また一つ。"},{w:null,t:"堰のそば。要石の上の大きな指が、一本ずつ曲がる。"},{w:null,t:"ホテルの裏口の前で、グリフォが顔を上げる。"}];
GR_BT[20]={mid:[[{w:"alek",t:"クロベク！",v:"20_0197"}],[{w:null,t:"アレク、土手の奥から駆けだす。"},{w:"alek",t:"クロベク！　上がってこいや！",v:"20_0207"},{w:null,t:"アレク、へりで、パーカーのすそに手をかける。"},{w:null,t:"ヤマト、もう走りだしている。"},{w:null,t:"ヤマト、すそをつかんだアレクの手を、上から押さえる。"},{w:null,t:"ヤマト、ロープの端に、へりの石を一つ、固く結ぶ。"},{w:"hero",t:"持ってろ。お前は、呼べ。",v:"20_0216"},{w:"elly",t:"ナルカミ、その子、止めて！",v:"20_0220"},{w:"alek",t:"……クロベク！",v:"20_0223"},{w:"alek",t:"クロベク、進化！",v:"20_0235"}],[{w:null,t:"ヤマト、へりで、水ぎわと池のまん中を見くらべる。"},{w:null,t:"ヤマト、池のまん中を指さして、アレクを見る。"},{w:null,t:"アレク、額のゴーグルを下ろす。"},{w:"alek",t:"クロコディロス、まん中や！",v:"20_0250"},{w:"alek",t:"クロコディロス、押し返せ！",v:"20_0262"},{w:"hero",t:"（アレクに）……まん中だと、雷、細くなってた。",v:"20_0276"}],[{w:"hero",t:"ありがとな、クロコディロス。",v:"20_0281"},{w:"alek",t:"……おれの手ぇには、なんもなしかい。",v:"20_0283"},{w:"hero",t:"水、かけただろ。",v:"20_0284"},{w:"alek",t:"その水筒、おれのやん。",v:"20_0285"},{w:null,t:"アレク、自分の腰のロープを、ほどきにかかる。"}]],post:[]};
GR_EP[20]={"t": "オリーヴァのため池", "sc": [["g20_01", "オリーヴァ村の引き（夜明け前）", 0], ["g20_02", "村の坂道〜おばあさんの家（夜明け前）", 0], ["g20_03", "ホテルの食堂（朝）", 0], ["g20_04", "アナのホテルのテラス（朝）", 0], ["g20_05", "ホテルの裏のぶどう畑（夜）", 0], ["g20_06", "ため池の土手（夜）・頭", 0], ["g20_07", "土手の上の勝負・押される", 1], ["g20_08", "池のへり・初めてかむ", 1], ["g20_09", "まん中で受ける・決着", 1], ["g20_10", "勝負のあと（夜ふけ）", 0], ["g20_11", "ため池の上の丘（夜明け前）", 0]]};
GR_SC.g21_01=[{w:null,t:"夜明けまで、あと少し。",v:"21_0029"},{w:null,t:"東の空のふちが、白みはじめている。"},{w:null,t:"アレクが戸口で、パーカーのフードをかぶりながら、ヤマトの腕を引っぱっている。"},{w:"alek",t:"急げや！　もう見物のドローンが来てるで！",v:"21_0032"},{w:null,t:"ヤマトは、寝ていない顔。"},{w:null,t:"フォルン、ヤマトに背中を向けて、しっぽを体に巻いている。"},{w:null,t:"エリーが、裏口へ走りながら、ジャムをぬったパンをヤマトの手に押しこむ。"},{w:"elly",t:"ほら、ご飯、先。走りながらでいいから。",v:"21_0036"},{w:"hero",f:"serious",t:"……今？",v:"21_0037"},{w:"elly",t:"今。",v:"21_0038"},{w:null,t:"ヤマト、走りながら、パンを二口で食べる。口のはしに、ぶどうのジャム。"},{w:"alek",t:"待て待て、それ、おれの分のジャムやろ！",v:"21_0040"}];
GR_SC.g21_02=[{w:null,t:"ため池より高いオリーブ畑の段。"},{w:null,t:"坂の下の家々は、明かりが一つもない。"},{w:null,t:"三人が、段の下の道を、堰の方へ上がっていく。"},{w:null,t:"エリー、アレクのパーカーのそでを、指でつまむ。"},{w:"elly",t:"アレク、それ、まだ乾いてないでしょ。",v:"21_0051"},{w:"alek",t:"……一枚しかないねん。",v:"21_0052"},{w:null,t:"アレク、そでを引っこめる。"},{w:"elly",t:"お姉ちゃん、下のみんなは？",v:"21_0054"},{w:"ana",t:"夜のうちに、みんな上に来た。",v:"21_0055"},{w:null,t:"アナの手首の画面。送り主の丸い写真に、エリーとおばあさんが並んで笑っている。"},{w:"elly",f:"serious",t:"……行ってくるね。",v:"21_0061"},{w:"ana",t:"うん。",v:"21_0062"}];
GR_SC.g21_03=[{w:null,t:"堰の頭の要石。"},{w:null,t:"堰の手前の、古い石だたみの広場。"},{w:null,t:"石段のわきに、丸い目のライトの古い黒いスポーツカーが止まっている。"},{w:null,t:"石段の下に、ヴァンプロード。"},{w:null,t:"石段のはしに、カシア。"},{w:null,t:"カシアの手首の画面から、空中にお客の顔の画面をいくつも開いている。"},{w:null,t:"堰のはしに、ゼノ。"},{w:null,t:"まわりに、チップの子たち。"},{w:null,t:"三人が、広場の入口に立つ。"},{w:"hero",t:"（石段のはしを見て）ピアスのおばさんも、いんのかよ。",v:"21_0076"},{w:"kasia",t:"（画面から目を上げずに）誰がおばさんよ。何回言わせるの。",v:"21_0077"},{w:null,t:"アレクの足もとから、クロッコが池へすべりこむ。"},{w:"victor",t:"遅かったな。",v:"21_0079"},{w:null,t:"ヴィクター、空のドローンへ向かって、お客の国の言葉で話す（字幕）。"},{w:"victor",t:"（お客の国の言葉・字幕）あの石を、持ち上げてご覧に入れます。",v:"21_0081"},{w:null,t:"第21話　夜明けの決戦",v:"21_0083"}];
GR_SC.g21_04=[{w:null,t:"ヴィクター、指輪の指で、石段の手すりを、とん、とん。"},{w:null,t:"ヴィクターが古代ギリシャ語で一言。"},{w:null,t:"アトラード、要石に両手をかけ、ゆっくり持ち上げる。"},{w:null,t:"ヴィクター、見上げたまま、とん、とん。"},{w:null,t:"少しして、また。"},{w:null,t:"エリー、一歩前に出る。"},{w:null,t:"エリー、だまって、アトラードの方へ歩きだす。"},{w:null,t:"ヴィクター、エリーを見る。笑顔。"},{w:"victor",t:"……好きにすればいい。",v:"21_0099"},{w:"victor",t:"こいつに、おまえの声は届かん。",v:"21_0100"},{w:null,t:"ヴィクター、ヴァンプロードに目だけやる。自分の耳を、指輪の指で、とん、とん。"},{w:"victor",t:"聞け。",v:"21_0102"},{w:null,t:"ヴァンプロードの頭の、大きな二つの耳が、ゆっくりヤマトの方を向く。"},{w:null,t:"ヴィクターは、もうアトラードを見上げている。"},{w:null,t:"ヴァンプロード、石だたみの広場のまん中まで歩いて、止まる。"},{w:null,t:"東の空が白くなる。ヴァンプロード、目を細めて、顔をそむける。"},{w:null,t:"頭の上の二つの耳だけが、大きく開く。"},{w:null,t:"チップの子たちが、エリーとアトラードのあいだに並んで、道をふさぐ。"},{w:null,t:"エリーの足が、チップの子たちの前で止まる。"}];
GR_SC.g21_12=[{w:null,t:"日が昇る。座りこんだアトラードの足もとで、エリーがグリフォの頭に手を置いている。"},{w:null,t:"堰の上のヤマト、手すりに両手をつく。"},{w:"hero",t:"エリー、さっきの。",v:"21_0277"},{w:"elly",t:"（見上げて）なに？",v:"21_0278"},{w:null,t:"ヤマト、エリーの目を、まっすぐ見る。"},{w:"hero",t:"ありがとな！",v:"21_0280"},{w:null,t:"エリー、目をぱちぱちさせる。それから、ヤマトの口もとを見て、ぱっと指さす。"},{w:"elly",t:"（下から）ヤマトー！　口、ジャムついてるー！",v:"21_0282"},{w:null,t:"堰の上のヤマト、手の甲で口をこする。"},{w:null,t:"となりのアレク、ふきだしかけて、顔をそむける。"},{w:null,t:"石段の上で、ヴィクター。もう笑顔に戻っている。"},{w:"x",n:"お客の声",t:"（字幕）……言葉一つで、じゃなかったのか。",v:"21_0288"},{w:"hero",t:"アレク。分割の、一回目。",v:"21_0295"},{w:"alek",t:"……一個かい。",v:"21_0297"}];
GR_BT[21]={mid:[[{w:null,t:"ヤマト、手首の画面を上げる。"},{w:null,t:"ヤマト、フォルンの背中を見る。それから、手首の画面をかざす。"},{w:"x",n:"三人",t:"進化！",v:"21_0117"},{w:null,t:"ヤマト、フォルレオンの背中へ、指をそろえた右の手のひらを立てる。"},{w:null,t:"ヤマト、手を下ろす。"},{w:"hero",t:"アレク、エリー。行くぞ。",v:"21_0126"},{w:"alek",t:"言われんでも行くわ。早よ終わらそ。",v:"21_0127"},{w:"elly",t:"ナルカミ、道をあけて！",v:"21_0128"},{w:null,t:"アレク、だまって堰のはしまで出る。"},{w:"alek",t:"（ゴーグルごしに、石段のはしのカシアへ）あん時の輪っか、利子つけて返したるで。",v:"21_0139"}],[{w:null,t:"ヤマトとアレク、堰の上のはしに立つ。"},{w:"hero",t:"フォルレオン、右から回れ！",v:"21_0145"},{w:"hero",t:"跳べ！　上からだ！",v:"21_0149"},{w:"hero",t:"フォルレオン、灼熱地獄！",v:"21_0152"},{w:null,t:"ヤマト、ヴィクターの口を見る。"},{w:"alek",t:"クロコディロス、上や！　かめ！",v:"21_0167"},{w:null,t:"カシア、ヨルフクを片手で拾い上げる。"},{w:null,t:"カシアのまわりの、お客の顔の画面。"},{w:null,t:"カシア、自分の手首の画面を閉じる。"},{w:"kasia",t:"ヴィクターさま。お客さまには、わたしから謝っておきます。",v:"21_0175"}],[{w:null,t:"ヤマト、肩で息をしている。"},{w:null,t:"ヤマト、一歩、前へ出る。"},{w:"hero",t:"フォル——",v:"21_0189"},{w:null,t:"ヤマト、口を閉じる。"},{w:"hero",t:"アレク！",v:"21_0194"},{w:"hero",f:"serious",t:"……行け、フォルン。",v:"21_0211"}],[{w:"victor",t:"右だ！",v:"21_0223"},{w:"victor",t:"下がれ！　羽を閉じろ！",v:"21_0225"},{w:null,t:"ヴィクターの口が、勝負の方を向いている。"},{w:null,t:"ヤマトは、手を下ろしたまま。"},{w:"elly",t:"（古代ギリシャ語・字幕）お願い。そっと、もどして。",v:"21_0234"},{w:null,t:"ヴィクター、ふり返る。"},{w:null,t:"ヴィクターの顔から、笑顔が消える。"},{w:"victor",t:"（古代ギリシャ語・字幕）持ち上げろ！",v:"21_0243"},{w:"victor",t:"ゼノ！　狐を止めろ！",v:"21_0249"},{w:null,t:"ヴィクター、ゼノから目をはなす。"},{w:null,t:"ヤマト、口を閉じたまま。"},{w:"hero",t:"灼熱地獄！！",v:"21_0256"}]],post:[{w:null,t:"ヴァンプロード、石だたみの上にどさりと倒れる。目を回している。"},{w:null,t:"首のうしろのチップに、ぴしっとひびが走る。"},{w:null,t:"フォルレオン、倒れたヴァンプロードの前で、肩で大きく息をしている。"},{w:"hero",f:"smile",t:"……へへっ。やったな、フォルン。",v:"21_0264"},{w:"alek",t:"（ヤマトの肩を小突いて）……耳、お前の声の方しか向いてへんかった。",v:"21_0267"}]};
GR_EP[21]={"t": "夜明けの決戦", "sc": [["g21_01", "アナのホテルの台所から裏口へ（夜明け前）", 0], ["g21_02", "坂の上のオリーブ畑（夜明け前）", 0], ["g21_03", "堰の前（夜明け前）", 0], ["g21_04", "持っていろ", 0], ["g21_05", "勝負・頭", 1], ["g21_06", "勝負・読まれる", 1], ["g21_07", "アレクとカシア", 1], ["g21_08", "手を開く", 1], ["g21_09", "読めない", 1], ["g21_10", "お願い", 1], ["g21_11", "決着", 1], ["g21_12", "日が昇る", 0]]};
GR_SC.g22_01=[{w:null,t:"運河の町、コリンタ。",v:"22_0026"},{w:null,t:"ヤマトの上着とズボンが、けさの勝負の土ぼこりで、まだ白い。"},{w:null,t:"橋のたもとの机。"},{w:null,t:"白いロボタクシーが止まる。"},{w:"alek",t:"ここ、ヴィクターんとこの机やん。",v:"22_0031"},{w:null,t:"ヤマト、名札の机を一回見る。"},{w:null,t:"ヤマト、机の前に立つ。"},{w:null,t:"かけらを、机の上に、ばらばらと置く。"},{w:"hero",t:"おい、名札。これ。",v:"22_0035"},{w:"nomos",t:"机に物を置くのは、禁止です。",v:"22_0037"},{w:"nomos",t:"……決まりですから。",v:"22_0042"},{w:null,t:"第22話　オリーブの坂",v:"22_0047"}];
GR_SC.g22_02=[{w:null,t:"ホテルのロビーの空中の画面に、ニュースの字幕。"},{w:null,t:"「外国のお客　あの会社との話を取りやめ」。"},{w:null,t:"丘の上。寝床で眠るアトラードの足もとに、白いテーブルと椅子が一つ。"},{w:null,t:"テーブルのはしに、角のすり切れた古い単語帳。"},{w:null,t:"少しうしろに、ゼノ。"},{w:null,t:"ヴィクターのまわりに、空中の画面が一つも浮いていない。"},{w:null,t:"三人が丘を上がってくる。"},{w:null,t:"ヴィクター、カップを置かない。三人を見て、笑顔。"},{w:null,t:"ゼノが、手首の画面を開く。"},{w:null,t:"ゼノ、画面に目を落としたまま、いちばん下の印を、指で長く押す。"},{w:null,t:"チップの子たちが、まばたきをする。"},{w:null,t:"池のそば。伏せていたヴァンプロードが、ゆっくり首を上げる。"},{w:null,t:"ヴィクター、紅茶を一口飲む。"},{w:null,t:"ゼノ、胸のオレンジの輪の胸章に指をかけて、外す。"},{w:"zeno",t:"仕事は、ここまでだ。",v:"22_0069"},{w:null,t:"ヴィクター、胸章を見て、ゼノの顔を見る。"},{w:null,t:"うしろの手下たちが、顔を見合わせる。"},{w:null,t:"手下たち、ばらばらの方へ坂を下りていく。"},{w:null,t:"ヴィクター、立ち上がる。"},{w:null,t:"ヴィクター、歩きだす。"},{w:null,t:"ヴィクター、エリーを見る。客に向けた笑顔ではない。"},{w:"victor",t:"才能があるな。",v:"22_0076"},{w:null,t:"エリーは、笑わない。"},{w:null,t:"ヴィクター、歩きだす。"},{w:null,t:"ヤマトの肩のフォルンが、青い濃紺のスーツをにらんで、のどの奥で低くうなる。"},{w:null,t:"ヴィクター、フォルンを一度だけ見る。"},{w:null,t:"池のそば。ヴァンプロードが目をあけて、坂を下りていく青い濃紺のスーツを見る。"},{w:null,t:"丘の上の寝床。アトラードが、ゆっくり目をあける。"},{w:null,t:"丘の上のテーブル。"},{w:null,t:"テーブルのはしの古い単語帳も、そのまま。"},{w:null,t:"道ばたに、丸い目のライトの古い黒いスポーツカーが、置かれたまま。"}];
GR_SC.g22_03=[{w:null,t:"坂の曲がり角。"},{w:null,t:"ヴィクター、その前で止まる。"},{w:null,t:"ヴィクターの指輪の指が、そばの石を、とん、と一回。"},{w:null,t:"アトラード、片目だけあける。"},{w:null,t:"……目を閉じる。"},{w:null,t:"ヴィクター、その前で、立ちつくす。二回目の「とん」は、来ない。"},{w:null,t:"ヴィクター、その手を見る。"},{w:null,t:"ヴィクター、指輪を外す。"},{w:null,t:"ヴィクターの手が、胸ポケットにふれる。"},{w:null,t:"エリーは、オリーブの幹に手をついて、見ている。"},{w:null,t:"画面の字「国へのお知らせ：だまって国の外へ出す　テリオンの荷　受けつけました」。"},{w:null,t:"かけらの横に、子どもの絵の写真立てが、立っている。"},{w:null,t:"坂の下から、黒い車が一台、静かに上がってきて止まる。"},{w:null,t:"車から、紺の制服の人が三人降りる。"},{w:null,t:"一人が、ヴィクターの前に立つ。手首の画面を、だまって見せる。"},{w:null,t:"その横に、割れたチップのかけらの写真。"},{w:null,t:"その下に、知らせた人の名前の欄。"},{w:null,t:"ヴィクター、画面を見る。笑顔のまま。"},{w:null,t:"ヴィクター、輪がかかる前に、上着の前のボタンを一つ留める。"},{w:null,t:"自分から両手を前に出す。"},{w:null,t:"その手首に、光る輪がかかる。"},{w:null,t:"ヴィクター、制服の人にはさまれて、黒い車に乗る。"},{w:null,t:"黒い車が、坂を下りていく。"},{w:null,t:"上着の前のボタンは、留めたまま。"}];
GR_SC.g22_04=[{w:null,t:"ヤニスの畑。"},{w:"x",n:"村の男の子",t:"……どけ。",v:"22_0127"},{w:"x",n:"村の女の子",t:"やだ。",v:"22_0128"},{w:null,t:"二人、笑って、畑の中へ走って逃げていく。"},{w:null,t:"ヤニス、顔も上げずに、麦をまきつづける。"},{w:null,t:"アナのホテル。"},{w:null,t:"丸くなって眠っている。"},{w:null,t:"6話の森の村。"},{w:null,t:"赤紫の長い髪の女。"},{w:null,t:"ニーナとマルコ。だまって、苗を土に置いている。"},{w:null,t:"丘の上の寝床。"},{w:null,t:"チップの光の消えた子が二、三体、同じ方を向いて聞いている。"},{w:"x",n:"係の人",t:"相棒の登録ですね。お名前を、どうぞ。",v:"22_0142"},{w:"ana",t:"アナです。世話も旅も、この子です。",v:"22_0143"},{w:"x",n:"係の人",t:"では、どうぞ。",v:"22_0145"},{w:"elly",t:"ねえ、いま、わたし見て決めたよね？",v:"22_0148"},{w:"ana",t:"早っ。フォルンなんて、わたしの板、しっぽではらったのにね。",v:"22_0149"},{w:"hero",t:"（書きながら）フォルンは、しっぽで返事すんだよ。",v:"22_0151"},{w:"alek",t:"（長いすから）クロッコ、消してやれ。",v:"22_0154"},{w:"ana",t:"エリー、ごはんの量、ここに書いといて。",v:"22_0158"}];
GR_SC.g22_06=[{w:null,t:"空港の待合。"},{w:null,t:"アレク、ヤマトの横に並ぶ。"},{w:"alek",t:"……最初から、目ぇつぶらせてたんか。",v:"22_0220"},{w:null,t:"ヤマト、前を向いたまま、手のひらをひらりと見せる。"},{w:null,t:"アレク、その手のひらを指でぴんとはじいて、アナたちの方へ下がる。"},{w:null,t:"案内の声。「中国行き、ご搭乗を開始します」。"},{w:null,t:"バジリクが、レンのうしろをのそのそついていく。"},{w:null,t:"搭乗口の手前。"},{w:null,t:"レン、顔だけ半分ふり向く。"},{w:null,t:"レンとバジリク、そのまま搭乗口へ入っていく。"},{w:null,t:"ヤマト、待合のいすにどさっと座る。"},{w:null,t:"肩のフォルン、前足をのばして、ピリポンの鼻にちょん。"},{w:null,t:"ピリポン、エリーの髪の中へ引っこむ。……そっと顔を出す。"},{w:null,t:"前足をのばして、フォルンの耳にちょん。フォルンの耳が、ぴくぴく。"},{w:null,t:"エリー、二匹を見て、ふきだす。"},{w:null,t:"アナに呼ばれて、エリーが立つ。"},{w:null,t:"少しはなれた所に、アナ。"},{w:"ana",t:"どうせ行くんでしょ。ご飯、ちゃんと食べるんだよ。",v:"22_0236"},{w:"elly",t:"お姉ちゃんもね。",v:"22_0237"},{w:"alek",t:"（横から）アナさん、おれの分は？",v:"22_0238"},{w:null,t:"アナ、エリーの前髪を、指で直す。"},{w:null,t:"ヤマト、アナに片手を上げる。"}];
GR_SC.g22_07=[{w:null,t:"空港の屋上。"},{w:null,t:"手すりの前に、ヤマト。"},{w:null,t:"見送りの場所の係の女の人が、手すりの前を回ってくる。"},{w:"alek",t:"（一段低い声で）実は僕、白い都に家が三軒ありまして。",v:"22_0249"},{w:"alek",t:"（一段低い声で）お姉さん、案内しましょか？",v:"22_0250"},{w:null,t:"エリーの髪の中から、ピリポンが顔を出す。"},{w:null,t:"アレクの青い髪が、ふわっと逆立つ。"},{w:null,t:"ヤマト、手首の画面を開く。"},{w:null,t:"ヤマト、打つ。"},{w:null,t:"ヤマト、画面を見たまま、鼻の頭をかく。"},{w:null,t:"三本の柱を丸い輪でかこんだ形。"},{w:null,t:"印の下に、「白い都の大会より　世界大会　出場決定」。"},{w:null,t:"ヤマト、印を二度見する。目が、まん丸になる。"},{w:"hero",f:"serious",t:"……世界大会。",v:"22_0261"},{w:null,t:"肩のフォルン、ヤマトの手首の画面に、前足をぽんと置く。"},{w:null,t:"「キャウ！」。"},{w:null,t:"肩のフォルンが、ヤマトの肩をけって、屋上の空へ高く跳ぶ。"},{w:null,t:"宙で一回転。しっぽの火が大きな輪になって、ぱあっと散る。"},{w:null,t:"ヤマト、両手を上げて、落ちてくるフォルンを胸で受けとめる。"},{w:"alek",t:"（うしろから）世界て。どこでやんねん。",v:"22_0268"},{w:"hero",t:"知らねえ。どこでも行く。な、フォルン。",v:"22_0269"},{w:null,t:"腕の中のフォルン、ヤマトのほっぺに、自分から鼻先をくっつける。"},{w:"elly",t:"フォルン、花火みたいだった！",v:"22_0271"},{w:"hero",f:"smile",t:"……すっげー。エリー、これ見ろ！",v:"22_0278"},{w:"elly",t:"ねえ、竜の横に、字がある。",v:"22_0280"},{w:"hero",t:"マジか！　読めんのか？",v:"22_0281"},{w:"elly",f:"serious",t:"……まだ。見たことない形。",v:"22_0282"},{w:"hero",t:"次は、中国だ。",v:"22_0284"},{w:"hero",t:"アレク。金、数えといて。",v:"22_0285"},{w:"alek",t:"なんでおれやねん……",v:"22_0286"},{w:"alek",t:"……行きの分は、あるわ。",v:"22_0289"},{w:"elly",t:"今日のラッキーアイテム、古い字の書いてある物だって！",v:"22_0294"},{w:"elly",f:"serious",t:"……もう。いいもん。",v:"22_0296"},{w:"hero",t:"（大きくなった字を見て）当たってんじゃん、占い。",v:"22_0299"}];
GR_BT[22]={mid:[[{w:null,t:"ヤマトが歩いてくる。"},{w:"dimi",t:"一回だけ。",v:"22_0169"},{w:"hero",t:"やろうぜ。",v:"22_0170"},{w:null,t:"ヤマト、左の手首の画面を、フォルンへかざす。"},{w:"hero",t:"フォルン、進化！",v:"22_0174"},{w:null,t:"ヤマト、手前の白い線の外まで下がる。"},{w:null,t:"ヤマト、フォルレオンの背中だけを見ている。"},{w:"alek",t:"（となりのエリーに、小さく）……あいつ、半分、闇やん。",v:"22_0184"}]],post:[{w:null,t:"ヤマトの手のひらは、立てたまま。"},{w:null,t:"ほこりの壁を割って、バジリクが顔を出す。"},{w:null,t:"芝のふるえが止まる。"},{w:"dimi",f:"serious",t:"……次も、やる。",v:"22_0206"},{w:"hero",t:"次も、勝つ。",v:"22_0207"}]};
GR_EP[22]={"t": "オリーブの坂", "sc": [["g22_01", "運河の町の橋のたもと（決戦の日の夕方）", 0], ["g22_02", "ホテルのロビー→丘の上・研究所あとの前（朝）", 0], ["g22_03", "坂の曲がり角", 0], ["g22_04", "村と白い都（数日あと）", 0], ["g22_05", "空港の前の芝生（昼）", 1], ["g22_06", "空港の待合（昼）", 0], ["g22_07", "空港の屋上の見送りの場所（夕方）", 0]]};
